INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('1', 'hSD01-001', 'oshiCharacter', 'OSR', NULL, 'hSD01/hSD01-001_OSR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-001_OSR.png', NULL, 5, NULL, NULL, 'でいりー', 'ときのそら', '{"card_sets":["スタートデッキ「ときのそら＆AZKi」"],"color_codes":["white"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Tokino Sora","oshi_skill":{"effect":"[1/Turn]Reattach 1 cheer from your stage to 1 of your holomem.","name":"Replacement"},"sp_oshi_skill":{"effect":"[1/Game]Swap your opponent''s center holomem with 1 back holomem. During this turn, your white center holomem gets Arts+50.","name":"So, that Makes You My Enemy?"}},"es":{"name":"ときのそら","oshi_skill":{"effect":"[Una vez por turno] Cambia una carta de Apoyo en tu Escenario y asígnala a tu Holomen.","name":"Reemplazo"},"sp_oshi_skill":{"effect":"[Una vez por partida] Intercambia el Holomen central y un Holomen de respaldo del oponente. Luego, durante este turno, los Artes de tu Holomen central blanco obtienen +50.","name":"¿Entonces eres mi enemigo?"}},"id":{"name":"ときのそら","oshi_skill":{"effect":"[ターンに１回]Ubah satu kartu Yell di panggungmu dan pasangkan ke Holomenmu.","name":"リプレイスメント"},"sp_oshi_skill":{"effect":"[ゲームに１回]Tukar Center Holomen lawan dengan satu Back Holomen lawan. Setelah itu, hingga akhir giliran ini, Arts Center Putih-mu +50.","name":"じゃあ敵だね？"}},"ja":{"name":"ときのそら","oshi_skill":{"effect":"[ターンに1回]自分のステージのエール1枚を、自分のホロメンに付け替える。","name":"リプレイスメント","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]相手のセンターホロメンとバックホロメン1人を交代させる。その後、このターンの間、自分の白センターホロメンのアーツ+50。","name":"じゃあ敵だね？","timing":"ゲームに1回"}},"ko":{"name":"ときのそら","oshi_skill":{"effect":"[턴에 1번] 자신의 스테이지에 있는 에일 1장을 자신의 홀로멘에게 갈아낀다.","name":"리플레이스먼트"},"sp_oshi_skill":{"effect":"[게임에 1번] 상대의 센터 홀로멘과 백 홀로멘 1명을 교대시킨다. 그 후, 이번 턴 동안 자신의 흰색 센터 홀로멘의 아츠 +50.","name":"그럼 적이네?"}},"tc":{"name":"ときのそら","oshi_skill":{"effect":"[每回合1次]將自己舞台上的1張應援，改附加到自己的任一位Holomen上。","name":"替換"},"sp_oshi_skill":{"effect":"[每場遊戲1次]讓對手的中央Holomen與1位後排Holomen互換位置。之後，直到回合結束為止，自己的白色中央Holomen的藝能+50。","name":"那就是敵人了？"}},"th":{"name":"ときのそら","oshi_skill":{"effect":"[ターンに１回] วางแทน เอール 1 ใบ บนสเตจของตัวเอง ไปยัง ホロメン ของตัวเอง","name":"リプレイスメント"},"sp_oshi_skill":{"effect":"[ゲームに１回] สลับ ホロメン ที่เป็นセンターของฝ่ายตรงข้ามกับ ホロメン 1 คนที่เป็นバック จากนั้น ในช่วงเทิร์นนี้ アーツ ของ 白センター ホロメン ของตัวเอง +50","name":"じゃあ敵だね？"}}}}', '{"en":[{"answer":"Yes, it can be used.You will resolve only ''During this turn, your white center holomem gets Arts+50.'' without resolving ''Swap your opponent''s center holomem with 1 back holomem. ''.","question":"Regarding hSD01-001〈Tokino Sora〉''s SP Oshi skill ''So, that Makes You My Enemy?'', can it be used when opponent has no center holomem or back holomem?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001: Tokino Sora]"},"title":"Q204（October 04, 2024）"},{"answer":"Yes, it is possible.","question":"Regarding hSD01-001〈Tokino Sora〉''s SP Oshi skill ''So, that Makes You My Enemy?'', can resting holomem be chosen when swapping opponent''s center holomem and back holomem?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001: Tokino Sora]"},"title":"Q203（October 04, 2024）"},{"answer":"The player who used ''So, That Makes You My Enemy?'' will choose.","question":"When the turn player uses SP Oshi skill ''So, that Makes You My Enemy?'', who chooses the back holomem to swap?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001: Tokino Sora]"},"title":"Q118（September 21, 2024）"},{"answer":"Yes, it can be used.","question":"Can hSD01-001〈Tokino Sora〉''s Oshi skill ''Replacement'' be used even if there is no cheer on the stage?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001: Tokino Sora]"},"title":"Q1（September 21, 2024）"}],"es":[{"answer":"Sí, puedes usarla. Para resolver el efecto tanto como sea posible, la parte de “Intercambia el Holomen central y un Holomen de respaldo del oponente” no se resuelve, y solo se resuelve la parte “Luego, durante este turno, los Artes de tu Holomen central blanco obtienen +50.”","question":"Con respecto a la habilidad SP Oshi Skill “¿Entonces eres mi enemigo?” de hSD01-001〈ときのそら〉, si el oponente no tiene un Holomen central o no tiene Holomen de respaldo, ¿puedo usar esta habilidad SP Oshi Skill?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q204（2024.10.04）"},{"answer":"Sí, puedes hacerlo.","question":"Con respecto a la habilidad SP Oshi Skill “¿Entonces eres mi enemigo?” de hSD01-001〈ときのそら〉, cuando intercambias el Holomen central y el Holomen de respaldo del oponente, ¿puedes elegir un Holomen que esté descansando?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q203（2024.10.04）"},{"answer":"Lo elige el jugador del turno que usó “¿Entonces eres mi enemigo?”.","question":"Cuando el jugador del turno usa la habilidad SP Oshi Skill “¿Entonces eres mi enemigo?”, ¿quién elige al Holomen de respaldo que se intercambiará?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q118（2024.09.21）"},{"answer":"Sí, puedes usarla.","question":"¿Se puede usar la habilidad Oshi Skill “Reemplazo” de hSD01-001〈ときのそら〉 incluso si no hay cartas de Apoyo en el Escenario?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q1（2024.09.21）"}],"id":[{"answer":"Ya, bisa digunakan. Untuk menyelesaikan efek sejauh mungkin, bagian \"Tukar Center Holomen lawan dengan satu Back Holomen lawan.\" tidak akan diselesaikan, dan hanya bagian \"Setelah itu, hingga akhir giliran ini, Arts Center Putih-mu +50.\" yang akan diselesaikan.","question":"Tentang SP Oshi Skill hSD01-001〈ときのそら〉 \"じゃあ敵だね？\": jika tidak ada Center Holomen atau tidak ada Back Holomen di panggung lawan, apakah SP Oshi Skill ini masih bisa digunakan?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q204（2024.10.04）"},{"answer":"Ya, boleh.","question":"Tentang SP Oshi Skill hSD01-001〈ときのそら〉 \"じゃあ敵だね？\": saat menukar Center Holomen dan Back Holomen lawan, bolehkah memilih Holomen yang sedang istirahat?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q203（2024.10.04）"},{"answer":"Pemain yang menggunakan \"じゃあ敵だね？\" pada giliran tersebut.","question":"Saat pemain giliran menggunakan SP Oshi Skill \"じゃあ敵だね？\", siapa yang memilih Back Holomen yang akan ditukar?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q118（2024.09.21）"},{"answer":"Ya, bisa digunakan.","question":"Apakah Oshi Skill hSD01-001〈ときのそら〉 \"リプレイスメント\" bisa digunakan meskipun tidak ada Yell di panggung?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q1（2024.09.21）"}],"ja":[{"answer":"はい、使用できます。可能な限り効果を解決するため「相手のセンターホロメンとバックホロメン１人を交代させる。」については解決せず、「その後、このターンの間、自分の白センターホロメンのアーツ+50。」の部分のみ解決します。","question":"hSD01-001〈ときのそら〉のSP推しスキル「じゃあ敵だね？」について、相手のステージにセンターホロメンがいない場合や、バックホロメンがいない場合に、このSP推しスキルを使用することはできますか。","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q204（2024.10.04）"},{"answer":"はい、できます。","question":"hSD01-001〈ときのそら〉のSP推しスキル「じゃあ敵だね？」について、相手のセンターホロメンとバックホロメンを交代させる時、お休みしているホロメンを選ぶことはできますか？","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q203（2024.10.04）"},{"answer":"「じゃあ敵だね？」を使ったターンプレイヤーになります。","question":"ターンプレイヤーがSP推しスキル「じゃあ敵だね？」を使った時、交代させるバックホロメンを選ぶのはどちらのプレイヤーですか？","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q118（2024.09.21）"},{"answer":"はい、使用できます。","question":"hSD01-001〈ときのそら〉の推しスキル「リプレイスメント」はステージにエールが無くても使用できますか？","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q1（2024.09.21）"}],"ko":[{"answer":"네, 사용할 수 있습니다. 가능한 범위에서 효과를 해결하기 때문에 「상대의 센터 홀로멘과 백 홀로멘 1명을 교대시킨다.」 부분은 해결하지 않고, 「그 후, 이번 턴 동안 자신의 흰색 센터 홀로멘의 아츠 +50.」 부분만 해결합니다.","question":"hSD01-001〈ときのそら〉의 SP 오시 스킬 「그럼 적이네?」에 대해, 상대 스테이지에 센터 홀로멘이 없거나 백 홀로멘이 없을 경우에도 이 SP 오시 스킬을 사용할 수 있나요?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q204（2024.10.04）"},{"answer":"네, 가능합니다.","question":"hSD01-001〈ときのそら〉의 SP 오시 스킬 「그럼 적이네?」에 대해, 상대의 센터 홀로멘과 백 홀로멘을 교대시킬 때 휴식 중인 홀로멘을 선택할 수 있나요?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q203（2024.10.04）"},{"answer":"「그럼 적이네?」를 사용한 턴 플레이어입니다.","question":"턴 플레이어가 SP 오시 스킬 「그럼 적이네?」를 사용했을 때, 교대시킬 백 홀로멘을 선택하는 것은 어느 플레이어인가요?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q118（2024.09.21）"},{"answer":"네, 사용할 수 있습니다.","question":"hSD01-001〈ときのそら〉의 오시 스킬 「리플레이스먼트」는 스테이지에 에일이 없어도 사용할 수 있나요?","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q1（2024.09.21）"}],"tc":[{"answer":"可以使用。為了盡可能解決效果，「讓對手的中央Holomen與1位後排Holomen互換位置。」這部分將不會解決，只會解決「之後，直到回合結束為止，自己的白色中央Holomen的藝能+50。」這部分。","question":"關於 hSD01-001〈ときのそら〉的SP推し技能「那就是敵人了？」如果對手舞台上沒有中央Holomen，或是沒有後排Holomen，能使用這個SP推し技能嗎？","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q204（2024.10.04）"},{"answer":"可以。","question":"關於 hSD01-001〈ときのそら〉的SP推し技能「那就是敵人了？」在讓對手的中央Holomen與後排Holomen互換位置時，可以選擇休息中的Holomen嗎？","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q203（2024.10.04）"},{"answer":"是使用「那就是敵人了？」的回合玩家選擇。","question":"當回合玩家使用SP推し技能「那就是敵人了？」時，選擇要互換位置的後排Holomen的是哪一位玩家？","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q118（2024.09.21）"},{"answer":"可以使用。","question":"hSD01-001〈ときのそら〉的推し技能「替換」在舞台上沒有應援時也能使用嗎？","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q1（2024.09.21）"}],"th":[{"answer":"ได้ สามารถใช้ได้ ในส่วนของการพยายามแก้ผลให้มากที่สุด ถ้าส่วนที่ว่า “สลับ センターホロメン ของฝ่ายตรงข้าม กับ バックホロメン 1 คน” ไม่สามารถแก้ได้ จะข้ามส่วนนั้นไป และแก้เฉพาะส่วนที่ว่า “จากนั้น ในช่วงเทิร์นนี้ アーツ ของ 白センター ホロメン ของตัวเอง +50”","question":"เกี่ยวกับ SP 推しスキル 「じゃあ敵だね？」 ของ hSD01-001〈ときのそら〉 ถ้าฝั่งตรงข้ามไม่มี センターホロメン บนสเตจ หรืไม่มี バックホロメン จะสามารถใช้สกิลนี้ได้ไหม","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q204（2024.10.04）"},{"answer":"ได้ สามารถเลือกได้","question":"เกี่ยวกับ SP 推しスキル 「じゃあ敵だね？」 ของ hSD01-001〈ときのそら〉 เมื่อต้องสลับ センターホロメン กับ バックホロメン ของฝ่ายตรงข้าม สามารถเลือก ホロメン ที่อยู่ในสถานะพัก (お休み) ได้หรือไม่","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q203（2024.10.04）"},{"answer":"ผู้เล่นที่ใช้ 「じゃあ敵だね？」 ในเทิร์นนั้น เป็นผู้เลือก","question":"เมื่อผู้เล่นที่กำลังเป็นเทิร์นใช้ SP 推しスキル 「じゃあ敵だね？」 ผู้เล่นคนไหนเป็นคนเลือก バックホロメン ที่จะถูกสลับ","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q118（2024.09.21）"},{"answer":"ได้ สามารถใช้ได้","question":"เกี่ยวกับ 推しスキル 「リプレイスメント」 ของ hSD01-001〈ときのそら〉 ถ้าบนสเตจไม่มี エール จะยังใช้สกิลนี้ได้ไหม","related_cards":{"card_number":["hSD01-001"],"raw_html":"[hSD01-001 ： ときのそら]"},"title":"Q1（2024.09.21）"}]}', 'eb4be8f7cbae4bf07fab1b4c18696e95662a060c08a3889b9ccc31f08f515281', 'a9cbc5880794739dfd3eca69a8c9b7f2cbd4fb42582ac1cc5aa44ece409b69f4', '1970-01-01T00:00:00Z');
INSERT INTO card_colors (color_code, card_id) VALUES ('white', '1');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ「ときのそら＆AZKi」', '1');
INSERT INTO cards_fts (rowid, card_number, text) VALUES (1, 'hSD01-001', 'hSD01-001 でいりー ときのそら リプレイスメント [ターンに1回]自分のステージのエール1枚を、自分のホロメンに付け替える。 じゃあ敵だね？ [ゲームに1回]相手のセンターホロメンとバックホロメン1人を交代させる。その後、このターンの間、自分の白センターホロメンのアーツ+50。 Q204（2024.10.04） hSD01-001〈ときのそら〉のSP推しスキル「じゃあ敵だね？」について、相手のステージにセンターホロメンがいない場合や、バックホロメンがいない場合に、このSP推しスキルを使用することはできますか。 はい、使用できます。可能な限り効果を解決するため「相手のセンターホロメンとバックホロメン１人を交代させる。」については解決せず、「その後、このターンの間、自分の白センターホロメンのアーツ+50。」の部分のみ解決します。 Q203（2024.10.04） hSD01-001〈ときのそら〉のSP推しスキル「じゃあ敵だね？」について、相手のセンターホロメンとバックホロメンを交代させる時、お休みしているホロメンを選ぶことはできますか？ はい、できます。 Q118（2024.09.21） ターンプレイヤーがSP推しスキル「じゃあ敵だね？」を使った時、交代させるバックホロメンを選ぶのはどちらのプレイヤーですか？ 「じゃあ敵だね？」を使ったターンプレイヤーになります。 Q1（2024.09.21） hSD01-001〈ときのそら〉の推しスキル「リプレイスメント」はステージにエールが無くても使用できますか？ はい、使用できます。 Tokino Sora Replacement [1/Turn]Reattach 1 cheer from your stage to 1 of your holomem. So, that Makes You My Enemy? [1/Game]Swap your opponent''s center holomem with 1 back holomem. During this turn, your white center holomem gets Arts+50. Q204（October 04, 2024） Regarding hSD01-001〈Tokino Sora〉''s SP Oshi skill ''So, that Makes You My Enemy?'', can it be used when opponent has no center holomem or back holomem? Yes, it can be used.You will resolve only ''During this turn, your white center holomem gets Arts+50.'' without resolving ''Swap your opponent''s center holomem with 1 back holomem. ''. Q203（October 04, 2024） Regarding hSD01-001〈Tokino Sora〉''s SP Oshi skill ''So, that Makes You My Enemy?'', can resting holomem be chosen when swapping opponent''s center holomem and back holomem? Yes, it is possible. Q118（September 21, 2024） When the turn player uses SP Oshi skill ''So, that Makes You My Enemy?'', who chooses the back holomem to swap? The player who used ''So, That Makes You My Enemy?'' will choose. Q1（September 21, 2024） Can hSD01-001〈Tokino Sora〉''s Oshi skill ''Replacement'' be used even if there is no cheer on the stage? Yes, it can be used. ときのそら 替換 [每回合1次]將自己舞台上的1張應援，改附加到自己的任一位Holomen上。 那就是敵人了？ [每場遊戲1次]讓對手的中央Holomen與1位後排Holomen互換位置。之後，直到回合結束為止，自己的白色中央Holomen的藝能+50。 Q204（2024.10.04） 關於 hSD01-001〈ときのそら〉的SP推し技能「那就是敵人了？」如果對手舞台上沒有中央Holomen，或是沒有後排Holomen，能使用這個SP推し技能嗎？ 可以使用。為了盡可能解決效果，「讓對手的中央Holomen與1位後排Holomen互換位置。」這部分將不會解決，只會解決「之後，直到回合結束為止，自己的白色中央Holomen的藝能+50。」這部分。 Q203（2024.10.04） 關於 hSD01-001〈ときのそら〉的SP推し技能「那就是敵人了？」在讓對手的中央Holomen與後排Holomen互換位置時，可以選擇休息中的Holomen嗎？ 可以。 Q118（2024.09.21） 當回合玩家使用SP推し技能「那就是敵人了？」時，選擇要互換位置的後排Holomen的是哪一位玩家？ 是使用「那就是敵人了？」的回合玩家選擇。 Q1（2024.09.21） hSD01-001〈ときのそら〉的推し技能「替換」在舞台上沒有應援時也能使用嗎？ 可以使用。 ときのそら リプレイスメント [ターンに１回]Ubah satu kartu Yell di panggungmu dan pasangkan ke Holomenmu. じゃあ敵だね？ [ゲームに１回]Tukar Center Holomen lawan dengan satu Back Holomen lawan. Setelah itu, hingga akhir giliran ini, Arts Center Putih-mu +50. Q204（2024.10.04） Tentang SP Oshi Skill hSD01-001〈ときのそら〉 "じゃあ敵だね？": jika tidak ada Center Holomen atau tidak ada Back Holomen di panggung lawan, apakah SP Oshi Skill ini masih bisa digunakan? Ya, bisa digunakan. Untuk menyelesaikan efek sejauh mungkin, bagian "Tukar Center Holomen lawan dengan satu Back Holomen lawan." tidak akan diselesaikan, dan hanya bagian "Setelah itu, hingga akhir giliran ini, Arts Center Putih-mu +50." yang akan diselesaikan. Q203（2024.10.04） Tentang SP Oshi Skill hSD01-001〈ときのそら〉 "じゃあ敵だね？": saat menukar Center Holomen dan Back Holomen lawan, bolehkah memilih Holomen yang sedang istirahat? Ya, boleh. Q118（2024.09.21） Saat pemain giliran menggunakan SP Oshi Skill "じゃあ敵だね？", siapa yang memilih Back Holomen yang akan ditukar? Pemain yang menggunakan "じゃあ敵だね？" pada giliran tersebut. Q1（2024.09.21） Apakah Oshi Skill hSD01-001〈ときのそら〉 "リプレイスメント" bisa digunakan meskipun tidak ada Yell di panggung? Ya, bisa digunakan. ときのそら 리플레이스먼트 [턴에 1번] 자신의 스테이지에 있는 에일 1장을 자신의 홀로멘에게 갈아낀다. 그럼 적이네? [게임에 1번] 상대의 센터 홀로멘과 백 홀로멘 1명을 교대시킨다. 그 후, 이번 턴 동안 자신의 흰색 센터 홀로멘의 아츠 +50. Q204（2024.10.04） hSD01-001〈ときのそら〉의 SP 오시 스킬 「그럼 적이네?」에 대해, 상대 스테이지에 센터 홀로멘이 없거나 백 홀로멘이 없을 경우에도 이 SP 오시 스킬을 사용할 수 있나요? 네, 사용할 수 있습니다. 가능한 범위에서 효과를 해결하기 때문에 「상대의 센터 홀로멘과 백 홀로멘 1명을 교대시킨다.」 부분은 해결하지 않고, 「그 후, 이번 턴 동안 자신의 흰색 센터 홀로멘의 아츠 +50.」 부분만 해결합니다. Q203（2024.10.04） hSD01-001〈ときのそら〉의 SP 오시 스킬 「그럼 적이네?」에 대해, 상대의 센터 홀로멘과 백 홀로멘을 교대시킬 때 휴식 중인 홀로멘을 선택할 수 있나요? 네, 가능합니다. Q118（2024.09.21） 턴 플레이어가 SP 오시 스킬 「그럼 적이네?」를 사용했을 때, 교대시킬 백 홀로멘을 선택하는 것은 어느 플레이어인가요? 「그럼 적이네?」를 사용한 턴 플레이어입니다. Q1（2024.09.21） hSD01-001〈ときのそら〉의 오시 스킬 「리플레이스먼트」는 스테이지에 에일이 없어도 사용할 수 있나요? 네, 사용할 수 있습니다. ときのそら リプレイスメント [ターンに１回] วางแทน เอール 1 ใบ บนสเตจของตัวเอง ไปยัง ホロメン ของตัวเอง じゃあ敵だね？ [ゲームに１回] สลับ ホロメン ที่เป็นセンターของฝ่ายตรงข้ามกับ ホロメン 1 คนที่เป็นバック จากนั้น ในช่วงเทิร์นนี้ アーツ ของ 白センター ホロメン ของตัวเอง +50 Q204（2024.10.04） เกี่ยวกับ SP 推しスキル 「じゃあ敵だね？」 ของ hSD01-001〈ときのそら〉 ถ้าฝั่งตรงข้ามไม่มี センターホロメン บนสเตจ หรืไม่มี バックホロメン จะสามารถใช้สกิลนี้ได้ไหม ได้ สามารถใช้ได้ ในส่วนของการพยายามแก้ผลให้มากที่สุด ถ้าส่วนที่ว่า “สลับ センターホロメン ของฝ่ายตรงข้าม กับ バックホロメン 1 คน” ไม่สามารถแก้ได้ จะข้ามส่วนนั้นไป และแก้เฉพาะส่วนที่ว่า “จากนั้น ในช่วงเทิร์นนี้ アーツ ของ 白センター ホロメン ของตัวเอง +50” Q203（2024.10.04） เกี่ยวกับ SP 推しスキル 「じゃあ敵だね？」 ของ hSD01-001〈ときのそら〉 เมื่อต้องสลับ センターホロメン กับ バックホロメン ของฝ่ายตรงข้าม สามารถเลือก ホロメン ที่อยู่ในสถานะพัก (お休み) ได้หรือไม่ ได้ สามารถเลือกได้ Q118（2024.09.21） เมื่อผู้เล่นที่กำลังเป็นเทิร์นใช้ SP 推しスキル 「じゃあ敵だね？」 ผู้เล่นคนไหนเป็นคนเลือก バックホロメン ที่จะถูกสลับ ผู้เล่นที่ใช้ 「じゃあ敵だね？」 ในเทิร์นนั้น เป็นผู้เลือก Q1（2024.09.21） เกี่ยวกับ 推しスキル 「リプレイスメント」 ของ hSD01-001〈ときのそら〉 ถ้าบนสเตจไม่มี エール จะยังใช้สกิลนี้ได้ไหม ได้ สามารถใช้ได้ ときのそら Reemplazo [Una vez por turno] Cambia una carta de Apoyo en tu Escenario y asígnala a tu Holomen. ¿Entonces eres mi enemigo? [Una vez por partida] Intercambia el Holomen central y un Holomen de respaldo del oponente. Luego, durante este turno, los Artes de tu Holomen central blanco obtienen +50. Q204（2024.10.04） Con respecto a la habilidad SP Oshi Skill “¿Entonces eres mi enemigo?” de hSD01-001〈ときのそら〉, si el oponente no tiene un Holomen central o no tiene Holomen de respaldo, ¿puedo usar esta habilidad SP Oshi Skill? Sí, puedes usarla. Para resolver el efecto tanto como sea posible, la parte de “Intercambia el Holomen central y un Holomen de respaldo del oponente” no se resuelve, y solo se resuelve la parte “Luego, durante este turno, los Artes de tu Holomen central blanco obtienen +50.” Q203（2024.10.04） Con respecto a la habilidad SP Oshi Skill “¿Entonces eres mi enemigo?” de hSD01-001〈ときのそら〉, cuando intercambias el Holomen central y el Holomen de respaldo del oponente, ¿puedes elegir un Holomen que esté descansando? Sí, puedes hacerlo. Q118（2024.09.21） Cuando el jugador del turno usa la habilidad SP Oshi Skill “¿Entonces eres mi enemigo?”, ¿quién elige al Holomen de respaldo que se intercambiará? Lo elige el jugador del turno que usó “¿Entonces eres mi enemigo?”. Q1（2024.09.21） ¿Se puede usar la habilidad Oshi Skill “Reemplazo” de hSD01-001〈ときのそら〉 incluso si no hay cartas de Apoyo en el Escenario? Sí, puedes usarla.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('2', 'hSD01-002', 'oshiCharacter', 'OSR', NULL, 'hSD01/hSD01-002_OSR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-002_OSR.png', NULL, 6, NULL, NULL, 'Hachi', 'AZKi', '{"card_sets":["スタートデッキ「ときのそら＆AZKi」"],"color_codes":["green"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"AZKi","oshi_skill":{"effect":"[1/Turn]Usable if your holomem''s ability would roll a die：Declare 1 of the face numbers of the die, and regard the next result as the declared number.","name":"A Map in My Left Hand"},"sp_oshi_skill":{"effect":"[1/Game]Send any number of cheers from your archive to 1 of your green holomem.","name":"A Mic in My Right Hand"}},"es":{"name":"AZKi","oshi_skill":{"effect":"[Una vez por turno] Puedes usarlo cuando lances un dado por una habilidad de tu Holomen: declara un número del dado, y el siguiente resultado del dado se tratará como el número declarado.","name":"Mapa en la mano izquierda"},"sp_oshi_skill":{"effect":"[Una vez por partida] Envía cualquier número de cartas de Ánimo desde tu Archivo a un Holomen verde de tu elección.","name":"Micrófono en la mano derecha"}},"id":{"name":"AZKi","oshi_skill":{"effect":"[Sekali per giliran] Dapat digunakan ketika menggunakan kemampuan salah satu Holomen-mu yang melempar dadu: nyatakan satu angka hasil dadu, dan angka hasil lemparan berikutnya dianggap sebagai angka yang dinyatakan.","name":"左手に地図"},"sp_oshi_skill":{"effect":"[Sekali per game] Kirim sebanyak kartu Eru dari Arsip-mu ke satu Holomen hijau yang kamu pilih.","name":"右手にマイク"}},"ja":{"name":"AZKi","oshi_skill":{"effect":"[ターンに1回]自分のホロメンの能力でサイコロを振る時に使える:サイコロの目の数１つを宣言し、次に出る目の数を宣言した目として扱う。","name":"左手に地図","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]自分のアーカイブのエールを自分の緑ホロメン1人に好きな枚数送る。","name":"右手にマイク","timing":"ゲームに1回"}},"ko":{"name":"AZKi","oshi_skill":{"effect":"[턴당 1번] 자신의 홀로멘 능력으로 주사위를 굴릴 때 사용할 수 있음: 주사위 눈의 숫자 하나를 선언하고, 다음에 나오는 눈을 선언한 눈으로 취급한다.","name":"왼손에 지도"},"sp_oshi_skill":{"effect":"[게임당 1번] 자신의 아카이브에 있는 응원을 원하는 만큼 자신의 초록 홀로멘 1명에게 보낸다.","name":"오른손에 마이크"}},"tc":{"name":"AZKi","oshi_skill":{"effect":"[每回合1次] 當自己的Holomen能力要擲骰時可以使用：宣告一個數字，並將下一次擲出的骰子點數視為所宣告的數字。","name":"左手握著地圖"},"sp_oshi_skill":{"effect":"[每場遊戲1次] 從自己的檔案區域中，將任意數量的應援送給自己的一位綠色Holomen。","name":"右手握著麥克風"}},"th":{"name":"AZKi","oshi_skill":{"effect":"[เทิร์นละ 1 ครั้ง] เมื่อใช้ความสามารถของโฮโลเมนของตนเพื่อลงลูกเต๋า: ประกาศจำนวนแต้มบนลูกเต๋า 1 ค่า แล้วนับแต้มของการทอยครั้งถัดไปเป็นค่าที่ประกาศไว้","name":"左手に地図"},"sp_oshi_skill":{"effect":"[เกมละ 1 ครั้ง] ส่งไอเอールจากอาร์ไคฟ์ของตนไปยังโฮโลเมนสีเขียวของตน 1 คน ตามจำนวนที่ต้องการ","name":"右手にマイク"}}}}', '{"en":[{"answer":"Yes, it is possible.","question":"If your Oshi holomem is hSD01-002〈AZKi〉 and you use hBP01-027〈Vestia Zeta〉''s gift ''V.7'' when your holomem takes damage, can you declare the die roll using hSD01-002〈AZKi〉''s Oshi skill ''A Map in My Left Hand''?","related_cards":{"card_number":["hSD01-002","hBP01-027"],"raw_html":"[hSD01-002: AZKi]\n[hBP01-027: Vestia Zeta]"},"title":"Q221（October 23, 2024）"},{"answer":"Yes, it can be used.","question":"Can hSD01-002〈AZKi〉''s SP Oshi skill ''A Mic in My Right Hand'' be used even if there is no cheer in the archive?","related_cards":{"card_number":["hSD01-002"],"raw_html":"[hSD01-002: AZKi]"},"title":"Q2（September 21, 2024）"}],"es":[{"answer":"Sí, puedes hacerlo.","question":"Cuando tu Holomen favorito es hSD01-002〈AZKi〉 y tu Holomen recibe daño, usas el regalo “V.7” de hBP01-027〈ベスティア・ゼータ〉. En este caso, ¿puedes declarar el número del dado usando la habilidad 推し de hSD01-002〈AZKi〉 “Mapa en la mano izquierda”?","related_cards":{"card_number":["hSD01-002","hBP01-027"],"raw_html":"[hSD01-002 ： AZKi]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"P221（2024.10.23）"},{"answer":"Sí, se puede usar.","question":"¿Se puede usar la habilidad SP 推し de hSD01-002〈AZKi〉 “Micrófono en la mano derecha” aunque no haya cartas de Ánimo en el Archivo?","related_cards":{"card_number":["hSD01-002"],"raw_html":"[hSD01-002 ： AZKi]"},"title":"P2（2024.09.21）"}],"id":[{"answer":"Ya, bisa.","question":"Jika oshi Holomen saya adalah hSD01-002〈AZKi〉, dan Holomen saya menerima damage serta hadiah \"V.7\" dari hBP01-027〈ベスティア・ゼータ〉 digunakan. Dalam kasus ini, dapatkah saya menggunakan oshi skill hSD01-002〈AZKi〉 \"左手に地図\" untuk menegaskan angka hasil dadu?","related_cards":{"card_number":["hSD01-002","hBP01-027"],"raw_html":"[hSD01-002 ： AZKi]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q221（2024.10.23）"},{"answer":"Ya, bisa digunakan.","question":"Apakah SP oshi skill hSD01-002〈AZKi〉 \"右手にマイク\" bisa digunakan meskipun tidak ada Eru di Arsip?","related_cards":{"card_number":["hSD01-002"],"raw_html":"[hSD01-002 ： AZKi]"},"title":"Q2（2024.09.21）"}],"ja":[{"answer":"はい、できます。","question":"自分の推しホロメンがhSD01-002〈AZKi〉で、自分のホロメンがダメージを受ける時、hBP01-027〈ベスティア・ゼータ〉のギフト「V.7」を使用しました。この場合、hSD01-002〈AZKi〉の推しスキル「左手に地図」を使用して出る目の数を宣言することはできますか。","related_cards":{"card_number":["hSD01-002","hBP01-027"],"raw_html":"[hSD01-002 ： AZKi]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q221（2024.10.23）"},{"answer":"はい、使用できます。","question":"hSD01-002〈AZKi〉のSP推しスキル「右手にマイク」はアーカイブにエールが無くても使用できますか？","related_cards":{"card_number":["hSD01-002"],"raw_html":"[hSD01-002 ： AZKi]"},"title":"Q2（2024.09.21）"}],"ko":[{"answer":"네, 가능합니다.","question":"자신의 오시 홀로멘이 hSD01-002〈AZKi〉이고, 자신의 홀로멘이 피해를 받을 때 hBP01-027〈베스티아・제타〉의 선물 ‘V.7’을 사용했습니다. 이 경우, hSD01-002〈AZKi〉의 오시 스킬 ‘왼손에 지도’를 사용해 나올 눈을 선언할 수 있나요?","related_cards":{"card_number":["hSD01-002","hBP01-027"],"raw_html":"[hSD01-002 ： AZKi]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q221（2024.10.23）"},{"answer":"네, 사용할 수 있습니다.","question":"hSD01-002〈AZKi〉의 SP 오시 스킬 ‘오른손에 마이크’는 아카이브에 응원이 없어도 사용할 수 있나요?","related_cards":{"card_number":["hSD01-002"],"raw_html":"[hSD01-002 ： AZKi]"},"title":"Q2（2024.09.21）"}],"tc":[{"answer":"可以。","question":"當自己的推しHolomen是hSD01-002〈AZKi〉，自己的Holomen受到傷害時，使用了hBP01-027〈ベスティア・ゼータ〉的禮物「V.7」。這種情況下，可以使用hSD01-002〈AZKi〉的推し技能「左手握著地圖」來宣告要出的骰子點數嗎？","related_cards":{"card_number":["hSD01-002","hBP01-027"],"raw_html":"[hSD01-002 ： AZKi]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q221（2024.10.23）"},{"answer":"可以使用。","question":"hSD01-002〈AZKi〉的SP推し技能「右手握著麥克風」在檔案區域中沒有應援時也能使用嗎？","related_cards":{"card_number":["hSD01-002"],"raw_html":"[hSD01-002 ： AZKi]"},"title":"Q2（2024.09.21）"}],"th":[{"answer":"ใช่ สามารถทำได้","question":"กรณีที่โฮโลเมนที่เป็น Oshi ของตนคือ hSD01-002〈AZKi〉 และโฮโลเมนของตนได้รับความเสียหาย แล้วใช้กิฟต์ “V.7” ของ hBP01-027〈ベスティア・ゼータ〉 ในกรณีนี้ สามารถใช้สกิล Oshi ของ hSD01-002〈AZKi〉 「左手に地図」 เพื่อประกาศจำนวนแต้มที่จะออกได้หรือไม่","related_cards":{"card_number":["hSD01-002","hBP01-027"],"raw_html":"[hSD01-002 ： AZKi]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q221（2024.10.23）"},{"answer":"ใช่ ใช้ได้","question":"สกิล SP Oshi ของ hSD01-002〈AZKi〉 「右手にマイク」 สามารถใช้งานได้แม้ในกรณีที่อาร์ไคฟ์ไม่มีไอเอールหรือไม่","related_cards":{"card_number":["hSD01-002"],"raw_html":"[hSD01-002 ： AZKi]"},"title":"Q2（2024.09.21）"}]}', '12046acd4e4e562c92283e19301090407dda23326334565dc285ee774a2ffa0e', '19886cbcc35aa53ede91dd709213798da961d8c2d185ca07a75c066b2a2a839c', '1970-01-01T00:00:00Z');
INSERT INTO card_colors (color_code, card_id) VALUES ('green', '2');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ「ときのそら＆AZKi」', '2');
INSERT INTO cards_fts (rowid, card_number, text) VALUES (2, 'hSD01-002', 'hSD01-002 Hachi AZKi 左手に地図 [ターンに1回]自分のホロメンの能力でサイコロを振る時に使える:サイコロの目の数１つを宣言し、次に出る目の数を宣言した目として扱う。 右手にマイク [ゲームに1回]自分のアーカイブのエールを自分の緑ホロメン1人に好きな枚数送る。 Q221（2024.10.23） 自分の推しホロメンがhSD01-002〈AZKi〉で、自分のホロメンがダメージを受ける時、hBP01-027〈ベスティア・ゼータ〉のギフト「V.7」を使用しました。この場合、hSD01-002〈AZKi〉の推しスキル「左手に地図」を使用して出る目の数を宣言することはできますか。 はい、できます。 Q2（2024.09.21） hSD01-002〈AZKi〉のSP推しスキル「右手にマイク」はアーカイブにエールが無くても使用できますか？ はい、使用できます。 AZKi A Map in My Left Hand [1/Turn]Usable if your holomem''s ability would roll a die：Declare 1 of the face numbers of the die, and regard the next result as the declared number. A Mic in My Right Hand [1/Game]Send any number of cheers from your archive to 1 of your green holomem. Q221（October 23, 2024） If your Oshi holomem is hSD01-002〈AZKi〉 and you use hBP01-027〈Vestia Zeta〉''s gift ''V.7'' when your holomem takes damage, can you declare the die roll using hSD01-002〈AZKi〉''s Oshi skill ''A Map in My Left Hand''? Yes, it is possible. Q2（September 21, 2024） Can hSD01-002〈AZKi〉''s SP Oshi skill ''A Mic in My Right Hand'' be used even if there is no cheer in the archive? Yes, it can be used. AZKi 左手握著地圖 [每回合1次] 當自己的Holomen能力要擲骰時可以使用：宣告一個數字，並將下一次擲出的骰子點數視為所宣告的數字。 右手握著麥克風 [每場遊戲1次] 從自己的檔案區域中，將任意數量的應援送給自己的一位綠色Holomen。 Q221（2024.10.23） 當自己的推しHolomen是hSD01-002〈AZKi〉，自己的Holomen受到傷害時，使用了hBP01-027〈ベスティア・ゼータ〉的禮物「V.7」。這種情況下，可以使用hSD01-002〈AZKi〉的推し技能「左手握著地圖」來宣告要出的骰子點數嗎？ 可以。 Q2（2024.09.21） hSD01-002〈AZKi〉的SP推し技能「右手握著麥克風」在檔案區域中沒有應援時也能使用嗎？ 可以使用。 AZKi 左手に地図 [Sekali per giliran] Dapat digunakan ketika menggunakan kemampuan salah satu Holomen-mu yang melempar dadu: nyatakan satu angka hasil dadu, dan angka hasil lemparan berikutnya dianggap sebagai angka yang dinyatakan. 右手にマイク [Sekali per game] Kirim sebanyak kartu Eru dari Arsip-mu ke satu Holomen hijau yang kamu pilih. Q221（2024.10.23） Jika oshi Holomen saya adalah hSD01-002〈AZKi〉, dan Holomen saya menerima damage serta hadiah "V.7" dari hBP01-027〈ベスティア・ゼータ〉 digunakan. Dalam kasus ini, dapatkah saya menggunakan oshi skill hSD01-002〈AZKi〉 "左手に地図" untuk menegaskan angka hasil dadu? Ya, bisa. Q2（2024.09.21） Apakah SP oshi skill hSD01-002〈AZKi〉 "右手にマイク" bisa digunakan meskipun tidak ada Eru di Arsip? Ya, bisa digunakan. AZKi 왼손에 지도 [턴당 1번] 자신의 홀로멘 능력으로 주사위를 굴릴 때 사용할 수 있음: 주사위 눈의 숫자 하나를 선언하고, 다음에 나오는 눈을 선언한 눈으로 취급한다. 오른손에 마이크 [게임당 1번] 자신의 아카이브에 있는 응원을 원하는 만큼 자신의 초록 홀로멘 1명에게 보낸다. Q221（2024.10.23） 자신의 오시 홀로멘이 hSD01-002〈AZKi〉이고, 자신의 홀로멘이 피해를 받을 때 hBP01-027〈베스티아・제타〉의 선물 ‘V.7’을 사용했습니다. 이 경우, hSD01-002〈AZKi〉의 오시 스킬 ‘왼손에 지도’를 사용해 나올 눈을 선언할 수 있나요? 네, 가능합니다. Q2（2024.09.21） hSD01-002〈AZKi〉의 SP 오시 스킬 ‘오른손에 마이크’는 아카이브에 응원이 없어도 사용할 수 있나요? 네, 사용할 수 있습니다. AZKi 左手に地図 [เทิร์นละ 1 ครั้ง] เมื่อใช้ความสามารถของโฮโลเมนของตนเพื่อลงลูกเต๋า: ประกาศจำนวนแต้มบนลูกเต๋า 1 ค่า แล้วนับแต้มของการทอยครั้งถัดไปเป็นค่าที่ประกาศไว้ 右手にマイク [เกมละ 1 ครั้ง] ส่งไอเอールจากอาร์ไคฟ์ของตนไปยังโฮโลเมนสีเขียวของตน 1 คน ตามจำนวนที่ต้องการ Q221（2024.10.23） กรณีที่โฮโลเมนที่เป็น Oshi ของตนคือ hSD01-002〈AZKi〉 และโฮโลเมนของตนได้รับความเสียหาย แล้วใช้กิฟต์ “V.7” ของ hBP01-027〈ベスティア・ゼータ〉 ในกรณีนี้ สามารถใช้สกิล Oshi ของ hSD01-002〈AZKi〉 「左手に地図」 เพื่อประกาศจำนวนแต้มที่จะออกได้หรือไม่ ใช่ สามารถทำได้ Q2（2024.09.21） สกิล SP Oshi ของ hSD01-002〈AZKi〉 「右手にマイク」 สามารถใช้งานได้แม้ในกรณีที่อาร์ไคฟ์ไม่มีไอเอールหรือไม่ ใช่ ใช้ได้ AZKi Mapa en la mano izquierda [Una vez por turno] Puedes usarlo cuando lances un dado por una habilidad de tu Holomen: declara un número del dado, y el siguiente resultado del dado se tratará como el número declarado. Micrófono en la mano derecha [Una vez por partida] Envía cualquier número de cartas de Ánimo desde tu Archivo a un Holomen verde de tu elección. P221（2024.10.23） Cuando tu Holomen favorito es hSD01-002〈AZKi〉 y tu Holomen recibe daño, usas el regalo “V.7” de hBP01-027〈ベスティア・ゼータ〉. En este caso, ¿puedes declarar el número del dado usando la habilidad 推し de hSD01-002〈AZKi〉 “Mapa en la mano izquierda”? Sí, puedes hacerlo. P2（2024.09.21） ¿Se puede usar la habilidad SP 推し de hSD01-002〈AZKi〉 “Micrófono en la mano derecha” aunque no haya cartas de Ánimo en el Archivo? Sí, se puede usar.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('6', 'hSD01-006', 'buzzCharacter', 'RR', 'first', 'hSD01/hSD01-006_RR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-006_RR.png', 240, NULL, 2, '["null","null"]', 'I☆LA', 'ときのそら', '{"arts":[{"cost_count":2,"cost_types":["white","null"],"damage":50},{"cost_count":3,"cost_types":["white","green","null"],"damage":60,"is_plus":true}],"card_sets":["スタートデッキ「ときのそら＆AZKi」"],"color_codes":["white"],"translations":{"en":{"arts":[{"name":"ドリームライブ"},{"effect":"If there is a Holomen〈AZKi〉on your Stage, this Arts +50.","name":"SorAZ シンパシー"}],"extra":"When this Holomen is downed, your Life -2.","name":"ときのそら","tags":["#JP","#0期生","#歌"]},"es":{"arts":[{"name":"ドリームライブ"},{"effect":"Si tienes en tu escenario a la Holomen〈AZKi〉, este arte obtiene +50.","name":"SorAZ シンパシー"}],"extra":"Cuando este Holomen sea derrotado, tu vida se reduce en 2.","name":"ときのそら","tags":["#JP","#0期生","#歌"]},"id":{"arts":[{"name":"ドリームライブ"},{"effect":"Jika di panggungmu ada holomen dengan label 〈AZKi〉, arts ini +50.","name":"SorAZ シンパシー"}],"extra":"Ketika holomen ini down, nyawamu -2","name":"ときのそら","tags":["#JP","#0期生","#歌"]},"ja":{"arts":[{"name":"ドリームライブ"},{"effect":"自分のステージにホロメンの〈AZKi〉がいる時、このアーツ+50。","name":"SorAZ シンパシー"}],"extra":"このホロメンがダウンした時、自分のライフ-2","name":"ときのそら","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"name":"ドリームライブ"},{"effect":"자신의 스테이지에 홀로멘〈AZKi〉가 있을 때, 이 아츠 +50.","name":"SorAZ シンパシー"}],"extra":"이 홀로멘이 다운될 때, 자신의 라이프 -2","name":"ときのそら","tags":["#JP","#0期生","#歌"]},"tc":{"arts":[{"name":"ドリームライブ"},{"effect":"當自己的舞台上有Holomen〈AZKi〉時，此藝術+50。","name":"SorAZ シンパシー"}],"extra":"當這位Holomen被擊倒時，自身生命值-2","name":"ときのそら","tags":["#JP","#0期生","#歌"]},"th":{"arts":[{"name":"ドリームライブ"},{"effect":"เมื่อบนสเตจของตนมีโฮโลเมนที่เป็น〈AZKi〉ของฝ่ายตน อาร์ตนี้+50。","name":"SorAZ シンパシー"}],"extra":"เมื่อโฮโลเมนคนนี้ล้ม, ชีวิตของตนเอง -2","name":"ときのそら","tags":["#JP","#0期生","#歌"]}}}', '{"en":[{"answer":"Yes, it gets +50. Even if there isn’t a card with the exact name, if there is a card whose Extra ability says something like “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” the condition is fulfilled.","question":"For hSD01-006〈ときのそら〉''s Arts ''SorAZ シンパシー'', does it still get “this Arts +50.” when you have hSD01-013〈SorAZ〉among your Holomen?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5 (2024.09.21)"},{"answer":"Yes, the condition is met. Even if there isn’t a card with that exact name, since its Extra states “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” the condition is fulfilled.","question":"For hSD01-006〈ときのそら〉''s Arts ''SorAZ シンパシー'', does the condition “If there is a Holomen〈AZKi〉on your Stage” also count if hSD01-013〈SorAZ〉is on your Stage?","related_cards":{"card_number":["hSD01-006"],"raw_html":"[hSD01-006 ： ときのそら]"},"title":"Q4 (2024.09.21)"}],"es":[{"answer":"Sí, obtiene +50. Incluso si no existe una carta con ese nombre exacto, si alguna carta tiene en su habilidad Extra algo como “Este Holomen también se considera como〈ときのそら〉〈AZKi〉”, se cumple la condición.","question":"Cuando la carta hSD01-006〈ときのそら〉 usa el arte “SorAZ シンパシー”, si tienes entre tus Holomen a hSD01-013〈SorAZ〉, ¿también obtiene “este arte +50.”?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"},{"answer":"Sí, se cumple la condición. Aunque no haya una carta con ese nombre exacto, como en el texto Extra dice “Este Holomen también se considera como〈ときのそら〉〈AZKi〉”, la condición se cumple.","question":"En el arte “SorAZ シンパシー” de hSD01-006〈ときのそら〉, la condición “Si tienes en tu escenario a la Holomen〈AZKi〉” ¿también se cumple si tienes a hSD01-013〈SorAZ〉?","related_cards":{"card_number":["hSD01-006"],"raw_html":"[hSD01-006 ： ときのそら]"},"title":"Q4（2024.09.21）"}],"id":[{"answer":"Ya, +50 diterapkan. Bahkan jika nama kartu yang sesuai tidak ada, jika efek ekstra menyatakan sesuatu seperti “holomen ini juga diperlakukan sebagai 〈ときのそら〉〈AZKi〉” sehingga dianggap sebagai nama kartu tertentu, maka kondisi itu terpenuhi.","question":"Apakah arts “SorAZ シンパシー” milik hSD01-006〈ときのそら〉 mendapatkan “arts ini +50.” meskipun di holomenmu ada hSD01-013〈SorAZ〉?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"},{"answer":"Ya, kondisi itu terpenuhi. Meskipun tidak ada nama kartu yang cocok, karena di extra tertulis “holomen ini juga diperlakukan sebagai 〈ときのそら〉〈AZKi〉”, kondisi tersebut terpenuhi.","question":"Apakah frasa “Jika di panggungmu ada holomen dengan 〈AZKi〉” pada arts “SorAZ シンパシー” hSD01-006〈ときのそら〉 terpenuhi jika ada hSD01-013〈SorAZ〉?","related_cards":{"card_number":["hSD01-006"],"raw_html":"[hSD01-006 ： ときのそら]"},"title":"Q4（2024.09.21）"}],"ja":[{"answer":"はい、＋50されます。カード名称に該当のカードがない場合でもエクストラの能力に「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。","question":"hSD01-006〈ときのそら〉のアーツ「SorAZ シンパシー」は自分のホロメンにhSD01-013〈SorAZ〉がいるときでも”このアーツ+50。”されますか？","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"},{"answer":"はい、条件を満たします。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」と書かれているため、条件を満たします。","question":"hSD01-006〈ときのそら〉のアーツ「SorAZ シンパシー」の「自分のステージにホロメンの〈AZKi〉がいる時」は、hSD01-013〈SorAZ〉がいる場合でも条件を満たしますか？","related_cards":{"card_number":["hSD01-006"],"raw_html":"[hSD01-006 ： ときのそら]"},"title":"Q4（2024.09.21）"}],"ko":[{"answer":"네, +50 됩니다. 카드 이름에 해당 카드가 없더라도, 엑스트라 능력에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」처럼 특정 카드명으로 취급하는 카드가 있다면 그 조건을 충족합니다.","question":"hSD01-006〈ときのそら〉의 아츠 「SorAZ シンパシー」는 자신의 홀로멘에 hSD01-013〈SorAZ〉가 있을 때도 “이 아츠 +50.”이 적용되나요?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"},{"answer":"네, 조건을 만족합니다. 카드 이름에 해당 카드가 없더라도, 엑스트라에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」고 적혀 있기 때문에 조건을 만족합니다.","question":"hSD01-006〈ときのそら〉의 아츠 「SorAZ シンパシー」의 “자신의 스테이지에 홀로멘〈AZKi〉가 있을 때”는 hSD01-013〈SorAZ〉가 있을 경우에도 조건을 만족하나요?","related_cards":{"card_number":["hSD01-006"],"raw_html":"[hSD01-006 ： ときのそら]"},"title":"Q4（2024.09.21）"}],"tc":[{"answer":"是的，會+50。即使卡牌名稱中沒有對應的卡牌，只要額外能力中有「此Holomen同時視為〈ときのそら〉〈AZKi〉」等能作為特定卡名處理的卡牌存在，就能滿足該條件。","question":"hSD01-006〈ときのそら〉的藝術「SorAZ シンパシー」，在自己的Holomen中有hSD01-013〈SorAZ〉時，也會「此藝術+50」嗎？","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"},{"answer":"是的，可以滿足條件。即使卡牌名稱中沒有對應的卡牌，因為額外能力中寫有「此Holomen同時視為〈ときのそら〉〈AZKi〉」，所以能滿足條件。","question":"hSD01-006〈ときのそら〉的藝術「SorAZ シンパシー」中，「當自己的舞台上有Holomen〈AZKi〉時」這個條件，在有hSD01-013〈SorAZ〉時也能滿足嗎？","related_cards":{"card_number":["hSD01-006"],"raw_html":"[hSD01-006 ： ときのそら]"},"title":"Q4（2024.09.21）"}],"th":[{"answer":"ใช่ จะได้ +50。 แม้จะไม่มีชื่อการ์ดตรงกับเงื่อนไข หากความสามารถพิเศษในเอ็กซ์ตราระบุว่า \"โฮโลเมนนี้ยังถูกนับว่าเป็น〈ときのそら〉〈AZKi〉\" หรือถูกปฏิบัติเหมือนเป็นชื่อการ์ดเฉพาะ ก็จะถือว่าเป็นไปตามเงื่อนไขนั้นได้。","question":"อาร์ต \"SorAZ シンパシー\" ของ hSD01-006〈ときのそら〉 จะได้ \"+50\" เมื่อบนโฮโลเมนของตนมี hSD01-013〈SorAZ〉 อยู่ด้วยหรือไม่?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"},{"answer":"ใช่ ถือว่าเป็นไปตามเงื่อนไข。 แม้จะไม่มีชื่อการ์ดที่ตรงกัน หากในเอ็กซ์ตราระบุว่า \"โฮโลเมนนี้ยังถูกนับว่าเป็น〈ときのそら〉〈AZKi〉\" ก็จะทำให้เป็นไปตามเงื่อนไขได้。","question":"ประโยค \"เมื่อบนสเตจของตนมีโฮโลเมนของ〈AZKi〉อยู่\" ในอาร์ต \"SorAZ シンパシー\" ของ hSD01-006〈ときのそら〉 จะถือว่าเป็นจริงแม้มี hSD01-013〈SorAZ〉 อยู่หรือไม่?","related_cards":{"card_number":["hSD01-006"],"raw_html":"[hSD01-006 ： ときのそら]"},"title":"Q4（2024.09.21）"}]}', 'c08a19d3c814ade57f87ae1b7ca90e2e5f6ab620148ee1d235a0c11b2bc81bc7', 'ccc0aa458ed8d1490bf86d0d50d0fe431aaf1a6b1342ef640a1e70621b2cdb38', '1970-01-01T00:00:00Z');
INSERT INTO card_colors (color_code, card_id) VALUES ('white', '6');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ「ときのそら＆AZKi」', '6');
INSERT INTO card_tags (tag, card_id) VALUES ('JP', '6');
INSERT INTO card_tags (tag, card_id) VALUES ('0期生', '6');
INSERT INTO card_tags (tag, card_id) VALUES ('歌', '6');
INSERT INTO cards_fts (rowid, card_number, text) VALUES (6, 'hSD01-006', 'hSD01-006 I☆LA JP 0期生 歌 ときのそら #JP #0期生 #歌 このホロメンがダウンした時、自分のライフ-2 ドリームライブ SorAZ シンパシー 自分のステージにホロメンの〈AZKi〉がいる時、このアーツ+50。 Q5（2024.09.21） hSD01-006〈ときのそら〉のアーツ「SorAZ シンパシー」は自分のホロメンにhSD01-013〈SorAZ〉がいるときでも”このアーツ+50。”されますか？ はい、＋50されます。カード名称に該当のカードがない場合でもエクストラの能力に「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。 Q4（2024.09.21） hSD01-006〈ときのそら〉のアーツ「SorAZ シンパシー」の「自分のステージにホロメンの〈AZKi〉がいる時」は、hSD01-013〈SorAZ〉がいる場合でも条件を満たしますか？ はい、条件を満たします。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」と書かれているため、条件を満たします。 ときのそら #JP #0期生 #歌 When this Holomen is downed, your Life -2. ドリームライブ SorAZ シンパシー If there is a Holomen〈AZKi〉on your Stage, this Arts +50. Q5 (2024.09.21) For hSD01-006〈ときのそら〉''s Arts ''SorAZ シンパシー'', does it still get “this Arts +50.” when you have hSD01-013〈SorAZ〉among your Holomen? Yes, it gets +50. Even if there isn’t a card with the exact name, if there is a card whose Extra ability says something like “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” the condition is fulfilled. Q4 (2024.09.21) For hSD01-006〈ときのそら〉''s Arts ''SorAZ シンパシー'', does the condition “If there is a Holomen〈AZKi〉on your Stage” also count if hSD01-013〈SorAZ〉is on your Stage? Yes, the condition is met. Even if there isn’t a card with that exact name, since its Extra states “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” the condition is fulfilled. ときのそら #JP #0期生 #歌 當這位Holomen被擊倒時，自身生命值-2 ドリームライブ SorAZ シンパシー 當自己的舞台上有Holomen〈AZKi〉時，此藝術+50。 Q5（2024.09.21） hSD01-006〈ときのそら〉的藝術「SorAZ シンパシー」，在自己的Holomen中有hSD01-013〈SorAZ〉時，也會「此藝術+50」嗎？ 是的，會+50。即使卡牌名稱中沒有對應的卡牌，只要額外能力中有「此Holomen同時視為〈ときのそら〉〈AZKi〉」等能作為特定卡名處理的卡牌存在，就能滿足該條件。 Q4（2024.09.21） hSD01-006〈ときのそら〉的藝術「SorAZ シンパシー」中，「當自己的舞台上有Holomen〈AZKi〉時」這個條件，在有hSD01-013〈SorAZ〉時也能滿足嗎？ 是的，可以滿足條件。即使卡牌名稱中沒有對應的卡牌，因為額外能力中寫有「此Holomen同時視為〈ときのそら〉〈AZKi〉」，所以能滿足條件。 ときのそら #JP #0期生 #歌 Ketika holomen ini down, nyawamu -2 ドリームライブ SorAZ シンパシー Jika di panggungmu ada holomen dengan label 〈AZKi〉, arts ini +50. Q5（2024.09.21） Apakah arts “SorAZ シンパシー” milik hSD01-006〈ときのそら〉 mendapatkan “arts ini +50.” meskipun di holomenmu ada hSD01-013〈SorAZ〉? Ya, +50 diterapkan. Bahkan jika nama kartu yang sesuai tidak ada, jika efek ekstra menyatakan sesuatu seperti “holomen ini juga diperlakukan sebagai 〈ときのそら〉〈AZKi〉” sehingga dianggap sebagai nama kartu tertentu, maka kondisi itu terpenuhi. Q4（2024.09.21） Apakah frasa “Jika di panggungmu ada holomen dengan 〈AZKi〉” pada arts “SorAZ シンパシー” hSD01-006〈ときのそら〉 terpenuhi jika ada hSD01-013〈SorAZ〉? Ya, kondisi itu terpenuhi. Meskipun tidak ada nama kartu yang cocok, karena di extra tertulis “holomen ini juga diperlakukan sebagai 〈ときのそら〉〈AZKi〉”, kondisi tersebut terpenuhi. ときのそら #JP #0期生 #歌 이 홀로멘이 다운될 때, 자신의 라이프 -2 ドリームライブ SorAZ シンパシー 자신의 스테이지에 홀로멘〈AZKi〉가 있을 때, 이 아츠 +50. Q5（2024.09.21） hSD01-006〈ときのそら〉의 아츠 「SorAZ シンパシー」는 자신의 홀로멘에 hSD01-013〈SorAZ〉가 있을 때도 “이 아츠 +50.”이 적용되나요? 네, +50 됩니다. 카드 이름에 해당 카드가 없더라도, 엑스트라 능력에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」처럼 특정 카드명으로 취급하는 카드가 있다면 그 조건을 충족합니다. Q4（2024.09.21） hSD01-006〈ときのそら〉의 아츠 「SorAZ シンパシー」의 “자신의 스테이지에 홀로멘〈AZKi〉가 있을 때”는 hSD01-013〈SorAZ〉가 있을 경우에도 조건을 만족하나요? 네, 조건을 만족합니다. 카드 이름에 해당 카드가 없더라도, 엑스트라에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」고 적혀 있기 때문에 조건을 만족합니다. ときのそら #JP #0期生 #歌 เมื่อโฮโลเมนคนนี้ล้ม, ชีวิตของตนเอง -2 ドリームライブ SorAZ シンパシー เมื่อบนสเตจของตนมีโฮโลเมนที่เป็น〈AZKi〉ของฝ่ายตน อาร์ตนี้+50。 Q5（2024.09.21） อาร์ต "SorAZ シンパシー" ของ hSD01-006〈ときのそら〉 จะได้ "+50" เมื่อบนโฮโลเมนของตนมี hSD01-013〈SorAZ〉 อยู่ด้วยหรือไม่? ใช่ จะได้ +50。 แม้จะไม่มีชื่อการ์ดตรงกับเงื่อนไข หากความสามารถพิเศษในเอ็กซ์ตราระบุว่า "โฮโลเมนนี้ยังถูกนับว่าเป็น〈ときのそら〉〈AZKi〉" หรือถูกปฏิบัติเหมือนเป็นชื่อการ์ดเฉพาะ ก็จะถือว่าเป็นไปตามเงื่อนไขนั้นได้。 Q4（2024.09.21） ประโยค "เมื่อบนสเตจของตนมีโฮโลเมนของ〈AZKi〉อยู่" ในอาร์ต "SorAZ シンパシー" ของ hSD01-006〈ときのそら〉 จะถือว่าเป็นจริงแม้มี hSD01-013〈SorAZ〉 อยู่หรือไม่? ใช่ ถือว่าเป็นไปตามเงื่อนไข。 แม้จะไม่มีชื่อการ์ดที่ตรงกัน หากในเอ็กซ์ตราระบุว่า "โฮโลเมนนี้ยังถูกนับว่าเป็น〈ときのそら〉〈AZKi〉" ก็จะทำให้เป็นไปตามเงื่อนไขได้。 ときのそら #JP #0期生 #歌 Cuando este Holomen sea derrotado, tu vida se reduce en 2. ドリームライブ SorAZ シンパシー Si tienes en tu escenario a la Holomen〈AZKi〉, este arte obtiene +50. Q5（2024.09.21） Cuando la carta hSD01-006〈ときのそら〉 usa el arte “SorAZ シンパシー”, si tienes entre tus Holomen a hSD01-013〈SorAZ〉, ¿también obtiene “este arte +50.”? Sí, obtiene +50. Incluso si no existe una carta con ese nombre exacto, si alguna carta tiene en su habilidad Extra algo como “Este Holomen también se considera como〈ときのそら〉〈AZKi〉”, se cumple la condición. Q4（2024.09.21） En el arte “SorAZ シンパシー” de hSD01-006〈ときのそら〉, la condición “Si tienes en tu escenario a la Holomen〈AZKi〉” ¿también se cumple si tienes a hSD01-013〈SorAZ〉? Sí, se cumple la condición. Aunque no haya una carta con ese nombre exacto, como en el texto Extra dice “Este Holomen también se considera como〈ときのそら〉〈AZKi〉”, la condición se cumple.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('13', 'hSD01-013', 'character', 'R', 'first', 'hSD01/hSD01-013_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-013_R.png', 130, NULL, 1, '["null"]', '© 2023 Victor Entertainment.', 'SorAZ', '{"arts":[{"cost_count":2,"cost_types":["null","null"],"damage":50}],"card_sets":["スタートデッキ「ときのそら＆AZKi」"],"color_codes":["white_green"],"translations":{"en":{"arts":[{"effect":"You may roll a single die: if the result is odd, send the top card of your Cheer Deck to this Holomen; if even, draw one card from your deck.","name":"The Future I Want to Surpass"}],"extra":"This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉.","name":"SorAZ","tags":["#JP","#0期生","#歌"]},"es":{"arts":[{"effect":"Puedes tirar un dado una vez: si sale número impar, envía la carta superior de tu mazo de apoyo a este Holomen. Si sale número par, roba una carta de tu mazo.","name":"Futuro que quiero superar"}],"extra":"Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉.","name":"SorAZ","tags":["#JP","#0期生","#歌"]},"id":{"arts":[{"effect":"Kamu boleh melempar dadu sekali: jika hasilnya ganjil, kirim 1 kartu dari atas dek sorakmu ke Holomen ini. Jika hasilnya genap, ambil 1 kartu dari dek-mu.","name":"Masa Depan yang Ingin Dilewati"}],"extra":"Holomen ini juga dianggap sebagai〈ときのそら〉dan〈AZKi〉","name":"SorAZ","tags":["#JP","#0期生","#歌"]},"ja":{"arts":[{"effect":"サイコロを1回振れる:奇数の時、自分のエールデッキの上から1枚を、このホロメンに送る。偶数の時、自分のデッキを1枚引く。","name":"越えたい未来"}],"extra":"このホロメンは〈ときのそら〉〈AZKi〉としても扱う","name":"SorAZ","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"effect":"주사위를 한 번 굴릴 수 있다: 홀수가 나오면 자신의 응원 덱 맨 위의 1장을 이 홀로멘에게 보낸다. 짝수가 나오면 자신의 덱에서 1장을 뽑는다.","name":"넘고 싶은 미래"}],"extra":"이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급된다","name":"SorAZ","tags":["#JP","#0期生","#歌"]},"tc":{"arts":[{"effect":"可以擲骰子1次：若為奇數，將自己應援牌庫頂的1張牌送給此Holomen；若為偶數，從自己的牌庫抽1張牌。","name":"想跨越的未來"}],"extra":"此Holomen也視為〈ときのそら〉與〈AZKi〉。","name":"SorAZ","tags":["#JP","#0期生","#歌"]},"th":{"arts":[{"effect":"ทอยลูกเต๋า 1 ครั้ง: ถ้าออกเลขคี่ ให้นำการ์ด 1 ใบจากบนสุดของเด็คเอลของตัวเอง ส่งให้โฮโลเมมนี้ ถ้าออกเลขคู่ จั่วการ์ด 1 ใบจากเด็คของตัวเอง","name":"อนาคตที่อยากก้าวข้าม"}],"extra":"โฮโลเมมนี้นับว่าเป็น〈ときのそら〉และ〈AZKi〉ด้วย","name":"SorAZ","tags":["#JP","#0期生","#歌"]}}}', '{"en":[{"answer":"It means this card has the names 〈ときのそら〉, 〈AZKi〉, and 〈SorAZ〉.","question":"What does hSD01-013〈SorAZ〉’s extra ability “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉.” mean?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q616 (2026.03.02)"},{"answer":"No, you cannot.","question":"If I have one hSD01-013〈SorAZ〉 and hBP07-068〈AZKi〉 performs a Collab, can I count hSD01-013〈SorAZ〉 as two Holomen — 〈ときのそら〉 and 〈SorAZ〉 — for the Collab Effect “The Path We Walked Together”?","related_cards":{"card_number":["hSD01-013","hBP07-068"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP07-068 ： AZKi]"},"title":"Q602 (2026.03.02)"},{"answer":"Yes, you can add them.","question":"Using hBP04-089〈Two-Tone Color Computer〉, I chose 〈ときのそら〉 and 〈フワワ・アビスガード〉 as the Holomen with one color each and different colors. In this case, can I add hSD01-013〈SorAZ〉 and hBP03-050〈FUWAMOCO〉—the 1st Holomen of the same colors as the chosen ones—to my hand?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404 (2025.06.11)"},{"answer":"It means Holomen that each have only one color and there are two or more of them. For example, hBP01-021〈ときのそら〉 has one color, but hSD01-013〈SorAZ〉 has two colors.","question":"What does “Holomen with one color and different colors” on hBP04-089〈Two-Tone Color Computer〉 mean?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP01-021"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP01-021 ： ときのそら]"},"title":"Q402 (2025.06.11)"},{"answer":"Yes, you can.","question":"Can I use hBP02-078〈かなた建設〉 to add hSD01-013〈SorAZ〉 to my hand?","related_cards":{"card_number":["hBP02-078","hSD01-013"],"raw_html":"[hBP02-078 ： かなた建設]\n[hSD01-013 ： SorAZ]"},"title":"Q250 (2024.12.12)"},{"answer":"No, hBP01-124〈Pioneer〉 will be archived.","question":"If I Bloom my hSD01-013〈SorAZ〉, which has hBP01-124〈Pioneer〉 attached, into hBP01-023〈ときのそら〉, will hBP01-124〈Pioneer〉 remain attached?","related_cards":{"card_number":["hSD01-013","hBP01-124"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP01-124 ： 開拓者]"},"title":"Q116 (2024.09.21)"},{"answer":"Yes, you can. Even if the card name doesn’t directly match, as long as there is a card with an Extra ability such as “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉”, it satisfies that condition.","question":"In hSD01-021〈First Gravity〉’s text, it says “Reveal any number of 〈ときのそら〉 and 〈AZKi〉 cards.” Can I reveal hSD01-013〈SorAZ〉 and add it to my hand?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17 (2024.09.21)"},{"answer":"Yes, both abilities will activate. Because hSD01-013〈SorAZ〉 is treated as 〈ときのそら〉 and 〈AZKi〉 due to its Extra, both Holomen names are considered to be on stage.","question":"If hSD01-013〈SorAZ〉 is in the center position and my hSD01-015〈Hakui Koyori〉 performs a Collab, will both Collab Effect abilities trigger?","related_cards":{"card_number":["hSD01-013","hSD01-015"],"raw_html":"[hSD01-013 ： SorAZ]\n[hSD01-015 ： 博衣こより]"},"title":"Q13 (2024.09.21)"},{"answer":"Yes, it does.","question":"Does the Extra of hSD01-013〈SorAZ〉, “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” apply even when it’s not on stage?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q12 (2025.12.18)"},{"answer":"Yes, you can. After declaring the use of the Art, resolve as much of the effect described in the text as possible, then deal Art Damage.","question":"Can I use hSD01-013〈SorAZ〉’s art “The Future I Want to Surpass” even if my Deck or Cheer Deck has 0 cards?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q11 (2024.09.21)"},{"answer":"Yes, you can. Even if the card name doesn’t directly match, if there is a card with an Extra such as “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” it satisfies that condition.","question":"For hSD01-011〈AZKi〉’s Art “SorAZ Gravity,” if I don’t have a 〈ときのそら〉 among my Holomen but I do have hSD01-013〈SorAZ〉, can I still send the top card of my Cheer Deck to one of my Holomen?","related_cards":{"card_number":["hSD01-011","hSD01-013"],"raw_html":"[hSD01-011 ： AZKi]\n[hSD01-013 ： SorAZ]"},"title":"Q10 (2024.09.21)"},{"answer":"Yes, it receives +50. Even if the card name doesn’t directly match, if there’s an Extra ability such as “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” it satisfies that condition.","question":"For hSD01-006〈ときのそら〉’s Art “SorAZ Sympathy,” does the Art receive +50 if I have hSD01-013〈SorAZ〉 among my Holomen?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5 (2024.09.21)"}],"es":[{"answer":"Indica que posee los nombres de carta 〈ときのそら〉, 〈AZKi〉 y 〈SorAZ〉.","question":"¿Qué significa la habilidad extra de hSD01-013〈SorAZ〉 “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉”?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q616（2026.03.02）"},{"answer":"No, no puede.","question":"Si tienes un hSD01-013〈SorAZ〉 y hBP07-068〈AZKi〉 realiza una colaboración, ¿puede contarse hSD01-013〈SorAZ〉 como dos Holomen, 〈ときのそら〉 y 〈SorAZ〉, para el efecto de colaboración “Huella de lo que caminamos juntas”?","related_cards":{"card_number":["hSD01-013","hBP07-068"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP07-068 ： AZKi]"},"title":"Q602（2026.03.02）"},{"answer":"Sí, puedes añadirlos.","question":"Usando hBP04-089〈ツートンカラーパソコン〉, si eliges como Holomen de distinto color pero de un solo color cada uno a 〈ときのそら〉 y 〈フワワ・アビスガード〉 en tu escenario, ¿puedes añadir a tu mano a hSD01-013〈SorAZ〉 y hBP03-050〈FUWAMOCO〉 como 1st Holomen del mismo color que los elegidos?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"Significa que esos Holomen tienen un solo color cada uno, y que hay al menos dos con colores distintos. Por ejemplo, hBP01-021〈ときのそら〉 tiene un solo color, mientras que hSD01-013〈SorAZ〉 tiene dos colores.","question":"¿Qué significa “Holomen de un solo color y de distinto color” en el texto de hBP04-089〈ツートンカラーパソコン〉?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP01-021"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP01-021 ： ときのそら]"},"title":"Q402（2025.06.11）"},{"answer":"Sí, puedes hacerlo.","question":"¿Puedo usar hBP02-078〈かなた建設〉 para añadir hSD01-013〈SorAZ〉 a mi mano?","related_cards":{"card_number":["hBP02-078","hSD01-013"],"raw_html":"[hBP02-078 ： かなた建設]\n[hSD01-013 ： SorAZ]"},"title":"Q250（2024.12.12）"},{"answer":"No, hBP01-124〈開拓者〉 se archiva.","question":"Si mi hSD01-013〈SorAZ〉 con hBP01-124〈開拓者〉 unido se hace Bloom hacia hBP01-023〈ときのそら〉, ¿sigue hBP01-124〈開拓者〉 unido?","related_cards":{"card_number":["hSD01-013","hBP01-124"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP01-124 ： 開拓者]"},"title":"Q116（2024.09.21）"},{"answer":"Sí, puedes hacerlo. Aunque una carta no tenga exactamente ese nombre, si tiene una habilidad extra como “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉”, cumple la condición.","question":"En hSD01-021〈First Gravity〉 se indica “revela cualquier número de cartas 〈ときのそら〉 y 〈AZKi〉”. ¿Puedo revelar hSD01-013〈SorAZ〉 y añadirla a mi mano?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"Sí, ambas se activan. Debido a su habilidad extra, hSD01-013〈SorAZ〉 se considera también como 〈ときのそら〉 y 〈AZKi〉, y por tanto ambas Holomen se consideran presentes en el escenario.","question":"Si hSD01-013〈SorAZ〉 está en la posición central y hSD01-015〈博衣こより〉 realiza una colaboración, ¿se activan ambas habilidades de colaboración?","related_cards":{"card_number":["hSD01-013","hSD01-015"],"raw_html":"[hSD01-013 ： SorAZ]\n[hSD01-015 ： 博衣こより]"},"title":"Q13（2024.09.21）"},{"answer":"Sí, se aplica.","question":"¿La habilidad extra “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉” de hSD01-013〈SorAZ〉 aplica también cuando no está en el escenario?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q12（2025.12.18）"},{"answer":"Sí, puedes usarlo. Después de declarar el uso del Arte, resuelves los efectos escritos en el texto tanto como sea posible y luego causas el daño del Arte.","question":"¿Puedo usar el Arte “Futuro que quiero superar” de hSD01-013〈SorAZ〉 incluso si mi mazo o mazo de apoyo tiene 0 cartas?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q11（2024.09.21）"},{"answer":"Sí, puedes hacerlo. Aunque una carta no tenga exactamente ese nombre, si tiene una habilidad extra como “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉”, cumple la condición.","question":"En el Arte “SorAZ Gravity” de hSD01-011〈AZKi〉, si no tengo 〈ときのそら〉 entre mis Holomen, ¿puedo enviar la carta superior de mi mazo de apoyo a uno de mis Holomen si tengo hSD01-013〈SorAZ〉?","related_cards":{"card_number":["hSD01-011","hSD01-013"],"raw_html":"[hSD01-011 ： AZKi]\n[hSD01-013 ： SorAZ]"},"title":"Q10（2024.09.21）"},{"answer":"Sí, recibe +50. Aunque una carta no tenga exactamente ese nombre, si tiene una habilidad extra como “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉”, cumple la condición.","question":"En el Arte “SorAZ Sympathy” de hSD01-006〈ときのそら〉, ¿recibe igualmente “este Arte +50.” si tengo hSD01-013〈SorAZ〉 entre mis Holomen?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"}],"id":[{"answer":"Artinya kartu ini memiliki nama sebagai〈ときのそら〉,〈AZKi〉dan〈SorAZ〉.","question":"Apa arti dari kemampuan ekstra hSD01-013〈SorAZ〉「Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉」?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q616（2026.03.02）"},{"answer":"Tidak, tidak bisa.","question":"Jika aku memiliki 1 hSD01-013〈SorAZ〉, lalu hBP07-068〈AZKi〉 melakukan kolaborasi. Dalam kasus ini, apakah efek kolaborasi “Jejak yang Telah Dijalani Bersama” bisa menghitung hSD01-013〈SorAZ〉 sebagai dua orang, yaitu〈ときのそら〉dan〈SorAZ〉?","related_cards":{"card_number":["hSD01-013","hBP07-068"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP07-068 ： AZKi]"},"title":"Q602（2026.03.02）"},{"answer":"Ya, bisa ditambahkan.","question":"Dengan menggunakan hBP04-089〈ツートンカラーパソコン〉, aku memilih〈ときのそら〉dan〈フワワ・アビスガード〉sebagai Holomen dengan satu warna yang berbeda di stagenya. Dalam kasus ini, apakah aku bisa menambahkan hSD01-013〈SorAZ〉dan hBP03-050〈FUWAMOCO〉ke tangan sebagai 1st Holomen dengan warna yang sama seperti yang dipilih?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"Artinya Holomen tersebut memiliki hanya satu warna, dan ada lebih dari satu karakter. Sebagai contoh, hBP01-021〈ときのそら〉memiliki satu warna, sedangkan hSD01-013〈SorAZ〉memiliki dua warna.","question":"Apa arti dari “Holomen dengan satu warna yang berbeda” pada hBP04-089〈ツートンカラーパソコン〉?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP01-021"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP01-021 ： ときのそら]"},"title":"Q402（2025.06.11）"},{"answer":"Ya, bisa.","question":"Apakah aku bisa menambahkan hSD01-013〈SorAZ〉ke tangan dengan menggunakan hBP02-078〈かなた建設〉?","related_cards":{"card_number":["hBP02-078","hSD01-013"],"raw_html":"[hBP02-078 ： かなた建設]\n[hSD01-013 ： SorAZ]"},"title":"Q250（2024.12.12）"},{"answer":"Tidak, hBP01-124〈開拓者〉akan diarsipkan.","question":"Jika aku melakukan Bloom dari hSD01-013〈SorAZ〉yang dilengkapi dengan hBP01-124〈開拓者〉ke hBP01-023〈ときのそら〉, apakah〈開拓者〉akan tetap terpasang?","related_cards":{"card_number":["hSD01-013","hBP01-124"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP01-124 ： 開拓者]"},"title":"Q116（2024.09.21）"},{"answer":"Ya, bisa. Walaupun tidak ada kartu dengan nama yang sama, jika ada kartu dengan efek ekstra seperti “Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉”, maka kartu tersebut memenuhi syarat.","question":"Pada hSD01-021〈First Gravity〉tertulis “perlihatkan sebanyak yang kamu mau kartu〈ときのそら〉dan〈AZKi〉”. Apakah aku bisa memperlihatkan hSD01-013〈SorAZ〉dan menambahkannya ke tangan?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"Ya, keduanya akan aktif. Karena efek ekstra dari hSD01-013〈SorAZ〉menganggapnya sebagai〈ときのそら〉dan〈AZKi〉, maka kedua nama kartu Holomen itu dianggap ada di stage.","question":"Jika hSD01-013〈SorAZ〉berada di posisi tengah dan aku melakukan kolaborasi dengan hSD01-015〈博衣こより〉, apakah kedua kemampuan efek kolaborasi akan aktif?","related_cards":{"card_number":["hSD01-013","hSD01-015"],"raw_html":"[hSD01-013 ： SorAZ]\n[hSD01-015 ： 博衣こより]"},"title":"Q13（2024.09.21）"},{"answer":"Ya, berlaku.","question":"Apakah efek ekstra hSD01-013〈SorAZ〉「Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉」berlaku juga saat tidak berada di stage?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q12（2025.12.18）"},{"answer":"Ya, bisa digunakan. Setelah mendeklarasikan penggunaan arts, efek yang tertulis diselesaikan sejauh mungkin, lalu berikan damage arts.","question":"Apakah aku bisa menggunakan arts “Masa Depan yang Ingin Dilewati” dari hSD01-013〈SorAZ〉meskipun deck atau deck sorakku kosong?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q11（2024.09.21）"},{"answer":"Ya, bisa. Walaupun tidak ada kartu dengan nama yang sama, jika ada kartu dengan efek ekstra seperti “Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉”, maka kartu tersebut memenuhi syarat.","question":"Pada hSD01-011〈AZKi〉dengan arts “SorAZ Gravity”, jika aku tidak memiliki〈ときのそら〉, tapi ada hSD01-013〈SorAZ〉, apakah aku bisa mengirim 1 kartu dari atas deck sorakku ke Holomen-ku?","related_cards":{"card_number":["hSD01-011","hSD01-013"],"raw_html":"[hSD01-011 ： AZKi]\n[hSD01-013 ： SorAZ]"},"title":"Q10（2024.09.21）"},{"answer":"Ya, menjadi +50. Walaupun tidak ada kartu dengan nama yang sama, jika ada kemampuan ekstra seperti “Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉”, maka kartu tersebut memenuhi syarat.","question":"Apakah arts “SorAZ Sympathy” dari hSD01-006〈ときのそら〉menjadi +50 saat aku memiliki hSD01-013〈SorAZ〉di antara Holomen-ku?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"}],"ja":[{"answer":"カード名として、〈ときのそら〉、〈AZKi〉、〈SorAZ〉を持つことを指します。","question":"hSD01-013〈SorAZ〉のエクストラ能力「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」とは、どういう意味ですか？","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q616（2026.03.02）"},{"answer":"いいえ、できません。","question":"自分のhSD01-013〈SorAZ〉が1人いる時、hBP07-068〈AZKi〉がコラボしました。この場合、コラボエフェクト「共に歩んできた軌跡」の能力で、hSD01-013〈SorAZ〉を〈ときのそら〉、〈SorAZ〉の2人分として数えることはできますか？","related_cards":{"card_number":["hSD01-013","hBP07-068"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP07-068 ： AZKi]"},"title":"Q602（2026.03.02）"},{"answer":"はい、加えられます。","question":"hBP04-089〈ツートンカラーパソコン〉を使い、自分のステージに色が1色で異なる色のホロメンとして、〈ときのそら〉と〈フワワ・アビスガード〉を選びました。この場合、選んだホロメンと同色の1stホロメンとして、hSD01-013〈SorAZ〉とhBP03-050〈FUWAMOCO〉を手札に加えられますか？","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"そのホロメンが持つ色が1色のみであり、2人以上いることを指します。例としてhBP01-021〈ときのそら〉は持っている色が1色ですが、hSD01-013〈SorAZ〉は持っている色が2色となります。","question":"hBP04-089〈ツートンカラーパソコン〉の「色が1色で異なる色のホロメン」とはどういう意味ですか？","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP01-021"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP01-021 ： ときのそら]"},"title":"Q402（2025.06.11）"},{"answer":"はい、可能です。","question":"hBP02-078〈かなた建設〉を使用して、hSD01-013〈SorAZ〉を手札に加えることができますか？","related_cards":{"card_number":["hBP02-078","hSD01-013"],"raw_html":"[hBP02-078 ： かなた建設]\n[hSD01-013 ： SorAZ]"},"title":"Q250（2024.12.12）"},{"answer":"いいえ、hBP01-124〈開拓者〉はアーカイブされます。","question":"hBP01-124〈開拓者〉が付けられている自分のhSD01-013〈SorAZ〉を、hBP01-023〈ときのそら〉にBloomした場合、hBP01-124〈開拓者〉は付けたままになりますか？","related_cards":{"card_number":["hSD01-013","hBP01-124"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP01-124 ： 開拓者]"},"title":"Q116（2024.09.21）"},{"answer":"はい、できます。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。","question":"hSD01-021〈First Gravity〉の「〈ときのそら〉と〈AZKi〉を好きな枚数公開し、」とありますが、hSD01-013〈SorAZ〉を公開し、手札に加えることはできますか？","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"はい、どちらの能力も発揮します。hSD01-013〈SorAZ〉は、エクストラにより〈ときのそら〉〈AZKi〉として扱うため、どちらのカード名のホロメンもステージにいるものとして扱います。","question":"hSD01-013〈SorAZ〉がセンターポジションにいる状態で、自分のhSD01-015〈博衣こより〉がコラボした場合、コラボエフェクトの能力はどちらの能力も発揮しますか？","related_cards":{"card_number":["hSD01-013","hSD01-015"],"raw_html":"[hSD01-013 ： SorAZ]\n[hSD01-015 ： 博衣こより]"},"title":"Q13（2024.09.21）"},{"answer":"はい、扱います。","question":"hSD01-013〈SorAZ〉のエクストラ「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」とは、ステージ以外にある場合でも〈ときのそら〉〈AZKi〉として扱いますか？","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q12（2025.12.18）"},{"answer":"はい、使用できます。アーツの使用の宣言後、テキストに書かれている効果を可能な限り解決してから、アーツダメージを与えます。","question":"hSD01-013〈SorAZ〉のアーツ「越えたい未来」は自分のデッキ、またはエールデッキが０枚の場合でも使用できますか？","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q11（2024.09.21）"},{"answer":"はい、送れます。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。","question":"hSD01-011〈AZKi〉のアーツ「SorAZ グラビティ」は、自分のホロメンに〈ときのそら〉がいなくてもhSD01-013〈SorAZ〉がいれば自分のエールデッキの上から１枚を、自分のホロメンに送れますか？","related_cards":{"card_number":["hSD01-011","hSD01-013"],"raw_html":"[hSD01-011 ： AZKi]\n[hSD01-013 ： SorAZ]"},"title":"Q10（2024.09.21）"},{"answer":"はい、＋50されます。カード名称に該当のカードがない場合でもエクストラの能力に「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。","question":"hSD01-006〈ときのそら〉のアーツ「SorAZ シンパシー」は自分のホロメンにhSD01-013〈SorAZ〉がいるときでも”このアーツ+50。”されますか？","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"}],"ko":[{"answer":"카드 이름으로서 〈ときのそら〉, 〈AZKi〉, 〈SorAZ〉를 모두 가진다는 뜻입니다.","question":"hSD01-013〈SorAZ〉의 엑스트라 능력 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급된다」는 무슨 의미인가요?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q616（2026.03.02）"},{"answer":"아니요, 할 수 없습니다.","question":"내 필드에 hSD01-013〈SorAZ〉 한 명이 있고, hBP07-068〈AZKi〉가 콜라보했습니다. 이때 콜라보 이펙트 「함께 걸어온 궤적」의 능력으로 hSD01-013〈SorAZ〉를 〈ときのそら〉와 〈SorAZ〉 두 명으로 계산할 수 있나요?","related_cards":{"card_number":["hSD01-013","hBP07-068"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP07-068 ： AZKi]"},"title":"Q602（2026.03.02）"},{"answer":"네, 넣을 수 있습니다.","question":"hBP04-089〈투톤 컬러 컴퓨터〉를 사용해, 내 스테이지에 색이 한 가지이며 다른 색의 홀로멘으로서〈ときのそら〉와 〈フワワ・アビスガード〉를 선택했습니다. 이 경우, 선택한 홀로멘과 같은 색의 1st 홀로멘으로 hSD01-013〈SorAZ〉와 hBP03-050〈FUWAMOCO〉를 손패에 넣을 수 있나요?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： 투톤 컬러 컴퓨터]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"그 홀로멘이 가진 색이 하나뿐이며, 두 명 이상 존재한다는 뜻입니다. 예를 들어 hBP01-021〈ときのそら〉는 색이 한 가지이지만, hSD01-013〈SorAZ〉는 두 가지 색을 가지고 있습니다.","question":"hBP04-089〈투톤 컬러 컴퓨터〉에서 말하는 ‘색이 한 가지이며 다른 색의 홀로멘’은 어떤 의미인가요?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP01-021"],"raw_html":"[hBP04-089 ： 투톤 컬러 컴퓨터]\n[hSD01-013 ： SorAZ]\n[hBP01-021 ： ときのそら]"},"title":"Q402（2025.06.11）"},{"answer":"네, 가능합니다.","question":"hBP02-078〈かなた建設〉을 사용해 hSD01-013〈SorAZ〉를 손패에 추가할 수 있나요?","related_cards":{"card_number":["hBP02-078","hSD01-013"],"raw_html":"[hBP02-078 ： かなた建設]\n[hSD01-013 ： SorAZ]"},"title":"Q250（2024.12.12）"},{"answer":"아니요, hBP01-124〈개척자〉는 보관 영역(아카이브)으로 이동합니다.","question":"hBP01-124〈개척자〉가 부착된 내 hSD01-013〈SorAZ〉를 hBP01-023〈ときのそら〉로 블룸했을 때, hBP01-124〈개척자〉는 그대로 남아 있나요?","related_cards":{"card_number":["hSD01-013","hBP01-124"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP01-124 ： 개척자]"},"title":"Q116（2024.09.21）"},{"answer":"네, 가능합니다. 카드 이름에 해당 카드가 없더라도 엑스트라에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급된다」처럼 특정 카드명으로 취급된다는 효과가 있다면 그 조건을 충족합니다.","question":"hSD01-021〈First Gravity〉의 “〈ときのそら〉와 〈AZKi〉를 원하는 만큼 공개하고,”라는 부분에서 hSD01-013〈SorAZ〉를 공개하여 손패에 넣을 수 있나요?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"네, 두 가지 능력 모두 발동됩니다. hSD01-013〈SorAZ〉는 엑스트라에 의해 〈ときのそら〉〈AZKi〉로도 취급되므로, 두 카드명의 홀로멘이 모두 스테이지에 있는 것으로 간주됩니다.","question":"hSD01-013〈SorAZ〉가 센터 포지션에 있고, 내 hSD01-015〈博衣こより〉가 콜라보했을 때, 콜라보 이펙트의 능력은 두 가지 모두 발동되나요?","related_cards":{"card_number":["hSD01-013","hSD01-015"],"raw_html":"[hSD01-013 ： SorAZ]\n[hSD01-015 ： 博衣こより]"},"title":"Q13（2024.09.21）"},{"answer":"네, 적용됩니다.","question":"hSD01-013〈SorAZ〉의 엑스트라 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급된다」는 스테이지 외의 영역에서도 적용되나요?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q12（2025.12.18）"},{"answer":"네, 사용할 수 있습니다. 아츠 사용을 선언한 후, 텍스트에 적힌 효과를 가능한 한 해결한 뒤 아츠 대미지를 줍니다.","question":"hSD01-013〈SorAZ〉의 아츠 「넘고 싶은 미래」는 내 덱이나 응원 덱이 0장일 때도 사용할 수 있나요?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q11（2024.09.21）"},{"answer":"네, 보낼 수 있습니다. 카드명에 해당 카드가 없더라도 엑스트라에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급된다」처럼 특정 카드명으로 취급된다는 효과가 있다면 그 조건을 충족합니다.","question":"hSD01-011〈AZKi〉의 아츠 「SorAZ 그래비티」는 내 홀로멘에 〈ときのそら〉가 없어도 hSD01-013〈SorAZ〉가 있으면 내 응원 덱 맨 위의 1장을 내 홀로멘에게 보낼 수 있나요?","related_cards":{"card_number":["hSD01-011","hSD01-013"],"raw_html":"[hSD01-011 ： AZKi]\n[hSD01-013 ： SorAZ]"},"title":"Q10（2024.09.21）"},{"answer":"네, +50 됩니다. 카드명에 해당 카드가 없더라도 엑스트라 능력에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급된다」처럼 특정 카드명으로 취급된다는 효과가 있다면 그 조건을 충족합니다.","question":"hSD01-006〈ときのそら〉의 아츠 「SorAZ 심퍼시」는 내 홀로멘에 hSD01-013〈SorAZ〉가 있을 때도 “이 아츠 +50.”이 적용되나요?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"}],"tc":[{"answer":"代表此卡同時擁有〈ときのそら〉、〈AZKi〉與〈SorAZ〉三個卡名。","question":"hSD01-013〈SorAZ〉的額外能力「此Holomen也視為〈ときのそら〉〈AZKi〉。」是什麼意思？","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q616（2026.03.02）"},{"answer":"不行，無法這麼做。","question":"當我場上有1張hSD01-013〈SorAZ〉，並讓hBP07-068〈AZKi〉進行合作時，在合作效果「共同走過的軌跡」之條件下，可以將hSD01-013〈SorAZ〉同時計作〈ときのそら〉與〈SorAZ〉兩人嗎？","related_cards":{"card_number":["hSD01-013","hBP07-068"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP07-068 ： AZKi]"},"title":"Q602（2026.03.02）"},{"answer":"可以，能夠加入手牌。","question":"使用hBP04-089〈ツートンカラーパソコン〉，選擇我場上顏色為單色且顏色不同的Holomen為〈ときのそら〉及〈フワワ・アビスガード〉。此時，可以將hSD01-013〈SorAZ〉與hBP03-050〈FUWAMOCO〉作為與所選Holomen同色的1st Holomen加入手牌嗎？","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"指該Holomen僅持有單一顏色，且有兩位以上。舉例來說，hBP01-021〈ときのそら〉僅有一種顏色，而hSD01-013〈SorAZ〉則持有兩種顏色。","question":"hBP04-089〈ツートンカラーパソコン〉中的「顏色為單色且顏色不同的Holomen」是什麼意思？","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP01-021"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP01-021 ： ときのそら]"},"title":"Q402（2025.06.11）"},{"answer":"可以，能夠這麼做。","question":"可以使用hBP02-078〈かなた建設〉將hSD01-013〈SorAZ〉加入手牌嗎？","related_cards":{"card_number":["hBP02-078","hSD01-013"],"raw_html":"[hBP02-078 ： かなた建設]\n[hSD01-013 ： SorAZ]"},"title":"Q250（2024.12.12）"},{"answer":"不會，hBP01-124〈開拓者〉會被送入檔案區域。","question":"若我場上的hSD01-013〈SorAZ〉裝備了hBP01-124〈開拓者〉，當我以〈ときのそら〉進行Bloom時，hBP01-124〈開拓者〉會保留在原位嗎？","related_cards":{"card_number":["hSD01-013","hBP01-124"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP01-124 ： 開拓者]"},"title":"Q116（2024.09.21）"},{"answer":"可以。即使卡名不符合條件，只要額外能力中（EXTRA）有「此Holomen也視為〈ときのそら〉〈AZKi〉。」類似的效果，便能滿足該條件。","question":"hSD01-021〈First Gravity〉寫著「公開任意數量的〈ときのそら〉與〈AZKi〉」時，可以公開hSD01-013〈SorAZ〉並將其加入手牌嗎？","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"會，兩個能力都會發動。由於hSD01-013〈SorAZ〉的額外能力使其同時視為〈ときのそら〉與〈AZKi〉，因此被視為舞台上同時存在這兩張卡名的Holomen。","question":"若hSD01-013〈SorAZ〉位於中央位置，並讓自己的hSD01-015〈博衣こより〉進行合作時，合作效果會同時發動兩張卡的能力嗎？","related_cards":{"card_number":["hSD01-013","hSD01-015"],"raw_html":"[hSD01-013 ： SorAZ]\n[hSD01-015 ： 博衣こより]"},"title":"Q13（2024.09.21）"},{"answer":"可以，皆視為同樣處理。","question":"hSD01-013〈SorAZ〉的額外能力「此Holomen也視為〈ときのそら〉〈AZKi〉。」在不在舞台上時也能當作〈ときのそら〉〈AZKi〉使用嗎？","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q12（2025.12.18）"},{"answer":"可以使用。宣告使用藝術後，會盡可能解決效果文字，再造成藝術傷害。","question":"hSD01-013〈SorAZ〉的藝術「想跨越的未來」在自己牌庫或應援牌庫為0張的情況下仍能使用嗎？","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q11（2024.09.21）"},{"answer":"可以。即使沒有該卡名稱，只要額外能力中有「此Holomen也視為〈ときのそら〉〈AZKi〉。」此類效果，便能滿足條件。","question":"hSD01-011〈AZKi〉的藝術「SorAZ Gravity」，若自己場上沒有〈ときのそら〉，但有hSD01-013〈SorAZ〉時，是否仍可將應援牌庫頂的1張牌送給自己的Holomen？","related_cards":{"card_number":["hSD01-011","hSD01-013"],"raw_html":"[hSD01-011 ： AZKi]\n[hSD01-013 ： SorAZ]"},"title":"Q10（2024.09.21）"},{"answer":"會，會增加+50。即使卡名不一致，只要額外能力中有「此Holomen也視為〈ときのそら〉〈AZKi〉。」類似效果，便能滿足條件。","question":"hSD01-006〈ときのそら〉的藝術「SorAZ Sympathy」，當自己場上有hSD01-013〈SorAZ〉時，也會使「此藝術+50」嗎？","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"}],"th":[{"answer":"หมายถึงถือว่าการ์ดนี้มีชื่อการ์ดเป็น〈ときのそら〉, 〈AZKi〉 และ〈SorAZ〉พร้อมกัน","question":"ความหมายของเอฟเฟกต์พิเศษ “โฮโลเมมนี้นับว่าเป็น〈ときのそら〉และ〈AZKi〉ด้วย” ในการ์ด hSD01-013〈SorAZ〉 คืออะไร?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q616（2026.03.02）"},{"answer":"ไม่ได้","question":"เมื่อมี hSD01-013〈SorAZ〉 ของตัวเองอยู่ 1 ใบ และได้คอลลาบกับ hBP07-068〈AZKi〉 ในกรณีนี้ จะนับ〈SorAZ〉เป็นทั้ง〈ときのそら〉และ〈SorAZ〉สองคนได้ไหม ตามเอฟเฟกต์คอลลาบ “เส้นทางที่เดินมาด้วยกัน”?","related_cards":{"card_number":["hSD01-013","hBP07-068"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP07-068 ： AZKi]"},"title":"Q602（2026.03.02）"},{"answer":"ได้ สามารถเพิ่มเข้ามือได้","question":"เมื่อใช้ hBP04-089〈ツートンカラーパソコン〉 แล้วเลือก〈ときのそら〉และ〈フワワ・アビスガード〉เป็นโฮโลเมมคนละสีที่มีแค่สีเดียว จะสามารถเพิ่ม hSD01-013〈SorAZ〉 และ hBP03-050〈FUWAMOCO〉 เข้ามือได้ไหม?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"หมายถึงโฮโลเมมนั้นมีสีเดียวเท่านั้น และมีมากกว่าหนึ่งคน ตัวอย่างเช่น hBP01-021〈ときのそら〉 มีสีเดียว แต่ hSD01-013〈SorAZ〉 มีสองสี","question":"คำว่า “โฮโลเมมที่มีเพียงสีเดียวและเป็นคนละสี” ใน hBP04-089〈ツートンカラーパソコン〉 หมายถึงอะไร?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP01-021"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP01-021 ： ときのそら]"},"title":"Q402（2025.06.11）"},{"answer":"ได้ สามารถทำได้","question":"สามารถใช้ hBP02-078〈かなた建設〉 เพื่อเพิ่ม hSD01-013〈SorAZ〉 เข้ามือได้ไหม?","related_cards":{"card_number":["hBP02-078","hSD01-013"],"raw_html":"[hBP02-078 ： かなた建設]\n[hSD01-013 ： SorAZ]"},"title":"Q250（2024.12.12）"},{"answer":"ไม่, hBP01-124〈開拓者〉 จะถูกส่งไปยังโซนอาร์ไคฟ์","question":"ถ้า hSD01-013〈SorAZ〉 ของตัวเองมี hBP01-124〈開拓者〉 ติดอยู่ แล้ว Bloom เป็น hBP01-023〈ときのそら〉 hBP01-124〈開拓者〉 จะยังคงอยู่ไหม?","related_cards":{"card_number":["hSD01-013","hBP01-124"],"raw_html":"[hSD01-013 ： SorAZ]\n[hBP01-124 ： 開拓者]"},"title":"Q116（2024.09.21）"},{"answer":"ได้ สามารถทำได้ ถึงจะไม่มีการ์ดที่มีชื่อตรงในชื่อการ์ด แต่ถ้ามีการ์ดที่มีเอฟเฟกต์พิเศษแบบ “โฮโลเมมนี้นับว่าเป็น〈ときのそら〉〈AZKi〉ด้วย” ก็ถือว่าเข้าเงื่อนไขได้","question":"ในข้อความของ hSD01-021〈First Gravity〉 มีระบุว่า “เปิดเผย〈ときのそら〉 และ〈AZKi〉ตามจำนวนที่ต้องการ” สามารถเปิดเผย hSD01-013〈SorAZ〉 แล้วเพิ่มเข้ามือได้ไหม?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"ได้ ทำงานทั้งสองฝั่ง เพราะ hSD01-013〈SorAZ〉 ถือว่าเป็น〈ときのそら〉และ〈AZKi〉 ด้วยจากเอฟเฟกต์พิเศษ จึงนับว่าโฮโลเมมทั้งสองชื่อนั้นอยู่บนสเตจ","question":"ถ้า hSD01-013〈SorAZ〉 อยู่ในตำแหน่งเซ็นเตอร์ แล้ว hSD01-015〈博衣こより〉 ของตัวเองทำคอลลาบ เอฟเฟกต์คอลลาบจะทำงานทั้งสองฝั่งไหม?","related_cards":{"card_number":["hSD01-013","hSD01-015"],"raw_html":"[hSD01-013 ： SorAZ]\n[hSD01-015 ： 博衣こより]"},"title":"Q13（2024.09.21）"},{"answer":"ได้ ใช้ได้ทุกโซน","question":"เอฟเฟกต์พิเศษของ hSD01-013〈SorAZ〉 ที่ว่า “โฮโลเมมนี้นับว่าเป็น〈ときのそら〉〈AZKi〉ด้วย” จะยังคงใช้ได้แม้อยู่ในโซนอื่นนอกจากสเตจไหม?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q12（2025.12.18）"},{"answer":"ได้ สามารถใช้ได้ หลังจากประกาศใช้สกิลแล้ว ให้แก้ผลตามที่สามารถทำได้ก่อน แล้วจึงคำนวณความเสียหายจากอาร์ต","question":"สามารถใช้สกิลอาร์ต “อนาคตที่อยากก้าวข้าม” ของ hSD01-013〈SorAZ〉 ได้ไหม หากเด็คหรือเด็คเอลของตัวเองเหลือ 0 ใบ?","related_cards":{"card_number":["hSD01-013"],"raw_html":"[hSD01-013 ： SorAZ]"},"title":"Q11（2024.09.21）"},{"answer":"ได้ สามารถส่งได้ ถึงไม่มีชื่อการ์ด〈ときのそら〉จริง ๆ แต่ถ้ามีการ์ดที่มีเอฟเฟกต์ว่า “โฮโลเมมนี้นับว่าเป็น〈ときのそら〉〈AZKi〉ด้วย” ก็ถือว่าเข้าเงื่อนไข","question":"อาร์ต “SorAZ กราวิตี” ของ hSD01-011〈AZKi〉 หากไม่มี〈ときのそら〉อยู่ในโฮโลเมม แต่มี hSD01-013〈SorAZ〉 จะสามารถส่งการ์ด 1 ใบจากบนเด็คเอลไปยังโฮโลเมมของตัวเองได้ไหม?","related_cards":{"card_number":["hSD01-011","hSD01-013"],"raw_html":"[hSD01-011 ： AZKi]\n[hSD01-013 ： SorAZ]"},"title":"Q10（2024.09.21）"},{"answer":"ได้ จะได้รับ +50 ถึงไม่มีชื่อการ์ด〈ときのそら〉ตรง ๆ แต่หากมีการ์ดที่มีเอฟเฟกต์ว่า “โฮโลเมมนี้นับว่าเป็น〈ときのそら〉〈AZKi〉ด้วย” ก็ถือว่าเข้าเงื่อนไขนั้น","question":"อาร์ต “SorAZ ซิมพาธี” ของ hSD01-006〈ときのそら〉 จะได้รับ “อาร์ตนี้ +50” ไหม เมื่อมี hSD01-013〈SorAZ〉 อยู่ในโฮโลเมมของตัวเอง?","related_cards":{"card_number":["hSD01-006","hSD01-013"],"raw_html":"[hSD01-006 ： ときのそら]\n[hSD01-013 ： SorAZ]"},"title":"Q5（2024.09.21）"}]}', '0cb770d3c9a519e92253f1032ed739cdb33d33ef035effac921035b3d30803f8', '01ab7f4d5d61b8942de26fa674f0a9ff020b1b5ddc9aa658e782a5998392bc67', '1970-01-01T00:00:00Z');
INSERT INTO card_colors (color_code, card_id) VALUES ('white_green', '13');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ「ときのそら＆AZKi」', '13');
INSERT INTO card_tags (tag, card_id) VALUES ('JP', '13');
INSERT INTO card_tags (tag, card_id) VALUES ('0期生', '13');
INSERT INTO card_tags (tag, card_id) VALUES ('歌', '13');
INSERT INTO cards_fts (rowid, card_number, text) VALUES (13, 'hSD01-013', 'hSD01-013 © 2023 Victor Entertainment. JP 0期生 歌 SorAZ #JP #0期生 #歌 このホロメンは〈ときのそら〉〈AZKi〉としても扱う 越えたい未来 サイコロを1回振れる:奇数の時、自分のエールデッキの上から1枚を、このホロメンに送る。偶数の時、自分のデッキを1枚引く。 Q616（2026.03.02） hSD01-013〈SorAZ〉のエクストラ能力「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」とは、どういう意味ですか？ カード名として、〈ときのそら〉、〈AZKi〉、〈SorAZ〉を持つことを指します。 Q602（2026.03.02） 自分のhSD01-013〈SorAZ〉が1人いる時、hBP07-068〈AZKi〉がコラボしました。この場合、コラボエフェクト「共に歩んできた軌跡」の能力で、hSD01-013〈SorAZ〉を〈ときのそら〉、〈SorAZ〉の2人分として数えることはできますか？ いいえ、できません。 Q404（2025.06.11） hBP04-089〈ツートンカラーパソコン〉を使い、自分のステージに色が1色で異なる色のホロメンとして、〈ときのそら〉と〈フワワ・アビスガード〉を選びました。この場合、選んだホロメンと同色の1stホロメンとして、hSD01-013〈SorAZ〉とhBP03-050〈FUWAMOCO〉を手札に加えられますか？ はい、加えられます。 Q402（2025.06.11） hBP04-089〈ツートンカラーパソコン〉の「色が1色で異なる色のホロメン」とはどういう意味ですか？ そのホロメンが持つ色が1色のみであり、2人以上いることを指します。例としてhBP01-021〈ときのそら〉は持っている色が1色ですが、hSD01-013〈SorAZ〉は持っている色が2色となります。 Q250（2024.12.12） hBP02-078〈かなた建設〉を使用して、hSD01-013〈SorAZ〉を手札に加えることができますか？ はい、可能です。 Q116（2024.09.21） hBP01-124〈開拓者〉が付けられている自分のhSD01-013〈SorAZ〉を、hBP01-023〈ときのそら〉にBloomした場合、hBP01-124〈開拓者〉は付けたままになりますか？ いいえ、hBP01-124〈開拓者〉はアーカイブされます。 Q17（2024.09.21） hSD01-021〈First Gravity〉の「〈ときのそら〉と〈AZKi〉を好きな枚数公開し、」とありますが、hSD01-013〈SorAZ〉を公開し、手札に加えることはできますか？ はい、できます。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。 Q13（2024.09.21） hSD01-013〈SorAZ〉がセンターポジションにいる状態で、自分のhSD01-015〈博衣こより〉がコラボした場合、コラボエフェクトの能力はどちらの能力も発揮しますか？ はい、どちらの能力も発揮します。hSD01-013〈SorAZ〉は、エクストラにより〈ときのそら〉〈AZKi〉として扱うため、どちらのカード名のホロメンもステージにいるものとして扱います。 Q12（2025.12.18） hSD01-013〈SorAZ〉のエクストラ「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」とは、ステージ以外にある場合でも〈ときのそら〉〈AZKi〉として扱いますか？ はい、扱います。 Q11（2024.09.21） hSD01-013〈SorAZ〉のアーツ「越えたい未来」は自分のデッキ、またはエールデッキが０枚の場合でも使用できますか？ はい、使用できます。アーツの使用の宣言後、テキストに書かれている効果を可能な限り解決してから、アーツダメージを与えます。 Q10（2024.09.21） hSD01-011〈AZKi〉のアーツ「SorAZ グラビティ」は、自分のホロメンに〈ときのそら〉がいなくてもhSD01-013〈SorAZ〉がいれば自分のエールデッキの上から１枚を、自分のホロメンに送れますか？ はい、送れます。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。 Q5（2024.09.21） hSD01-006〈ときのそら〉のアーツ「SorAZ シンパシー」は自分のホロメンにhSD01-013〈SorAZ〉がいるときでも”このアーツ+50。”されますか？ はい、＋50されます。カード名称に該当のカードがない場合でもエクストラの能力に「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。 SorAZ #JP #0期生 #歌 This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉. The Future I Want to Surpass You may roll a single die: if the result is odd, send the top card of your Cheer Deck to this Holomen; if even, draw one card from your deck. Q616 (2026.03.02) What does hSD01-013〈SorAZ〉’s extra ability “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉.” mean? It means this card has the names 〈ときのそら〉, 〈AZKi〉, and 〈SorAZ〉. Q602 (2026.03.02) If I have one hSD01-013〈SorAZ〉 and hBP07-068〈AZKi〉 performs a Collab, can I count hSD01-013〈SorAZ〉 as two Holomen — 〈ときのそら〉 and 〈SorAZ〉 — for the Collab Effect “The Path We Walked Together”? No, you cannot. Q404 (2025.06.11) Using hBP04-089〈Two-Tone Color Computer〉, I chose 〈ときのそら〉 and 〈フワワ・アビスガード〉 as the Holomen with one color each and different colors. In this case, can I add hSD01-013〈SorAZ〉 and hBP03-050〈FUWAMOCO〉—the 1st Holomen of the same colors as the chosen ones—to my hand? Yes, you can add them. Q402 (2025.06.11) What does “Holomen with one color and different colors” on hBP04-089〈Two-Tone Color Computer〉 mean? It means Holomen that each have only one color and there are two or more of them. For example, hBP01-021〈ときのそら〉 has one color, but hSD01-013〈SorAZ〉 has two colors. Q250 (2024.12.12) Can I use hBP02-078〈かなた建設〉 to add hSD01-013〈SorAZ〉 to my hand? Yes, you can. Q116 (2024.09.21) If I Bloom my hSD01-013〈SorAZ〉, which has hBP01-124〈Pioneer〉 attached, into hBP01-023〈ときのそら〉, will hBP01-124〈Pioneer〉 remain attached? No, hBP01-124〈Pioneer〉 will be archived. Q17 (2024.09.21) In hSD01-021〈First Gravity〉’s text, it says “Reveal any number of 〈ときのそら〉 and 〈AZKi〉 cards.” Can I reveal hSD01-013〈SorAZ〉 and add it to my hand? Yes, you can. Even if the card name doesn’t directly match, as long as there is a card with an Extra ability such as “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉”, it satisfies that condition. Q13 (2024.09.21) If hSD01-013〈SorAZ〉 is in the center position and my hSD01-015〈Hakui Koyori〉 performs a Collab, will both Collab Effect abilities trigger? Yes, both abilities will activate. Because hSD01-013〈SorAZ〉 is treated as 〈ときのそら〉 and 〈AZKi〉 due to its Extra, both Holomen names are considered to be on stage. Q12 (2025.12.18) Does the Extra of hSD01-013〈SorAZ〉, “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” apply even when it’s not on stage? Yes, it does. Q11 (2024.09.21) Can I use hSD01-013〈SorAZ〉’s art “The Future I Want to Surpass” even if my Deck or Cheer Deck has 0 cards? Yes, you can. After declaring the use of the Art, resolve as much of the effect described in the text as possible, then deal Art Damage. Q10 (2024.09.21) For hSD01-011〈AZKi〉’s Art “SorAZ Gravity,” if I don’t have a 〈ときのそら〉 among my Holomen but I do have hSD01-013〈SorAZ〉, can I still send the top card of my Cheer Deck to one of my Holomen? Yes, you can. Even if the card name doesn’t directly match, if there is a card with an Extra such as “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” it satisfies that condition. Q5 (2024.09.21) For hSD01-006〈ときのそら〉’s Art “SorAZ Sympathy,” does the Art receive +50 if I have hSD01-013〈SorAZ〉 among my Holomen? Yes, it receives +50. Even if the card name doesn’t directly match, if there’s an Extra ability such as “This Holomen is also treated as 〈ときのそら〉 and 〈AZKi〉,” it satisfies that condition. SorAZ #JP #0期生 #歌 此Holomen也視為〈ときのそら〉與〈AZKi〉。 想跨越的未來 可以擲骰子1次：若為奇數，將自己應援牌庫頂的1張牌送給此Holomen；若為偶數，從自己的牌庫抽1張牌。 Q616（2026.03.02） hSD01-013〈SorAZ〉的額外能力「此Holomen也視為〈ときのそら〉〈AZKi〉。」是什麼意思？ 代表此卡同時擁有〈ときのそら〉、〈AZKi〉與〈SorAZ〉三個卡名。 Q602（2026.03.02） 當我場上有1張hSD01-013〈SorAZ〉，並讓hBP07-068〈AZKi〉進行合作時，在合作效果「共同走過的軌跡」之條件下，可以將hSD01-013〈SorAZ〉同時計作〈ときのそら〉與〈SorAZ〉兩人嗎？ 不行，無法這麼做。 Q404（2025.06.11） 使用hBP04-089〈ツートンカラーパソコン〉，選擇我場上顏色為單色且顏色不同的Holomen為〈ときのそら〉及〈フワワ・アビスガード〉。此時，可以將hSD01-013〈SorAZ〉與hBP03-050〈FUWAMOCO〉作為與所選Holomen同色的1st Holomen加入手牌嗎？ 可以，能夠加入手牌。 Q402（2025.06.11） hBP04-089〈ツートンカラーパソコン〉中的「顏色為單色且顏色不同的Holomen」是什麼意思？ 指該Holomen僅持有單一顏色，且有兩位以上。舉例來說，hBP01-021〈ときのそら〉僅有一種顏色，而hSD01-013〈SorAZ〉則持有兩種顏色。 Q250（2024.12.12） 可以使用hBP02-078〈かなた建設〉將hSD01-013〈SorAZ〉加入手牌嗎？ 可以，能夠這麼做。 Q116（2024.09.21） 若我場上的hSD01-013〈SorAZ〉裝備了hBP01-124〈開拓者〉，當我以〈ときのそら〉進行Bloom時，hBP01-124〈開拓者〉會保留在原位嗎？ 不會，hBP01-124〈開拓者〉會被送入檔案區域。 Q17（2024.09.21） hSD01-021〈First Gravity〉寫著「公開任意數量的〈ときのそら〉與〈AZKi〉」時，可以公開hSD01-013〈SorAZ〉並將其加入手牌嗎？ 可以。即使卡名不符合條件，只要額外能力中（EXTRA）有「此Holomen也視為〈ときのそら〉〈AZKi〉。」類似的效果，便能滿足該條件。 Q13（2024.09.21） 若hSD01-013〈SorAZ〉位於中央位置，並讓自己的hSD01-015〈博衣こより〉進行合作時，合作效果會同時發動兩張卡的能力嗎？ 會，兩個能力都會發動。由於hSD01-013〈SorAZ〉的額外能力使其同時視為〈ときのそら〉與〈AZKi〉，因此被視為舞台上同時存在這兩張卡名的Holomen。 Q12（2025.12.18） hSD01-013〈SorAZ〉的額外能力「此Holomen也視為〈ときのそら〉〈AZKi〉。」在不在舞台上時也能當作〈ときのそら〉〈AZKi〉使用嗎？ 可以，皆視為同樣處理。 Q11（2024.09.21） hSD01-013〈SorAZ〉的藝術「想跨越的未來」在自己牌庫或應援牌庫為0張的情況下仍能使用嗎？ 可以使用。宣告使用藝術後，會盡可能解決效果文字，再造成藝術傷害。 Q10（2024.09.21） hSD01-011〈AZKi〉的藝術「SorAZ Gravity」，若自己場上沒有〈ときのそら〉，但有hSD01-013〈SorAZ〉時，是否仍可將應援牌庫頂的1張牌送給自己的Holomen？ 可以。即使沒有該卡名稱，只要額外能力中有「此Holomen也視為〈ときのそら〉〈AZKi〉。」此類效果，便能滿足條件。 Q5（2024.09.21） hSD01-006〈ときのそら〉的藝術「SorAZ Sympathy」，當自己場上有hSD01-013〈SorAZ〉時，也會使「此藝術+50」嗎？ 會，會增加+50。即使卡名不一致，只要額外能力中有「此Holomen也視為〈ときのそら〉〈AZKi〉。」類似效果，便能滿足條件。 SorAZ #JP #0期生 #歌 Holomen ini juga dianggap sebagai〈ときのそら〉dan〈AZKi〉 Masa Depan yang Ingin Dilewati Kamu boleh melempar dadu sekali: jika hasilnya ganjil, kirim 1 kartu dari atas dek sorakmu ke Holomen ini. Jika hasilnya genap, ambil 1 kartu dari dek-mu. Q616（2026.03.02） Apa arti dari kemampuan ekstra hSD01-013〈SorAZ〉「Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉」? Artinya kartu ini memiliki nama sebagai〈ときのそら〉,〈AZKi〉dan〈SorAZ〉. Q602（2026.03.02） Jika aku memiliki 1 hSD01-013〈SorAZ〉, lalu hBP07-068〈AZKi〉 melakukan kolaborasi. Dalam kasus ini, apakah efek kolaborasi “Jejak yang Telah Dijalani Bersama” bisa menghitung hSD01-013〈SorAZ〉 sebagai dua orang, yaitu〈ときのそら〉dan〈SorAZ〉? Tidak, tidak bisa. Q404（2025.06.11） Dengan menggunakan hBP04-089〈ツートンカラーパソコン〉, aku memilih〈ときのそら〉dan〈フワワ・アビスガード〉sebagai Holomen dengan satu warna yang berbeda di stagenya. Dalam kasus ini, apakah aku bisa menambahkan hSD01-013〈SorAZ〉dan hBP03-050〈FUWAMOCO〉ke tangan sebagai 1st Holomen dengan warna yang sama seperti yang dipilih? Ya, bisa ditambahkan. Q402（2025.06.11） Apa arti dari “Holomen dengan satu warna yang berbeda” pada hBP04-089〈ツートンカラーパソコン〉? Artinya Holomen tersebut memiliki hanya satu warna, dan ada lebih dari satu karakter. Sebagai contoh, hBP01-021〈ときのそら〉memiliki satu warna, sedangkan hSD01-013〈SorAZ〉memiliki dua warna. Q250（2024.12.12） Apakah aku bisa menambahkan hSD01-013〈SorAZ〉ke tangan dengan menggunakan hBP02-078〈かなた建設〉? Ya, bisa. Q116（2024.09.21） Jika aku melakukan Bloom dari hSD01-013〈SorAZ〉yang dilengkapi dengan hBP01-124〈開拓者〉ke hBP01-023〈ときのそら〉, apakah〈開拓者〉akan tetap terpasang? Tidak, hBP01-124〈開拓者〉akan diarsipkan. Q17（2024.09.21） Pada hSD01-021〈First Gravity〉tertulis “perlihatkan sebanyak yang kamu mau kartu〈ときのそら〉dan〈AZKi〉”. Apakah aku bisa memperlihatkan hSD01-013〈SorAZ〉dan menambahkannya ke tangan? Ya, bisa. Walaupun tidak ada kartu dengan nama yang sama, jika ada kartu dengan efek ekstra seperti “Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉”, maka kartu tersebut memenuhi syarat. Q13（2024.09.21） Jika hSD01-013〈SorAZ〉berada di posisi tengah dan aku melakukan kolaborasi dengan hSD01-015〈博衣こより〉, apakah kedua kemampuan efek kolaborasi akan aktif? Ya, keduanya akan aktif. Karena efek ekstra dari hSD01-013〈SorAZ〉menganggapnya sebagai〈ときのそら〉dan〈AZKi〉, maka kedua nama kartu Holomen itu dianggap ada di stage. Q12（2025.12.18） Apakah efek ekstra hSD01-013〈SorAZ〉「Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉」berlaku juga saat tidak berada di stage? Ya, berlaku. Q11（2024.09.21） Apakah aku bisa menggunakan arts “Masa Depan yang Ingin Dilewati” dari hSD01-013〈SorAZ〉meskipun deck atau deck sorakku kosong? Ya, bisa digunakan. Setelah mendeklarasikan penggunaan arts, efek yang tertulis diselesaikan sejauh mungkin, lalu berikan damage arts. Q10（2024.09.21） Pada hSD01-011〈AZKi〉dengan arts “SorAZ Gravity”, jika aku tidak memiliki〈ときのそら〉, tapi ada hSD01-013〈SorAZ〉, apakah aku bisa mengirim 1 kartu dari atas deck sorakku ke Holomen-ku? Ya, bisa. Walaupun tidak ada kartu dengan nama yang sama, jika ada kartu dengan efek ekstra seperti “Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉”, maka kartu tersebut memenuhi syarat. Q5（2024.09.21） Apakah arts “SorAZ Sympathy” dari hSD01-006〈ときのそら〉menjadi +50 saat aku memiliki hSD01-013〈SorAZ〉di antara Holomen-ku? Ya, menjadi +50. Walaupun tidak ada kartu dengan nama yang sama, jika ada kemampuan ekstra seperti “Holomen ini juga dianggap sebagai〈ときのそら〉〈AZKi〉”, maka kartu tersebut memenuhi syarat. SorAZ #JP #0期生 #歌 이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급된다 넘고 싶은 미래 주사위를 한 번 굴릴 수 있다: 홀수가 나오면 자신의 응원 덱 맨 위의 1장을 이 홀로멘에게 보낸다. 짝수가 나오면 자신의 덱에서 1장을 뽑는다. Q616（2026.03.02） hSD01-013〈SorAZ〉의 엑스트라 능력 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급된다」는 무슨 의미인가요? 카드 이름으로서 〈ときのそら〉, 〈AZKi〉, 〈SorAZ〉를 모두 가진다는 뜻입니다. Q602（2026.03.02） 내 필드에 hSD01-013〈SorAZ〉 한 명이 있고, hBP07-068〈AZKi〉가 콜라보했습니다. 이때 콜라보 이펙트 「함께 걸어온 궤적」의 능력으로 hSD01-013〈SorAZ〉를 〈ときのそら〉와 〈SorAZ〉 두 명으로 계산할 수 있나요? 아니요, 할 수 없습니다. Q404（2025.06.11） hBP04-089〈투톤 컬러 컴퓨터〉를 사용해, 내 스테이지에 색이 한 가지이며 다른 색의 홀로멘으로서〈ときのそら〉와 〈フワワ・アビスガード〉를 선택했습니다. 이 경우, 선택한 홀로멘과 같은 색의 1st 홀로멘으로 hSD01-013〈SorAZ〉와 hBP03-050〈FUWAMOCO〉를 손패에 넣을 수 있나요? 네, 넣을 수 있습니다. Q402（2025.06.11） hBP04-089〈투톤 컬러 컴퓨터〉에서 말하는 ‘색이 한 가지이며 다른 색의 홀로멘’은 어떤 의미인가요? 그 홀로멘이 가진 색이 하나뿐이며, 두 명 이상 존재한다는 뜻입니다. 예를 들어 hBP01-021〈ときのそら〉는 색이 한 가지이지만, hSD01-013〈SorAZ〉는 두 가지 색을 가지고 있습니다. Q250（2024.12.12） hBP02-078〈かなた建設〉을 사용해 hSD01-013〈SorAZ〉를 손패에 추가할 수 있나요? 네, 가능합니다. Q116（2024.09.21） hBP01-124〈개척자〉가 부착된 내 hSD01-013〈SorAZ〉를 hBP01-023〈ときのそら〉로 블룸했을 때, hBP01-124〈개척자〉는 그대로 남아 있나요? 아니요, hBP01-124〈개척자〉는 보관 영역(아카이브)으로 이동합니다. Q17（2024.09.21） hSD01-021〈First Gravity〉의 “〈ときのそら〉와 〈AZKi〉를 원하는 만큼 공개하고,”라는 부분에서 hSD01-013〈SorAZ〉를 공개하여 손패에 넣을 수 있나요? 네, 가능합니다. 카드 이름에 해당 카드가 없더라도 엑스트라에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급된다」처럼 특정 카드명으로 취급된다는 효과가 있다면 그 조건을 충족합니다. Q13（2024.09.21） hSD01-013〈SorAZ〉가 센터 포지션에 있고, 내 hSD01-015〈博衣こより〉가 콜라보했을 때, 콜라보 이펙트의 능력은 두 가지 모두 발동되나요? 네, 두 가지 능력 모두 발동됩니다. hSD01-013〈SorAZ〉는 엑스트라에 의해 〈ときのそら〉〈AZKi〉로도 취급되므로, 두 카드명의 홀로멘이 모두 스테이지에 있는 것으로 간주됩니다. Q12（2025.12.18） hSD01-013〈SorAZ〉의 엑스트라 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급된다」는 스테이지 외의 영역에서도 적용되나요? 네, 적용됩니다. Q11（2024.09.21） hSD01-013〈SorAZ〉의 아츠 「넘고 싶은 미래」는 내 덱이나 응원 덱이 0장일 때도 사용할 수 있나요? 네, 사용할 수 있습니다. 아츠 사용을 선언한 후, 텍스트에 적힌 효과를 가능한 한 해결한 뒤 아츠 대미지를 줍니다. Q10（2024.09.21） hSD01-011〈AZKi〉의 아츠 「SorAZ 그래비티」는 내 홀로멘에 〈ときのそら〉가 없어도 hSD01-013〈SorAZ〉가 있으면 내 응원 덱 맨 위의 1장을 내 홀로멘에게 보낼 수 있나요? 네, 보낼 수 있습니다. 카드명에 해당 카드가 없더라도 엑스트라에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급된다」처럼 특정 카드명으로 취급된다는 효과가 있다면 그 조건을 충족합니다. Q5（2024.09.21） hSD01-006〈ときのそら〉의 아츠 「SorAZ 심퍼시」는 내 홀로멘에 hSD01-013〈SorAZ〉가 있을 때도 “이 아츠 +50.”이 적용되나요? 네, +50 됩니다. 카드명에 해당 카드가 없더라도 엑스트라 능력에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급된다」처럼 특정 카드명으로 취급된다는 효과가 있다면 그 조건을 충족합니다. SorAZ #JP #0期生 #歌 โฮโลเมมนี้นับว่าเป็น〈ときのそら〉และ〈AZKi〉ด้วย อนาคตที่อยากก้าวข้าม ทอยลูกเต๋า 1 ครั้ง: ถ้าออกเลขคี่ ให้นำการ์ด 1 ใบจากบนสุดของเด็คเอลของตัวเอง ส่งให้โฮโลเมมนี้ ถ้าออกเลขคู่ จั่วการ์ด 1 ใบจากเด็คของตัวเอง Q616（2026.03.02） ความหมายของเอฟเฟกต์พิเศษ “โฮโลเมมนี้นับว่าเป็น〈ときのそら〉และ〈AZKi〉ด้วย” ในการ์ด hSD01-013〈SorAZ〉 คืออะไร? หมายถึงถือว่าการ์ดนี้มีชื่อการ์ดเป็น〈ときのそら〉, 〈AZKi〉 และ〈SorAZ〉พร้อมกัน Q602（2026.03.02） เมื่อมี hSD01-013〈SorAZ〉 ของตัวเองอยู่ 1 ใบ และได้คอลลาบกับ hBP07-068〈AZKi〉 ในกรณีนี้ จะนับ〈SorAZ〉เป็นทั้ง〈ときのそら〉และ〈SorAZ〉สองคนได้ไหม ตามเอฟเฟกต์คอลลาบ “เส้นทางที่เดินมาด้วยกัน”? ไม่ได้ Q404（2025.06.11） เมื่อใช้ hBP04-089〈ツートンカラーパソコン〉 แล้วเลือก〈ときのそら〉และ〈フワワ・アビスガード〉เป็นโฮโลเมมคนละสีที่มีแค่สีเดียว จะสามารถเพิ่ม hSD01-013〈SorAZ〉 และ hBP03-050〈FUWAMOCO〉 เข้ามือได้ไหม? ได้ สามารถเพิ่มเข้ามือได้ Q402（2025.06.11） คำว่า “โฮโลเมมที่มีเพียงสีเดียวและเป็นคนละสี” ใน hBP04-089〈ツートンカラーパソコン〉 หมายถึงอะไร? หมายถึงโฮโลเมมนั้นมีสีเดียวเท่านั้น และมีมากกว่าหนึ่งคน ตัวอย่างเช่น hBP01-021〈ときのそら〉 มีสีเดียว แต่ hSD01-013〈SorAZ〉 มีสองสี Q250（2024.12.12） สามารถใช้ hBP02-078〈かなた建設〉 เพื่อเพิ่ม hSD01-013〈SorAZ〉 เข้ามือได้ไหม? ได้ สามารถทำได้ Q116（2024.09.21） ถ้า hSD01-013〈SorAZ〉 ของตัวเองมี hBP01-124〈開拓者〉 ติดอยู่ แล้ว Bloom เป็น hBP01-023〈ときのそら〉 hBP01-124〈開拓者〉 จะยังคงอยู่ไหม? ไม่, hBP01-124〈開拓者〉 จะถูกส่งไปยังโซนอาร์ไคฟ์ Q17（2024.09.21） ในข้อความของ hSD01-021〈First Gravity〉 มีระบุว่า “เปิดเผย〈ときのそら〉 และ〈AZKi〉ตามจำนวนที่ต้องการ” สามารถเปิดเผย hSD01-013〈SorAZ〉 แล้วเพิ่มเข้ามือได้ไหม? ได้ สามารถทำได้ ถึงจะไม่มีการ์ดที่มีชื่อตรงในชื่อการ์ด แต่ถ้ามีการ์ดที่มีเอฟเฟกต์พิเศษแบบ “โฮโลเมมนี้นับว่าเป็น〈ときのそら〉〈AZKi〉ด้วย” ก็ถือว่าเข้าเงื่อนไขได้ Q13（2024.09.21） ถ้า hSD01-013〈SorAZ〉 อยู่ในตำแหน่งเซ็นเตอร์ แล้ว hSD01-015〈博衣こより〉 ของตัวเองทำคอลลาบ เอฟเฟกต์คอลลาบจะทำงานทั้งสองฝั่งไหม? ได้ ทำงานทั้งสองฝั่ง เพราะ hSD01-013〈SorAZ〉 ถือว่าเป็น〈ときのそら〉และ〈AZKi〉 ด้วยจากเอฟเฟกต์พิเศษ จึงนับว่าโฮโลเมมทั้งสองชื่อนั้นอยู่บนสเตจ Q12（2025.12.18） เอฟเฟกต์พิเศษของ hSD01-013〈SorAZ〉 ที่ว่า “โฮโลเมมนี้นับว่าเป็น〈ときのそら〉〈AZKi〉ด้วย” จะยังคงใช้ได้แม้อยู่ในโซนอื่นนอกจากสเตจไหม? ได้ ใช้ได้ทุกโซน Q11（2024.09.21） สามารถใช้สกิลอาร์ต “อนาคตที่อยากก้าวข้าม” ของ hSD01-013〈SorAZ〉 ได้ไหม หากเด็คหรือเด็คเอลของตัวเองเหลือ 0 ใบ? ได้ สามารถใช้ได้ หลังจากประกาศใช้สกิลแล้ว ให้แก้ผลตามที่สามารถทำได้ก่อน แล้วจึงคำนวณความเสียหายจากอาร์ต Q10（2024.09.21） อาร์ต “SorAZ กราวิตี” ของ hSD01-011〈AZKi〉 หากไม่มี〈ときのそら〉อยู่ในโฮโลเมม แต่มี hSD01-013〈SorAZ〉 จะสามารถส่งการ์ด 1 ใบจากบนเด็คเอลไปยังโฮโลเมมของตัวเองได้ไหม? ได้ สามารถส่งได้ ถึงไม่มีชื่อการ์ด〈ときのそら〉จริง ๆ แต่ถ้ามีการ์ดที่มีเอฟเฟกต์ว่า “โฮโลเมมนี้นับว่าเป็น〈ときのそら〉〈AZKi〉ด้วย” ก็ถือว่าเข้าเงื่อนไข Q5（2024.09.21） อาร์ต “SorAZ ซิมพาธี” ของ hSD01-006〈ときのそら〉 จะได้รับ “อาร์ตนี้ +50” ไหม เมื่อมี hSD01-013〈SorAZ〉 อยู่ในโฮโลเมมของตัวเอง? ได้ จะได้รับ +50 ถึงไม่มีชื่อการ์ด〈ときのそら〉ตรง ๆ แต่หากมีการ์ดที่มีเอฟเฟกต์ว่า “โฮโลเมมนี้นับว่าเป็น〈ときのそら〉〈AZKi〉ด้วย” ก็ถือว่าเข้าเงื่อนไขนั้น SorAZ #JP #0期生 #歌 Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉. Futuro que quiero superar Puedes tirar un dado una vez: si sale número impar, envía la carta superior de tu mazo de apoyo a este Holomen. Si sale número par, roba una carta de tu mazo. Q616（2026.03.02） ¿Qué significa la habilidad extra de hSD01-013〈SorAZ〉 “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉”? Indica que posee los nombres de carta 〈ときのそら〉, 〈AZKi〉 y 〈SorAZ〉. Q602（2026.03.02） Si tienes un hSD01-013〈SorAZ〉 y hBP07-068〈AZKi〉 realiza una colaboración, ¿puede contarse hSD01-013〈SorAZ〉 como dos Holomen, 〈ときのそら〉 y 〈SorAZ〉, para el efecto de colaboración “Huella de lo que caminamos juntas”? No, no puede. Q404（2025.06.11） Usando hBP04-089〈ツートンカラーパソコン〉, si eliges como Holomen de distinto color pero de un solo color cada uno a 〈ときのそら〉 y 〈フワワ・アビスガード〉 en tu escenario, ¿puedes añadir a tu mano a hSD01-013〈SorAZ〉 y hBP03-050〈FUWAMOCO〉 como 1st Holomen del mismo color que los elegidos? Sí, puedes añadirlos. Q402（2025.06.11） ¿Qué significa “Holomen de un solo color y de distinto color” en el texto de hBP04-089〈ツートンカラーパソコン〉? Significa que esos Holomen tienen un solo color cada uno, y que hay al menos dos con colores distintos. Por ejemplo, hBP01-021〈ときのそら〉 tiene un solo color, mientras que hSD01-013〈SorAZ〉 tiene dos colores. Q250（2024.12.12） ¿Puedo usar hBP02-078〈かなた建設〉 para añadir hSD01-013〈SorAZ〉 a mi mano? Sí, puedes hacerlo. Q116（2024.09.21） Si mi hSD01-013〈SorAZ〉 con hBP01-124〈開拓者〉 unido se hace Bloom hacia hBP01-023〈ときのそら〉, ¿sigue hBP01-124〈開拓者〉 unido? No, hBP01-124〈開拓者〉 se archiva. Q17（2024.09.21） En hSD01-021〈First Gravity〉 se indica “revela cualquier número de cartas 〈ときのそら〉 y 〈AZKi〉”. ¿Puedo revelar hSD01-013〈SorAZ〉 y añadirla a mi mano? Sí, puedes hacerlo. Aunque una carta no tenga exactamente ese nombre, si tiene una habilidad extra como “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉”, cumple la condición. Q13（2024.09.21） Si hSD01-013〈SorAZ〉 está en la posición central y hSD01-015〈博衣こより〉 realiza una colaboración, ¿se activan ambas habilidades de colaboración? Sí, ambas se activan. Debido a su habilidad extra, hSD01-013〈SorAZ〉 se considera también como 〈ときのそら〉 y 〈AZKi〉, y por tanto ambas Holomen se consideran presentes en el escenario. Q12（2025.12.18） ¿La habilidad extra “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉” de hSD01-013〈SorAZ〉 aplica también cuando no está en el escenario? Sí, se aplica. Q11（2024.09.21） ¿Puedo usar el Arte “Futuro que quiero superar” de hSD01-013〈SorAZ〉 incluso si mi mazo o mazo de apoyo tiene 0 cartas? Sí, puedes usarlo. Después de declarar el uso del Arte, resuelves los efectos escritos en el texto tanto como sea posible y luego causas el daño del Arte. Q10（2024.09.21） En el Arte “SorAZ Gravity” de hSD01-011〈AZKi〉, si no tengo 〈ときのそら〉 entre mis Holomen, ¿puedo enviar la carta superior de mi mazo de apoyo a uno de mis Holomen si tengo hSD01-013〈SorAZ〉? Sí, puedes hacerlo. Aunque una carta no tenga exactamente ese nombre, si tiene una habilidad extra como “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉”, cumple la condición. Q5（2024.09.21） En el Arte “SorAZ Sympathy” de hSD01-006〈ときのそら〉, ¿recibe igualmente “este Arte +50.” si tengo hSD01-013〈SorAZ〉 entre mis Holomen? Sí, recibe +50. Aunque una carta no tenga exactamente ese nombre, si tiene una habilidad extra como “Este Holomen también se considera como 〈ときのそら〉 y 〈AZKi〉”, cumple la condición.');
