INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('18', 'hSD01-018', 'supportItem', 'C', NULL, 'hSD01/hSD01-018_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-018_C.png', NULL, NULL, NULL, NULL, 'JinArt こばやかわやまと', 'サブパソコン', '{"card_sets":["スタートデッキ「ときのそら＆AZKi」","スタートデッキ 赤 百鬼あやめ","スタートデッキ 黄 不知火フレア"],"translations":{"en":{"ability_text":"Look at the top 5 cards of your deck. Reveal a LIMITED Support card from among them and add it to your hand. Then, put the remaining cards on the bottom of your deck in any order.","name":"サブパソコン"},"es":{"ability_text":"Mira las 5 cartas superiores de tu mazo. Revela 1 carta de apoyo LIMITED de entre ellas y añádela a tu mano. Luego, coloca las cartas restantes en la parte inferior del mazo en el orden que prefieras.","name":"サブパソコン"},"id":{"ability_text":"Lihat 5 kartu teratas dari dek Anda. Dari kartu-kartu tersebut, ungkap 1 kartu Support bertipe LIMITED, lalu tambahkan ke tangan. Kembalikan sisa kartu ke bawah dek dengan urutan yang Anda inginkan.","name":"サブパソコン"},"ja":{"ability_text":"自分のデッキの上から5枚を見る。その中から、LIMITEDのサポートカード1枚を公開し、手札に加える。そして残ったカードを好きな順でデッキの下に戻す。","name":"サブパソコン"},"ko":{"ability_text":"자신의 덱 위에서 5장을 본다. 그중에서 LIMITED 서포트 카드 1장을 공개하고, 패에 넣는다. 그리고 남은 카드를 원하는 순서로 덱 아래로 되돌린다.","name":"サブパソコン"},"tc":{"ability_text":"查看自己牌庫上方5張牌，從中公開1張LIMITED的支援卡並加入手牌。將剩下的牌以任意順序放回牌庫底。","name":"サブパソコン"},"th":{"ability_text":"從自己的牌組頂翻開5張。從中公開1張限定（LIMITED）支援卡，並加入手牌。然後把剩下的卡按任意順序放回牌組底。","name":"サブパソコン"}}}', '{}', '0b117e0a9be0cd9acb8591789ea1991054c972709788953986383e83e8199e01', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
