INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ 黄 不知火フレア', '18');
INSERT INTO cards_fts (rowid, card_number, text) VALUES (18, 'hSD01-018', 'hSD01-018 JinArt こばやかわやまと サブパソコン 自分のデッキの上から5枚を見る。その中から、LIMITEDのサポートカード1枚を公開し、手札に加える。そして残ったカードを好きな順でデッキの下に戻す。 サブパソコン Look at the top 5 cards of your deck. Reveal a LIMITED Support card from among them and add it to your hand. Then, put the remaining cards on the bottom of your deck in any order. サブパソコン 查看自己牌庫上方5張牌，從中公開1張LIMITED的支援卡並加入手牌。將剩下的牌以任意順序放回牌庫底。 サブパソコン Lihat 5 kartu teratas dari dek Anda. Dari kartu-kartu tersebut, ungkap 1 kartu Support bertipe LIMITED, lalu tambahkan ke tangan. Kembalikan sisa kartu ke bawah dek dengan urutan yang Anda inginkan. サブパソコン 자신의 덱 위에서 5장을 본다. 그중에서 LIMITED 서포트 카드 1장을 공개하고, 패에 넣는다. 그리고 남은 카드를 원하는 순서로 덱 아래로 되돌린다. サブパソコン 從自己的牌組頂翻開5張。從中公開1張限定（LIMITED）支援卡，並加入手牌。然後把剩下的卡按任意順序放回牌組底。 サブパソコン Mira las 5 cartas superiores de tu mazo. Revela 1 carta de apoyo LIMITED de entre ellas y añádela a tu mano. Luego, coloca las cartas restantes en la parte inferior del mazo en el orden que prefieras.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('19', 'hSD01-019', 'supportItemLimited', 'C', NULL, 'hSD01/hSD01-019_C_02', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-019_C_02.png', NULL, NULL, NULL, NULL, 'JinArt KABAKURA', 'スゴイパソコン', '{"card_sets":["ブースターパック「ブルーミングレディアンス」","スタートデッキ「ときのそら＆AZKi」","スタートデッキ 青 猫又おかゆ","スタートデッキ 紫 癒月ちょこ","スタートデッキ FLOW GLOW 推し 虎金妃笑虎","スタートデッキ 推し Justice","ライブスタートデッキ 白上フブキ","ライブスタートデッキ 儒烏風亭らでん","ライブスタートデッキ さくらみこ","ライブスタートデッキ 星街すいせい","ライブスタートデッキ 大空スバル"],"translations":{"en":{"ability_text":"You can’t use this card unless you archive 1 of your Cheers from your Stage.\n\nReveal 1 [1st Holomen or 2nd Holomen] card other than Buzz from your deck, add it to your hand, then shuffle your deck.\n\nLIMITED: You can only use 1 per turn.","name":"スゴイパソコン"},"es":{"ability_text":"No puedes usar esta carta a menos que archives 1 carta de Apoyo en tu Escenario.\n\r\nRevela 1 carta de tu mazo que sea un [1stホロメン o 2ndホロメン] que no sea Buzz, agrégala a tu mano y luego baraja tu mazo.\n\r\nLIMITED: Solo puedes usar 1 por turno.","name":"スゴイパソコン"},"id":{"ability_text":"Kartu ini tidak bisa digunakan kecuali kamu mengarsipkan 1 kartu Yell di Stage kamu.\n\r\nPerlihatkan 1 kartu [1st Holomen atau 2nd Holomen] selain Buzz dari Deck kamu, tambahkan ke tanganmu. Lalu kocok Deck kamu.\n\r\nLIMITED: Hanya dapat digunakan 1 kali per giliran.","name":"スゴイパソコン"},"ja":{"ability_text":"このカードは、自分のステージのエール1枚をアーカイブしなければ使えない。\n\r\n自分のデッキから、Buzz以外の[1stホロメンか2ndホロメン]1枚を公開し、手札に加える。そしてデッキをシャッフルする。\n\r\nLIMITED:ターンに1枚しか使えない。","name":"スゴイパソコン"},"ko":{"ability_text":"이 카드는 자신의 스테이지에 있는 에일 한 장을 아카이브하지 않으면 사용할 수 없다.\n\r\n자신의 덱에서 Buzz가 아닌 [1st 홀로멘 또는 2nd 홀로멘] 한 장을 공개하고, 패에 추가한다. 그 후 덱을 셔플한다.\n\r\nLIMITED: 턴당 한 장만 사용할 수 있다.","name":"스고이파소콘"},"tc":{"ability_text":"使用這張卡時，必須先將自己場上的 1 張應援卡存檔。\n\r\n從自己的牌庫中公開 1 張非 Buzz 的 [1st 成員或 2nd 成員]，將其加入手牌。然後洗牌。\n\r\nLIMITED：每回合只能使用 1 張。","name":"スゴイパソコン"},"th":{"ability_text":"ไม่สามารถใช้การ์ดนี้ได้ เว้นแต่จะอาร์ไคฟ์การ์ดเยล 1 ใบบนสเตจของตัวเองก่อน\n\r\nเปิดเผยการ์ด [1stホロメン หรือ 2ndホロメン] ที่ไม่ใช่ Buzz 1 ใบจากเด็คของตัวเอง แล้วเพิ่มการ์ดนั้นเข้ามือ จากนั้นสับเด็ค\n\r\nLIMITED: ใช้ได้เพียง 1 ใบต่อเทิร์นเท่านั้น","name":"スゴイパソコン"}}}', '{"en":[{"answer":"Yes, you don’t have to reveal anything. In that case, shuffle your deck and the effect ends.","question":"When using hSD01-019〈スゴイパソコン〉, if the desired card is not in your deck, can you choose not to reveal anything?","related_cards":{"card_number":["hSD01-019"],"raw_html":"[hSD01-019 ： スゴイパソコン]"},"title":"Q639 (2026.04.16)"},{"answer":"No, you cannot. When an ability specifies only a card name or card type, you can only choose cards that are on your Stage.","question":"For hSD01-019〈スゴイパソコン〉, the text says “You can’t use this card unless you archive 1 of your Cheers.” — can the Cheer be taken from the Cheer Deck and archived?","related_cards":{"card_number":["hSD01-019"],"raw_html":"[hSD01-019 ： スゴイパソコン]"},"title":"Q15 (2024.09.21)"}],"es":[{"answer":"Sí, puedes optar por no revelar ninguna. En ese caso, baraja tu mazo y la habilidad termina.","question":"Cuando usas hSD01-019〈スゴイパソコン〉 y no hay ninguna carta deseada en tu mazo, ¿puedes no revelar ninguna carta?","related_cards":{"card_number":["hSD01-019"],"raw_html":"[hSD01-019 ： スゴイパソコン]"},"title":"Q639（2026.04.16）"},{"answer":"No, no puedes. Cuando una habilidad solo especifica el nombre o tipo de carta, solo puedes elegir cartas que estén en el Escenario.","question":"En el texto de hSD01-019〈スゴイパソコン〉 que dice: «No puedes usar esta carta a menos que archives 1 carta de Apoyo propia», ¿puedo archivar una carta de Apoyo que esté en el mazo de Apoyos?","related_cards":{"card_number":["hSD01-019"],"raw_html":"[hSD01-019 ： スゴイパソコン]"},"title":"Q15（2024.09.21）"}],"id":[{"answer":"Ya, tidak perlu memperlihatkan apa pun. Dalam hal itu, cukup kocok Deck dan kemampuan selesai.","question":"Jika kamu menggunakan hSD01-019〈スゴイパソコン〉 dan tidak ada kartu yang diinginkan di dalam Deck, bolehkah tidak memperlihatkan apa pun?","related_cards":{"card_number":["hSD01-019"],"raw_html":"[hSD01-019 ： スゴイパソコン]"},"title":"Q639（2026.04.16）"},{"answer":"Tidak bisa. Jika kemampuan hanya menentukan nama atau tipe kartu, kamu hanya dapat memilih kartu yang berada di Stage.","question":"Dalam teks kemampuan hSD01-019〈スゴイパソコン〉 yang berbunyi “Kartu ini tidak bisa digunakan kecuali kamu mengarsipkan 1 Yell milikmu.”, apakah Yell yang ada di Deck Yell bisa diarsipkan?","related_cards":{"card_number":["hSD01-019"],"raw_html":"[hSD01-019 ： スゴイパソコン]"},"title":"Q15（2024.09.21）"}],"ja":[{"answer":"はい、公開しなくてもよいです。その場合は、デッキをシャッフルして能力が終了します。","question":"hSD01-019〈スゴイパソコン〉を使い、デッキの中に望むカードがなかった場合、何も公開しなくてもよいですか？","related_cards":{"card_number":["hSD01-019"],"raw_html":"[hSD01-019 ： スゴイパソコン]"},"title":"Q639（2026.04.16）"},{"answer":"いいえ、できません。能力でカード名やカードタイプのみを指定されている場合は、ステージにあるカードのみを選ぶことができます。","question":"hSD01-019〈スゴイパソコン〉の「このカードは、自分のエール１枚をアーカイブしなければ使えない。」とは、エールデッキにあるエールをアーカイブにすることはできますか？","related_cards":{"card_number":["hSD01-019"],"raw_html":"[hSD01-019 ： スゴイパソコン]"},"title":"Q15（2024.09.21）"}],"ko":[{"answer":"네, 공개하지 않아도 됩니다. 그 경우에는 덱을 셔플하고 능력이 종료됩니다.","question":"hSD01-019〈스고이파소콘〉을 사용했는데, 덱 안에 원하는 카드가 없을 경우 아무 것도 공개하지 않아도 되나요?","related_cards":{"card_number":["hSD01-019"],"raw_html":"[hSD01-019 ： スゴイパソコン]"},"title":"Q639（2026.04.16）"},{"answer":"아니요, 할 수 없습니다. 능력에서 카드 이름이나 카드 타입만 지정되어 있는 경우, 스테이지에 있는 카드만 선택할 수 있습니다.","question":"hSD01-019〈스고이파소콘〉의 「이 카드는 자신의 에일 한 장을 아카이브하지 않으면 사용할 수 없다.」는 문장에서, 에일 덱에 있는 에일을 아카이브로 할 수 있나요?","related_cards":{"card_number":["hSD01-019"],"raw_html":"[hSD01-019 ： スゴイパソコン]"},"title":"Q15（2024.09.21）"}],"tc":[{"answer":"是的，可以不公開。在那種情況下，洗牌後此能力結束。","question":"使用 hSD01-019〈スゴイパソコン〉時，如果牌庫中沒有想要的卡，是否可以不公開任何卡？","related_cards":{"card_number":["hSD01-019"],"raw_html":"[hSD01-019 ： スゴイパソコン]"},"title":"Q639（2026.04.16）"},{"answer":"不，可以。當能力僅指定卡名或卡片類型時，只能選擇在舞台上的卡片。","question":"hSD01-019〈スゴイパソコン〉的「使用這張卡時，必須先將自己 1 張應援卡存檔。」可以從應援牌庫中的應援存檔嗎？","related_cards":{"card_number":["hSD01-019"],"raw_html":"[hSD01-019 ： スゴイパソコン]"},"title":"Q15（2024.09.21）"}],"th":[{"answer":"ไม่จำเป็นต้องเปิดเผยครับ/ค่ะ หลังจากนั้นให้สับเด็ค แล้วความสามารถจะสิ้นสุดลง","question":"ถ้าใช้ hSD01-019〈スゴイパソコン〉 แล้วไม่มีการ์ดที่ต้องการอยู่ในเด็ค จำเป็นต้องเปิดเผยการ์ดไหม?","related_cards":{"card_number":["hSD01-019"],"raw_html":"[hSD01-019 ： スゴイパソコン]"},"title":"Q639（2026.04.16）"},{"answer":"ไม่สามารถทำได้ หากความสามารถระบุเพียงชื่อการ์ดหรือประเภทการ์ดเท่านั้น จะสามารถเลือกได้เฉพาะการ์ดที่อยู่บนสเตจเท่านั้น","question":"ข้อความของ hSD01-019〈スゴイパソコン〉 ที่ว่า “การ์ดนี้ไม่สามารถใช้ได้ เว้นแต่จะอาร์ไคฟ์เยล 1 ใบของตัวเอง” หมายถึงสามารถอาร์ไคฟ์เยลจากเด็คเยลได้หรือไม่?","related_cards":{"card_number":["hSD01-019"],"raw_html":"[hSD01-019 ： スゴイパソコン]"},"title":"Q15（2024.09.21）"}]}', 'be3430ff34b3c3d3f95c58f0bdc2c93773e7c83bdbcba97b9a0cb3f4ff5ccd58', '9eeca0d5eec7cdfbb754859831d370afafca9d777bc2d19f5f451127ef40879e', '1970-01-01T00:00:00Z');
