INSERT INTO cards_fts (rowid, card_number, text) VALUES (19, 'hSD01-019', 'hSD01-019 JinArt KABAKURA スゴイパソコン このカードは、自分のステージのエール1枚をアーカイブしなければ使えない。
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('20', 'hSD01-020', 'supportEvent', 'C', NULL, 'hSD01/hSD01-020_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-020_C.png', NULL, NULL, NULL, NULL, 'JinArt KABAKURA', 'ホロリスの輪', '{"card_sets":["ブースターパック「ブルーミングレディアンス」","スタートデッキ「ときのそら＆AZKi」"],"translations":{"en":{"ability_text":"Roll a die: If the result is 3 or higher, send 1 Cheer from your Archive to your Holomen.","name":"Hororisu''s Ring"},"es":{"ability_text":"Lanza un dado una vez: si el resultado es 3 o más, envía 1 carta de Aplauso desde tu Archivo a tu Holomen.","name":"El Círculo de Hololis"},"id":{"ability_text":"Lempar dadu sekali: jika hasilnya 3 atau lebih, kirim 1 kartu Yell dari Arsipmu ke Holomenmu.","name":"Holoris no Wa"},"ja":{"ability_text":"サイコロを1回振る:3以上の時、自分のアーカイブのエール1枚を自分のホロメンに送る。","name":"ホロリスの輪"},"ko":{"ability_text":"주사위를 1번 굴린다: 3 이상이 나오면, 자신의 아카이브에 있는 에ール 1장을 자신의 홀로멘에게 보낸다.","name":"ホロリスの輪"},"tc":{"ability_text":"擲一次骰子：若為3以上，將自己檔案區域中的1張應援卡送給自己的Holomen。","name":"Holoris之環"},"th":{"ability_text":"ทอยลูกเต๋า 1 ครั้ง: ถ้าได้ 3 ขึ้นไป ส่งเอียร์ 1 ใบจากพื้นที่จดจำของตัวเองไปให้โฮโลเมนของตนเอง","name":"ホロリスの輪"}}}', '{"en":[{"answer":"No, you can’t. If you don’t have any Cheers in your Archive, you also cannot roll the die.","question":"Can I use hSD01-020〈ホロリスの輪〉 when I don’t have any Cheers in my Archive?","related_cards":{"card_number":["hSD01-020"],"raw_html":"[hSD01-020 ： ホロリスの輪]"},"title":"Q554 (2026.01.16)"},{"answer":"Yes, the Arts damage is increased. Regardless of the die result, since the effect of the Support Card is activated, it is considered to have been used, so the Arts damage increases.","question":"When using hSD01-020〈ホロリスの輪〉 and the die roll result is 2 or less, if I use the Arts ‘Oh,Hi’ of hBP01-015〈七詩ムメイ〉, is the Arts damage increased?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50 (2024.09.21)"}],"es":[{"answer":"No, no se puede. Si no tienes ninguna carta de Aplauso en tu Archivo, tampoco puedes simplemente lanzar el dado.","question":"¿Se puede usar hSD01-020〈ホロリスの輪〉 cuando no tienes ninguna carta de Aplauso en tu Archivo?","related_cards":{"card_number":["hSD01-020"],"raw_html":"[hSD01-020 ： ホロリスの輪]"},"title":"Q554（2026.01.16）"},{"answer":"Sí, el daño del arte se incrementa. Independientemente del resultado del dado, la habilidad de la carta de soporte se activa, por lo que se considera usada y el daño del arte se incrementa.","question":"Si usas hSD01-020〈ホロリスの輪〉 y el resultado del dado es 2 o menos, luego usas el arte «Oh,Hi» de hBP01-015〈七詩ムメイ〉, ¿el daño del arte se incrementa?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"}],"id":[{"answer":"Tidak bisa. Jika di Arsipmu tidak ada Yell, kamu juga tidak dapat hanya melempar dadu saja.","question":"Apakah saya bisa menggunakan hSD01-020〈Holoris no Wa〉 ketika di Arsip saya tidak ada Yell?","related_cards":{"card_number":["hSD01-020"],"raw_html":"[hSD01-020 ： Holoris no Wa]"},"title":"Q554（2026.01.16）"},{"answer":"Ya, damage arts akan bertambah. Terlepas dari hasil dadu, kemampuan kartu Support tetap aktif, sehingga dianggap telah digunakan dan damage arts akan bertambah.","question":"Ketika menggunakan hSD01-020〈Holoris no Wa〉 dan hasil dadu adalah 2 atau kurang, jika saya menggunakan arts dari hBP01-015〈七詩ムメイ〉 “Oh,Hi”, apakah damage arts-nya akan bertambah?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： Holoris no Wa]"},"title":"Q50（2024.09.21）"}],"ja":[{"answer":"いいえ、できません。自分のアーカイブにエールがない場合、サイコロのみを振ることもできません。","question":"自分のアーカイブにエールがない時に、hSD01-020〈ホロリスの輪〉を使用することはできますか？","related_cards":{"card_number":["hSD01-020"],"raw_html":"[hSD01-020 ： ホロリスの輪]"},"title":"Q554（2026.01.16）"},{"answer":"はい、アーツダメージはプラスされます。サイコロの結果は問わず、サポートカードの能力は発揮されているので、使用したとみなされアーツダメージがプラスされます。","question":"hSD01-020〈ホロリスの輪〉を使用し、サイコロの目が2以下の時に、hBP01-015〈七詩ムメイ〉のアーツ「Oh,Hi」を使用した場合、アーツダメージはプラスされますか？","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"}],"ko":[{"answer":"아니요, 사용할 수 없습니다. 자신의 아카이브에 에ール이 없을 경우, 주사위만 굴리는 것도 불가능합니다.","question":"자신의 아카이브에 에ール이 없을 때, hSD01-020〈ホロリスの輪〉을(를) 사용할 수 있나요?","related_cards":{"card_number":["hSD01-020"],"raw_html":"[hSD01-020 ： ホロリスの輪]"},"title":"Q554（2026.01.16）"},{"answer":"네, 아츠 데미지가 추가됩니다. 주사위 결과와 관계없이 서포트 카드의 능력이 발휘되고 있으므로, 사용된 것으로 간주되어 아츠 데미지가 추가됩니다.","question":"hSD01-020〈ホロリスの輪〉을(를) 사용해서 주사위 눈이 2 이하일 때, hBP01-015〈七詩ムメイ〉의 아츠 「Oh,Hi」를 사용하면, 아츠 데미지가 추가되나요?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"}],"tc":[{"answer":"不可以。若自己的檔案區域中沒有應援卡，則無法僅擲骰子。","question":"當自己的檔案區域中沒有應援卡時，可以使用hSD01-020〈Holoris之環〉嗎？","related_cards":{"card_number":["hSD01-020"],"raw_html":"[hSD01-020 ： Holoris之環]"},"title":"Q554（2026.01.16）"},{"answer":"會，藝術傷害會增加。無論骰子結果如何，因為支援卡的能力已經發動，所以視為已使用，藝術傷害會增加。","question":"使用hSD01-020〈Holoris之環〉時，若骰子點數為2以下，再使用hBP01-015〈七詩ムメイ〉的アーツ「Oh,Hi」，藝術傷害會增加嗎？","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： Holoris之環]"},"title":"Q50（2024.09.21）"}],"th":[{"answer":"ไม่สามารถทำได้ ถ้าในพื้นที่จดจำของตัวเองไม่มีเอียร์ จะไม่สามารถทอยลูกเต๋าเพียงอย่างเดียวได้เช่นกัน","question":"สามารถใช้ hSD01-020〈ホロリスの輪〉 ได้หรือไม่ หากในพื้นที่จดจำของตัวเองไม่มีเอียร์?","related_cards":{"card_number":["hSD01-020"],"raw_html":"[hSD01-020 ： ホロリスの輪]"},"title":"Q554（2026.01.16）"},{"answer":"ใช่ ค่าความเสียหายของอาร์ตส์จะเพิ่มขึ้นไม่ว่าผลของลูกเต๋าจะเป็นเท่าใด เพราะความสามารถของการ์ดซัพพอร์ตได้ทำงานแล้ว จึงถือว่าได้ใช้งานและค่าความเสียหายของอาร์ตส์จะเพิ่มขึ้น","question":"เมื่อใช้ hSD01-020〈ホロリスの輪〉 แล้วทอยลูกเต๋าได้ 2 หรือต่ำกว่า จากนั้นใช้ท่าอาร์ตส์ “Oh,Hi” ของ hBP01-015〈七詩ムメイ〉 ค่าความเสียหายของอาร์ตส์จะเพิ่มขึ้นไหม?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"}]}', 'dc5e1a2b63c29ee307201a990913258239074bcb9239d16f7e94cc9c9ce06a3c', 'cf726cc505526f55630cd64542b22998d888612cfa78cc3072d18ee5314f7e00', '1970-01-01T00:00:00Z');
INSERT INTO card_sets (set_name, card_id) VALUES ('ブースターパック「ブルーミングレディアンス」', '20');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ「ときのそら＆AZKi」', '20');
INSERT INTO cards_fts (rowid, card_number, text) VALUES (20, 'hSD01-020', 'hSD01-020 JinArt KABAKURA ホロリスの輪 サイコロを1回振る:3以上の時、自分のアーカイブのエール1枚を自分のホロメンに送る。 Q554（2026.01.16） 自分のアーカイブにエールがない時に、hSD01-020〈ホロリスの輪〉を使用することはできますか？ いいえ、できません。自分のアーカイブにエールがない場合、サイコロのみを振ることもできません。 Q50（2024.09.21） hSD01-020〈ホロリスの輪〉を使用し、サイコロの目が2以下の時に、hBP01-015〈七詩ムメイ〉のアーツ「Oh,Hi」を使用した場合、アーツダメージはプラスされますか？ はい、アーツダメージはプラスされます。サイコロの結果は問わず、サポートカードの能力は発揮されているので、使用したとみなされアーツダメージがプラスされます。 Hororisu''s Ring Roll a die: If the result is 3 or higher, send 1 Cheer from your Archive to your Holomen. Q554 (2026.01.16) Can I use hSD01-020〈ホロリスの輪〉 when I don’t have any Cheers in my Archive? No, you can’t. If you don’t have any Cheers in your Archive, you also cannot roll the die. Q50 (2024.09.21) When using hSD01-020〈ホロリスの輪〉 and the die roll result is 2 or less, if I use the Arts ‘Oh,Hi’ of hBP01-015〈七詩ムメイ〉, is the Arts damage increased? Yes, the Arts damage is increased. Regardless of the die result, since the effect of the Support Card is activated, it is considered to have been used, so the Arts damage increases. Holoris之環 擲一次骰子：若為3以上，將自己檔案區域中的1張應援卡送給自己的Holomen。 Q554（2026.01.16） 當自己的檔案區域中沒有應援卡時，可以使用hSD01-020〈Holoris之環〉嗎？ 不可以。若自己的檔案區域中沒有應援卡，則無法僅擲骰子。 Q50（2024.09.21） 使用hSD01-020〈Holoris之環〉時，若骰子點數為2以下，再使用hBP01-015〈七詩ムメイ〉的アーツ「Oh,Hi」，藝術傷害會增加嗎？ 會，藝術傷害會增加。無論骰子結果如何，因為支援卡的能力已經發動，所以視為已使用，藝術傷害會增加。 Holoris no Wa Lempar dadu sekali: jika hasilnya 3 atau lebih, kirim 1 kartu Yell dari Arsipmu ke Holomenmu. Q554（2026.01.16） Apakah saya bisa menggunakan hSD01-020〈Holoris no Wa〉 ketika di Arsip saya tidak ada Yell? Tidak bisa. Jika di Arsipmu tidak ada Yell, kamu juga tidak dapat hanya melempar dadu saja. Q50（2024.09.21） Ketika menggunakan hSD01-020〈Holoris no Wa〉 dan hasil dadu adalah 2 atau kurang, jika saya menggunakan arts dari hBP01-015〈七詩ムメイ〉 “Oh,Hi”, apakah damage arts-nya akan bertambah? Ya, damage arts akan bertambah. Terlepas dari hasil dadu, kemampuan kartu Support tetap aktif, sehingga dianggap telah digunakan dan damage arts akan bertambah. ホロリスの輪 주사위를 1번 굴린다: 3 이상이 나오면, 자신의 아카이브에 있는 에ール 1장을 자신의 홀로멘에게 보낸다. Q554（2026.01.16） 자신의 아카이브에 에ール이 없을 때, hSD01-020〈ホロリスの輪〉을(를) 사용할 수 있나요? 아니요, 사용할 수 없습니다. 자신의 아카이브에 에ール이 없을 경우, 주사위만 굴리는 것도 불가능합니다. Q50（2024.09.21） hSD01-020〈ホロリスの輪〉을(를) 사용해서 주사위 눈이 2 이하일 때, hBP01-015〈七詩ムメイ〉의 아츠 「Oh,Hi」를 사용하면, 아츠 데미지가 추가되나요? 네, 아츠 데미지가 추가됩니다. 주사위 결과와 관계없이 서포트 카드의 능력이 발휘되고 있으므로, 사용된 것으로 간주되어 아츠 데미지가 추가됩니다. ホロリスの輪 ทอยลูกเต๋า 1 ครั้ง: ถ้าได้ 3 ขึ้นไป ส่งเอียร์ 1 ใบจากพื้นที่จดจำของตัวเองไปให้โฮโลเมนของตนเอง Q554（2026.01.16） สามารถใช้ hSD01-020〈ホロリスの輪〉 ได้หรือไม่ หากในพื้นที่จดจำของตัวเองไม่มีเอียร์? ไม่สามารถทำได้ ถ้าในพื้นที่จดจำของตัวเองไม่มีเอียร์ จะไม่สามารถทอยลูกเต๋าเพียงอย่างเดียวได้เช่นกัน Q50（2024.09.21） เมื่อใช้ hSD01-020〈ホロリスの輪〉 แล้วทอยลูกเต๋าได้ 2 หรือต่ำกว่า จากนั้นใช้ท่าอาร์ตส์ “Oh,Hi” ของ hBP01-015〈七詩ムメイ〉 ค่าความเสียหายของอาร์ตส์จะเพิ่มขึ้นไหม? ใช่ ค่าความเสียหายของอาร์ตส์จะเพิ่มขึ้นไม่ว่าผลของลูกเต๋าจะเป็นเท่าใด เพราะความสามารถของการ์ดซัพพอร์ตได้ทำงานแล้ว จึงถือว่าได้ใช้งานและค่าความเสียหายของอาร์ตส์จะเพิ่มขึ้น El Círculo de Hololis Lanza un dado una vez: si el resultado es 3 o más, envía 1 carta de Aplauso desde tu Archivo a tu Holomen. Q554（2026.01.16） ¿Se puede usar hSD01-020〈ホロリスの輪〉 cuando no tienes ninguna carta de Aplauso en tu Archivo? No, no se puede. Si no tienes ninguna carta de Aplauso en tu Archivo, tampoco puedes simplemente lanzar el dado. Q50（2024.09.21） Si usas hSD01-020〈ホロリスの輪〉 y el resultado del dado es 2 o menos, luego usas el arte «Oh,Hi» de hBP01-015〈七詩ムメイ〉, ¿el daño del arte se incrementa? Sí, el daño del arte se incrementa. Independientemente del resultado del dado, la habilidad de la carta de soporte se activa, por lo que se considera usada y el daño del arte se incrementa.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('21', 'hSD01-021', 'supportEventLimited', 'C', NULL, 'hSD01/hSD01-021_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hSD01/hSD01-021_C.png', NULL, NULL, NULL, NULL, '© 2023 Victor Entertainment. © 2016 COVER Corp.', 'First Gravity', '{"card_sets":["スタートデッキ「ときのそら＆AZKi」"],"translations":{"en":{"ability_text":"This card can only be used if you have 6 or less cards in hand excluding this card.\n\nLook at the top 4 cards of your deck. Reveal any number of 〈Tokino Sora〉 and/or 〈AZKi〉 from among them, and put the revealed holomem into hand. Then, return the rest to the bottom of the deck in any order.\n\nLIMITED：Usable only 1 per turn.","name":"First Gravity"},"es":{"ability_text":"Solo puedes usar esta carta si, sin contar esta carta, tienes 6 o menos cartas en tu mano.\n\nMira las 4 cartas superiores de tu mazo. Puedes revelar cualquier número de cartas que sean 〈ときのそら〉 o 〈AZKi〉 entre ellas, y añade a tu mano las Holomen reveladas. Coloca las cartas restantes en la parte inferior de tu mazo en el orden que prefieras.\n\nLIMITED: Solo puedes usar una por turno.","name":"First Gravity"},"id":{"ability_text":"Kartu ini hanya bisa digunakan jika jumlah kartu di tangan Anda, tidak termasuk kartu ini, adalah 6 kartu atau kurang.\n\nLihat 4 kartu teratas dari dek Anda. Dari kartu-kartu tersebut, buka sebanyak yang Anda suka dari 〈ときのそら〉 dan 〈AZKi〉, lalu tambahkan anggota Hololive yang dibuka tersebut ke tangan Anda. Kemudian kembalikan sisa kartu ke bawah dek dalam urutan yang Anda inginkan.\n\nLIMITED：Hanya bisa digunakan 1 kali per giliran.","name":"First Gravity"},"ja":{"ability_text":"このカードは、自分の手札がこのカードを含まずに6枚以下でなければ使えない。\n\r\n自分のデッキの上から4枚を見る。その中から、〈ときのそら〉と〈AZKi〉を好きな枚数公開し、公開したホロメンを手札に加える。そして残ったカードを好きな順でデッキの下に戻す。\n\r\nLIMITED:ターンに1枚しか使えない。","name":"First Gravity"},"ko":{"ability_text":"이 카드는, 자신의 패가 이 카드를 제외하고 6장 이하일 때만 사용할 수 있다.\n\n자신의 덱 맨 위에서 카드 4장을 본다. 그중에서 〈ときのそら〉와 〈AZKi〉를 원하는 만큼 공개하고, 공개한 홀로멘을 패에 넣는다. 그리고 남은 카드는 원하는 순서로 덱 아래에 돌려놓는다.\n\nLIMITED: 턴당 1장만 사용할 수 있다.","name":"First Gravity"},"tc":{"ability_text":"這張卡必須在自己的手牌不包含這張卡的情況下為6張以下才能使用。\n\n查看自己牌庫頂的4張牌。從中可公開任意數量的〈ときのそら〉與〈AZKi〉，將公開的Holomen加入手牌。然後將剩下的卡以任意順序放回牌庫底。\n\nLIMITED：每回合只能使用1張。","name":"First Gravity"},"th":{"ability_text":"การ์ดใบนี้ไม่สามารถใช้ได้ถ้ามือของตัวเองมีไพ่รวมกันมากกว่า 6 ใบ โดยไม่รวมการ์ดใบนี้อยู่ด้วย\n\nดูไพ่ 4 ใบจากด้านบนของเด็ค จากไพ่เหล่านั้น เผย〈ときのそら〉และ〈AZKi〉ตามจำนวนที่ต้องการ แล้วนำโฮโลเมนที่เผยไปเข้ามือ จากนั้นนำไพ่ที่เหลือกลับไปไว้ด้านล่างเด็คตามลำดับที่ต้องการ\n\nLIMITED：สามารถใช้ได้ครั้งละ 1 ใบต่อเทิร์น","name":"First Gravity"}}}', '{"en":[{"answer":"Yes, it is possible.Even if there is no corresponding card name, if there exists a card with an extra like ''This holomem is also regarded as 〈Tokino Sora〉〈AZKi〉'' as specific card names, the condition is met.","question":"Regarding hSD01-021〈First Gravity〉''s ''Reveal any number of 〈Tokino Sora〉 and/or 〈AZKi〉,'' can you reveal hSD01-013〈SorAZ〉 and add it to your hand?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021: First Gravity]\n[hSD01-013: SorAZ]"},"title":"Q17（September 21, 2024）"},{"answer":"Yes, it is included.","question":"Regarding hBP01-021〈First Gravity〉''s ''This card can only be used if you have 6 or less cards in hand excluding this card.'' does this include when you have exactly 6 cards?","related_cards":{"card_number":["hSD01-021"],"raw_html":"[hSD01-021: First Gravity]"},"title":"Q16（September 21, 2024）"}],"es":[{"answer":"Sí, puedes. Aunque no exista una carta con ese nombre exacto, si en el Extra hay una carta que indique algo como «esta Holomen también cuenta como 〈ときのそら〉 y 〈AZKi〉», entonces cumple con las condiciones.","question":"En el texto de hSD01-021〈First Gravity〉 dice «puedes revelar cualquier número de 〈ときのそら〉 y 〈AZKi〉». ¿Puedo revelar y añadir a la mano una hSD01-013〈SorAZ〉?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"Sí, lo incluye.","question":"En el texto de hSD01-021〈First Gravity〉 dice «Solo puedes usar esta carta si, sin contar esta carta, tienes 6 o menos cartas en tu mano». ¿Incluye el caso cuando tienes exactamente 6?","related_cards":{"card_number":["hSD01-021"],"raw_html":"[hSD01-021 ： First Gravity]"},"title":"Q16（2024.09.21）"}],"id":[{"answer":"Ya, bisa. Bahkan jika nama kartu yang cocok tidak ada dalam nama kartu aslinya, jika ada kartu di area ekstra yang memperlakukan anggota Hololive tersebut sebagai nama kartu tertentu misalnya “anggota Hololive ini juga diperlakukan sebagai 〈ときのそら〉〈AZKi〉”, maka kondisi itu terpenuhi.","question":"Di hSD01-021〈First Gravity〉 tertulis “buka sebanyak yang Anda suka dari 〈ときのそら〉 dan 〈AZKi〉,” apakah saya bisa membuka hSD01-013〈SorAZ〉 dan menambahkannya ke tangan?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"Ya, termasuk.","question":"Di hSD01-021〈First Gravity〉 tertulis “Kartu ini hanya bisa digunakan jika jumlah kartu di tangan Anda, tidak termasuk kartu ini, adalah 6 kartu atau kurang.” apakah itu termasuk saat jumlahnya 6?","related_cards":{"card_number":["hSD01-021"],"raw_html":"[hSD01-021 ： First Gravity]"},"title":"Q16（2024.09.21）"}],"ja":[{"answer":"はい、できます。カード名称に該当のカードがない場合でもエクストラに「このホロメンは〈ときのそら〉〈AZKi〉としても扱う」の様に特定のカード名として扱うカードが存在している場合は、その条件を満たします。","question":"hSD01-021〈First Gravity〉の「〈ときのそら〉と〈AZKi〉を好きな枚数公開し、」とありますが、hSD01-013〈SorAZ〉を公開し、手札に加えることはできますか？","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"はい、含みます。","question":"hSD01-021〈First Gravity〉の「このカードは、自分の手札がこのカードを含まずに６枚以下でなければ使えない。」とは6枚のときも含みますか？","related_cards":{"card_number":["hSD01-021"],"raw_html":"[hSD01-021 ： First Gravity]"},"title":"Q16（2024.09.21）"}],"ko":[{"answer":"네, 가능합니다. 카드 명칭에 해당 카드가 없더라도, 엑스트라에 「이 홀로멘은 〈ときのそら〉〈AZKi〉로도 취급한다」와 같이 특정 카드명으로 취급하는 카드가 존재할 경우 그 조건을 만족합니다.","question":"hSD01-021〈First Gravity〉의 「〈ときのそら〉와 〈AZKi〉를 원하는 만큼 공개하고,」라고 되어 있는데, hSD01-013〈SorAZ〉를 공개해서 패에 넣을 수 있나요?","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"네, 포함됩니다.","question":"hSD01-021〈First Gravity〉의 「이 카드는, 자신의 패가 이 카드를 제외하고 6장 이하일 때만 사용할 수 있다.」라는 조건은 6장일 때도 포함되나요?","related_cards":{"card_number":["hSD01-021"],"raw_html":"[hSD01-021 ： First Gravity]"},"title":"Q16（2024.09.21）"}],"tc":[{"answer":"可以。即使卡牌名稱中沒有對應名稱，但如果額外有「此Holomen也視為〈ときのそら〉〈AZKi〉」等效果的卡牌存在，也能滿足條件。","question":"hSD01-021〈First Gravity〉的「可公開任意數量的〈ときのそら〉與〈AZKi〉，」那麼可以公開hSD01-013〈SorAZ〉並將其加入手牌嗎？","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"是的，包含。","question":"hSD01-021〈First Gravity〉的「這張卡必須在自己的手牌不包含這張卡的情況下為6張以下才能使用。」是否包含正好6張的情況？","related_cards":{"card_number":["hSD01-021"],"raw_html":"[hSD01-021 ： First Gravity]"},"title":"Q16（2024.09.21）"}],"th":[{"answer":"ได้ครับ/ค่ะ สามารถทำได้ แม้ชื่อการ์ดนั้นจะไม่ตรงกับชื่อที่ระบุ หากการ์ดเอ็กซ์ตรามีข้อความที่ทำให้การ์ดนั้น\"ถูกนับว่าเป็น〈ときのそら〉หรือ〈AZKi〉\" ก็ถือว่าเป็นไปตามเงื่อนไข","question":"hSD01-021〈First Gravity〉の「〈ときのそら〉と〈AZKi〉を好きな枚数公開し、」とありますが、hSD01-013〈SorAZ〉を公開し、手札に加えることはできますか？","related_cards":{"card_number":["hSD01-021","hSD01-013"],"raw_html":"[hSD01-021 ： First Gravity]\n[hSD01-013 ： SorAZ]"},"title":"Q17（2024.09.21）"},{"answer":"ใช่ รวมถึงตอนที่มี 6 ใบด้วย","question":"hSD01-021〈First Gravity〉の「このカードは、自分の手札がこのカードを含まずに６枚以下でなければ使えない。」とは6枚のときも含みますか？","related_cards":{"card_number":["hSD01-021"],"raw_html":"[hSD01-021 ： First Gravity]"},"title":"Q16（2024.09.21）"}]}', '70dfc25272dfb7ec9b7a704f23d9d60f9810a01a1be8579878bba8ac16b0c916', 'fdaeb014b484f4516fed895381142270b8c62f4c12069400b062f3b47d9c1df7', '1970-01-01T00:00:00Z');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ「ときのそら＆AZKi」', '21');
INSERT INTO cards_fts (rowid, card_number, text) VALUES (21, 'hSD01-021', 'hSD01-021 © 2023 Victor Entertainment. © 2016 COVER Corp. First Gravity このカードは、自分の手札がこのカードを含まずに6枚以下でなければ使えない。
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('23', 'hBP01-001', 'oshiCharacter', 'OUR', NULL, 'hBP01/hBP01-001_OUR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-001_OUR.png', NULL, 5, NULL, NULL, 'Hiroko', '天音かなた', '{"card_sets":["ブースターパック「ブルーミングレディアンス」"],"color_codes":["white"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"天音かなた","oshi_skill":{"effect":"[Once per turn] Set the remaining HP of your opponent’s Center Holomem to 50.","name":"Gyugyu"},"sp_oshi_skill":{"effect":"[Once per game] During this turn, one of your Holomems gets Arts +50. If that Holomem is white, it gets an additional +50 Arts.","name":"I’ll Crush You in My Hand"}},"es":{"name":"天音かなた","oshi_skill":{"effect":"[Una vez por turno] Reduce el HP restante del holomen central del oponente a 50.","name":"ぎゅっぎゅっ"},"sp_oshi_skill":{"effect":"[Una vez por partida] Durante este turno, uno de tus holomen obtiene +50 en Artes. Si ese holomen es de color blanco, obtiene +50 adicionales.","name":"握りつぶしちゃうぞ"}},"id":{"name":"天音かなた","oshi_skill":{"effect":"[Sekali per giliran] Kurangi sisa HP Holomen pusat lawan menjadi 50.","name":"ぎゅっぎゅっ"},"sp_oshi_skill":{"effect":"[Sekali per game] Selama giliran ini, Arts salah satu Holomen kamu bertambah +50. Jika Holomen tersebut berwarna putih, tambahkan lagi +50 pada Arts-nya.","name":"握りつぶしちゃうぞ"}},"ja":{"name":"天音かなた","oshi_skill":{"effect":"[ターンに1回]相手のセンターホロメンの残りHPを50にする。","name":"ぎゅっぎゅっ","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]このターンの間、自分のホロメン1人のアーツ+50。そのホロメンの色が白の時、さらに、そのアーツ+50。","name":"握りつぶしちゃうぞ","timing":"ゲームに1回"}},"ko":{"name":"天音かなた","oshi_skill":{"effect":"[턴당 1회] 상대 센터 홀로멘의 남은 HP를 50으로 만든다.","name":"꽉꽉"},"sp_oshi_skill":{"effect":"[게임당 1회] 이번 턴 동안, 내 홀로멘 한 명의 아츠 +50. 그 홀로멘의 색이 흰색일 경우, 추가로 아츠 +50.","name":"으깨버릴 거야"}},"tc":{"name":"天音かなた","oshi_skill":{"effect":"[每回合1次]將對手中央Holomen的剩餘HP變為50。","name":"ぎゅっぎゅっ"},"sp_oshi_skill":{"effect":"[每場遊戲1次]這回合期間，使我方1位Holomen的Arts +50。若該Holomen的顏色為白色，則再額外使該Holomen的Arts +50。","name":"握りつぶしちゃうぞ"}},"th":{"name":"天音かなた","oshi_skill":{"effect":"[ครั้งละ 1 เทิร์น] ทำให้ HP ที่เหลือของโฮโลเมนตรงกลางของคู่ต่อสู้เหลือ 50","name":"ぎゅっぎゅっ"},"sp_oshi_skill":{"effect":"[ครั้งละ 1 เกม] ในเทิร์นนี้ โฮโลเมนของตัวเอง 1 คน จะได้รับค่าอาร์ตส์ +50 ถ้าโฮโลเมนคนนั้นเป็นสีขาว ค่าอาร์ตส์ของคนนั้นจะได้รับเพิ่มอีก +50","name":"握りつぶしちゃうぞ"}}}}', '{"en":[{"answer":"No, you cannot.","question":"Can you set the remaining HP of a Buzz Holomem equipped with hBP06-097〈カワイイスタジャン〉 to 50 using hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu”?","related_cards":{"card_number":["hBP01-001","hBP06-097"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP06-097 ： カワイイスタジャン]"},"title":"Q536 (2025.12.12)"},{"answer":"No, because HP does not change, so it cannot be set to 50.","question":"Can the gift “冷静沈着” from hBP04-024〈儒烏風亭らでん〉 allow you to set the remaining HP to 50 using hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu”?","related_cards":{"card_number":["hBP01-001","hBP04-024"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP04-024 ： 儒烏風亭らでん]"},"title":"Q382 (2025.06.11)"},{"answer":"Yes, it can.","question":"You used hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu” on 〈ときのそら〉 equipped with hBP01-118〈あん肝〉. In this case, can the remaining HP of 〈ときのそら〉 equipped with hBP01-118〈あん肝〉 be set to 50?","related_cards":{"card_number":["hBP01-001","hBP01-118"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-118 ： あん肝]"},"title":"Q362 (2025.03.11)"},{"answer":"No, because HP does not change, so it cannot be set to 50.","question":"Can the gift “Boxing Style” from hBP03-065〈戌神ころね〉 be affected by hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu” to set the remaining HP to 50?","related_cards":{"card_number":["hBP01-001","hBP03-065"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP03-065 ： 戌神ころね]"},"title":"Q327 (2025.03.11)"},{"answer":"No, it does not. The ability of hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu” does not deal damage, so hBP01-116〈うぱお〉’s effect does not trigger.","question":"If you use hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu” on an opponent’s Center Holomem equipped with hBP01-116〈うぱお〉, does your own Center Holomem take special damage from hBP01-116〈うぱお〉’s ability?","related_cards":{"card_number":["hBP01-001","hBP01-116"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-116 ： うぱお]"},"title":"Q26 (2024.09.21)"},{"answer":"No, you cannot. Since it does not deal damage, hYS01-001〈七詩ムメイ〉’s SP Oshi Skill “Quick Guard” cannot be used against hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu”.","question":"Can you use hYS01-001〈七詩ムメイ〉’s SP Oshi Skill “Quick Guard” against hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu”?","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25 (2024.09.21)"},{"answer":"No, you cannot. Since it does not deal damage, hBP01-121〈Kotori〉’s ability cannot be used against hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu”.","question":"Can you use hBP01-121〈Kotori〉’s ability against hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu”?","related_cards":{"card_number":["hBP01-001","hBP01-121"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-121 ： Kotori]"},"title":"Q24 (2024.09.21)"},{"answer":"No, you cannot. Since it does not deal damage, hBP01-117〈フレンド〉’s ability cannot be used against hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu”.","question":"Can you use hBP01-117〈フレンド〉’s ability against hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu”?","related_cards":{"card_number":["hBP01-001","hBP01-117"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-117 ： フレンド]"},"title":"Q23 (2024.09.21)"},{"answer":"No, you cannot. Since it does not deal damage, hBP01-027〈ベスティア・ゼータ〉’s gift “V.7” cannot be used against hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu”.","question":"Can you use the gift “V.7” from hBP01-027〈ベスティア・ゼータ〉 against hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu”?","related_cards":{"card_number":["hBP01-001","hBP01-027"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q22 (2024.09.21)"},{"answer":"No, you cannot. Since hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu” does not deal damage, hBP01-002〈七詩ムメイ〉’s Oshi Skill “Civilization Guardian” cannot be used.","question":"During your opponent’s turn, when your Holomem with #Promise has its remaining HP set to 50 by hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu”, can you use hBP01-002〈七詩ムメイ〉’s Oshi Skill “Civilization Guardian” to reduce its damage by 50?","related_cards":{"card_number":["hBP01-001","hBP01-002"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-002 ： 七詩ムメイ]"},"title":"Q21 (2024.09.21)"},{"answer":"No, it does not trigger. Since hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu” specifies the remaining HP, it does not count as HP recovery.","question":"You use hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu” on an opponent’s Holomem that has 40 remaining HP and is equipped with 〈石の斧〉. When its HP becomes 50, does 〈石の斧〉’s “When this Holomem recovers” ability trigger?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q20 (2024.09.21)"},{"answer":"The opponent’s Holomem’s remaining HP becomes 50.","question":"When hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu” is used on an opponent’s Holomem whose remaining HP is 40 or less, what happens to its HP?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q19 (2024.09.21)"},{"answer":"No, it cannot. Since hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu” does not deal damage, its effect cannot be reduced or prevented.","question":"When your Center Holomem’s HP is reduced to 50 by hBP01-001〈天音かなた〉’s Oshi Skill “Gyugyu”, can hBP01-027〈ベスティア・ゼータ〉’s gift “V.7” be used to prevent the damage?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q18 (2024.09.21)"}],"es":[{"answer":"No, no se puede.","question":"¿Se puede hacer que el holomen Buzz con hBP06-097〈カワイイスタジャン〉 anexado tenga su HP restante reducido a ''50'' por la habilidad oshi de hBP01-001〈天音かなた〉 「ぎゅっぎゅっ」?","related_cards":{"card_number":["hBP01-001","hBP06-097"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP06-097 ： カワイイスタジャン]"},"title":"Q536（2025.12.12）"},{"answer":"No, no puede, ya que el HP no cambia y no se convierte en ''50''.","question":"¿Puede la habilidad de regalo 「冷静沈着」 de hBP04-024〈儒烏風亭らでん〉 hacer que, mediante la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉, el HP restante sea ''50''?","related_cards":{"card_number":["hBP01-001","hBP04-024"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP04-024 ： 儒烏風亭らでん]"},"title":"Q382（2025.06.11）"},{"answer":"Sí, se puede.","question":"Se usó la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉 sobre 〈ときのそら〉 que tiene anexado hBP01-118〈あん肝〉. En este caso, ¿se puede establecer el HP restante de 〈ときのそら〉 con hBP01-118〈あん肝〉 en ''50''?","related_cards":{"card_number":["hBP01-001","hBP01-118"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-118 ： あん肝]"},"title":"Q362（2025.03.11）"},{"answer":"No, no puede, ya que el HP no cambia y no se vuelve ''50''.","question":"¿Puede la habilidad de regalo 「ボクシングスタイル」 de hBP03-065〈戌神ころね〉 permitir que, mediante la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉, el HP restante se convierta en ''50''?","related_cards":{"card_number":["hBP01-001","hBP03-065"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP03-065 ： 戌神ころね]"},"title":"Q327（2025.03.11）"},{"answer":"No, no lo recibe. La habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉 no inflige daño, por lo tanto, la habilidad de hBP01-116〈うぱお〉 no se activa.","question":"Si se usa la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉 sobre el holomen central del oponente que tiene anexado hBP01-116〈うぱお〉, ¿recibe mi holomen central daño especial por la habilidad de hBP01-116〈うぱお〉?","related_cards":{"card_number":["hBP01-001","hBP01-116"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-116 ： うぱお]"},"title":"Q26（2024.09.21）"},{"answer":"No, no se puede usar. Como no es una habilidad que inflige daño, la habilidad SP oshi 「クイックガード」 de hYS01-001〈七詩ムメイ〉 no puede usarse contra la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉.","question":"¿Se puede usar la habilidad SP oshi 「クイックガード」 de hYS01-001〈七詩ムメイ〉 contra la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"},{"answer":"No, no se puede. Como no inflige daño, no se puede usar la habilidad de hBP01-121〈Kotori〉 contra la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉.","question":"¿Se puede usar la habilidad de hBP01-121〈Kotori〉 contra la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP01-121"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-121 ： Kotori]"},"title":"Q24（2024.09.21）"},{"answer":"No, no se puede. Dado que no inflige daño, la habilidad de hBP01-117〈フレンド〉 no puede usarse contra la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉.","question":"¿Se puede usar la habilidad de hBP01-117〈フレンド〉 contra la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP01-117"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-117 ： フレンド]"},"title":"Q23（2024.09.21）"},{"answer":"No, no se puede. Como no inflige daño, la habilidad de regalo 「V.7」 de hBP01-027〈ベスティア・ゼータ〉 no puede usarse contra la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉.","question":"¿Se puede usar el regalo 「V.7」 de hBP01-027〈ベスティア・ゼータ〉 contra la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP01-027"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q22（2024.09.21）"},{"answer":"No, no puede. La habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉 no inflige daño, por lo que no se puede usar la habilidad 「文明の守護者」 de hBP01-002〈七詩ムメイ〉 para reducirlo.","question":"Durante el turno del oponente, si la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉 hace que el HP restante de mi holomen con #Promise sea 50, ¿puede la habilidad oshi 「文明の守護者」 de hBP01-002〈七詩ムメイ〉 reducir dicho daño en -50?","related_cards":{"card_number":["hBP01-001","hBP01-002"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-002 ： 七詩ムメイ]"},"title":"Q21（2024.09.21）"},{"answer":"No, no se activa. La habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉 especifica un valor de HP restante, no restaura HP.","question":"Se usó la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉 sobre un holomen del oponente con HP restante 40 y equipado con 〈石の斧〉. Cuando su HP se convierte en 50, ¿se activa la habilidad de 〈石の斧〉 que dice ''cuando este holomen se recupera''?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q20（2024.09.21）"},{"answer":"El HP restante del holomen oponente se vuelve 50.","question":"Cuando se usa la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉 sobre un holomen oponente con HP restante de 40 o menos, ¿qué sucede con su HP?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q19（2024.09.21）"},{"answer":"No, no se puede. Como la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉 no inflige daño, no es posible reducir ni evitar el daño recibido.","question":"Cuando la habilidad oshi 「ぎゅっぎゅっ」 de hBP01-001〈天音かなた〉 reduce el HP de mi holomen central a 50, ¿puedo evitar el daño con el regalo 「V.7」 de hBP01-027〈ベスティア・ゼータ〉?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q18（2024.09.21）"}],"id":[{"answer":"Tidak, tidak bisa.","question":"Apakah bisa membuat sisa HP Buzz Holomen yang mengenakan hBP06-097〈カワイイスタジャン〉 menjadi ''50'' dengan menggunakan skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP06-097"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP06-097 ： カワイイスタジャン]"},"title":"Q536（2025.12.12）"},{"answer":"Tidak, karena HP tidak berubah, tidak bisa menjadi ''50''.","question":"Apakah gift ''冷静沈着'' dari hBP04-024〈儒烏風亭らでん〉 bisa membuat sisa HP jadi ''50'' ketika terkena skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP04-024"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP04-024 ： 儒烏風亭らでん]"},"title":"Q382（2025.06.11）"},{"answer":"Ya, bisa.","question":"Jika ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 digunakan pada 〈ときのそら〉 yang mengenakan hBP01-118〈あん肝〉, apakah sisa HP 〈ときのそら〉 yang mengenakan hBP01-118〈あん肝〉 bisa menjadi 50?","related_cards":{"card_number":["hBP01-001","hBP01-118"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-118 ： あん肝]"},"title":"Q362（2025.03.11）"},{"answer":"Tidak, karena HP tidak berubah, tidak bisa menjadi ''50''.","question":"Apakah gift ''ボクシングスタイル'' dari hBP03-065〈戌神ころね〉 bisa membuat sisa HP menjadi 50 melalui skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP03-065"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP03-065 ： 戌神ころね]"},"title":"Q327（2025.03.11）"},{"answer":"Tidak, tidak menerima. Karena kemampuan skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 bukan kemampuan yang memberikan damage, kemampuan dari hBP01-116〈うぱお〉 tidak akan aktif.","question":"Jika menggunakan skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 terhadap Holomen pusat lawan yang mengenakan hBP01-116〈うぱお〉, apakah Holomen pusat saya akan menerima damage spesial dari kemampuan hBP01-116〈うぱお〉?","related_cards":{"card_number":["hBP01-001","hBP01-116"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-116 ： うぱお]"},"title":"Q26（2024.09.21）"},{"answer":"Tidak, tidak bisa digunakan. Karena skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 bukan kemampuan yang memberikan damage, maka kemampuan dari SP skill oshi ''クイックガード'' dari hYS01-001〈七詩ムメイ〉 tidak dapat digunakan terhadapnya.","question":"Apakah skill SP oshi ''クイックガード'' dari hYS01-001〈七詩ムメイ〉 bisa digunakan terhadap skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"},{"answer":"Tidak, tidak bisa digunakan. Karena skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 bukan kemampuan yang memberikan damage, kemampuan dari hBP01-121〈Kotori〉 tidak dapat digunakan terhadapnya.","question":"Apakah kemampuan dari hBP01-121〈Kotori〉 bisa digunakan terhadap skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP01-121"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-121 ： Kotori]"},"title":"Q24（2024.09.21）"},{"answer":"Tidak, tidak bisa digunakan. Karena skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 bukan kemampuan yang memberikan damage, kemampuan dari hBP01-117〈フレンド〉 tidak dapat digunakan terhadapnya.","question":"Apakah kemampuan dari hBP01-117〈フレンド〉 bisa digunakan terhadap skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP01-117"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-117 ： フレンド]"},"title":"Q23（2024.09.21）"},{"answer":"Tidak, tidak bisa digunakan. Karena skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 bukan kemampuan yang memberikan damage, gift ''V.7'' dari hBP01-027〈ベスティア・ゼータ〉 tidak bisa digunakan terhadapnya.","question":"Apakah gift ''V.7'' dari hBP01-027〈ベスティア・ゼータ〉 bisa digunakan terhadap skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hBP01-027"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q22（2024.09.21）"},{"answer":"Tidak, tidak bisa. Karena skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 bukan kemampuan yang memberikan damage, kemampuan dari skill oshi ''文明の守護者'' dari hBP01-002〈七詩ムメイ〉 tidak dapat digunakan terhadapnya.","question":"Saat giliran lawan, jika skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 membuat sisa HP Holomen saya yang memiliki #Promise menjadi 50, apakah skill oshi ''文明の守護者'' dari hBP01-002〈七詩ムメイ〉 dapat digunakan untuk mengurangi damage Holomen itu sebesar -50?","related_cards":{"card_number":["hBP01-001","hBP01-002"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-002 ： 七詩ムメイ]"},"title":"Q21（2024.09.21）"},{"answer":"Tidak, tidak akan aktif. Karena skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 hanya menetapkan sisa HP, bukan memulihkan HP.","question":"Jika skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 digunakan terhadap Holomen lawan dengan sisa HP 40 dan mengenakan 〈石の斧〉, apakah kemampuan ''ketika Holomen ini dipulihkan'' dari 〈石の斧〉 akan aktif ketika HP menjadi 50?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q20（2024.09.21）"},{"answer":"Sisa HP Holomen lawan menjadi 50.","question":"Jika skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 digunakan pada Holomen lawan dengan sisa HP 40 atau kurang, bagaimana hasil HP-nya?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q19（2024.09.21）"},{"answer":"Tidak, tidak bisa. Karena skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉 bukan kemampuan yang memberikan damage, maka tidak dapat mengurangi atau mencegah damage yang diterima.","question":"Ketika HP Holomen pusat saya dikurangi menjadi 50 oleh skill oshi ''ぎゅっぎゅっ'' dari hBP01-001〈天音かなた〉, apakah saya bisa mencegahnya dengan menggunakan gift ''V.7'' dari hBP01-027〈ベスティア・ゼータ〉 agar tidak menerima damage?","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q18（2024.09.21）"}],"ja":[{"answer":"いいえ、できません。","question":"hBP06-097〈カワイイスタジャン〉が付いているBuzzホロメンを、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」によって残りHPを「50」させることはできますか？","related_cards":{"card_number":["hBP01-001","hBP06-097"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP06-097 ： カワイイスタジャン]"},"title":"Q536（2025.12.12）"},{"answer":"いいえ、HPの変動はしないため「50」にはできません。","question":"hBP04-024〈儒烏風亭らでん〉のギフト「冷静沈着」は、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」によって残りHPを「50」させることはできますか？","related_cards":{"card_number":["hBP01-001","hBP04-024"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP04-024 ： 儒烏風亭らでん]"},"title":"Q382（2025.06.11）"},{"answer":"はい、できます。","question":"hBP01-118〈あん肝〉が付いている〈ときのそら〉にhBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」を使いました。この場合、hBP01-118〈あん肝〉が付いている〈ときのそら〉の残りHPを「50」にできますか？","related_cards":{"card_number":["hBP01-001","hBP01-118"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-118 ： あん肝]"},"title":"Q362（2025.03.11）"},{"answer":"いいえ、HPの変動はしないため「50」にはできません。","question":"hBP03-065〈戌神ころね〉のギフト「ボクシングスタイル」は、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」によって残りHPを「50」にすることはできますか？","related_cards":{"card_number":["hBP01-001","hBP03-065"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP03-065 ： 戌神ころね]"},"title":"Q327（2025.03.11）"},{"answer":"いいえ、受けません。hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」の能力はダメージを与える能力ではないため、hBP01-116〈うぱお〉の能力は発揮しません。","question":"hBP01-116〈うぱお〉が付いている相手のセンターホロメンに対してhBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」を使用した場合、自分のセンターホロメンは、相手のhBP01-116〈うぱお〉の能力で特殊ダメージを受けますか？","related_cards":{"card_number":["hBP01-001","hBP01-116"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-116 ： うぱお]"},"title":"Q26（2024.09.21）"},{"answer":"いいえ、使用できません。ダメージを与える能力ではないため、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」の能力を使用することはできません。","question":"hBP01-001〈天音かなた〉の推しスキル〈ぎゅっぎゅっ〉に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」を使用することはできますか？","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"},{"answer":"いいえ、使用できません。ダメージを与える能力ではないため、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhBP01-121〈Kotori〉の能力を使用することはできません。","question":"hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhBP01-121〈Kotori〉の能力を使用することはできますか？","related_cards":{"card_number":["hBP01-001","hBP01-121"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-121 ： Kotori]"},"title":"Q24（2024.09.21）"},{"answer":"いいえ、使用できません。ダメージを与える能力ではないため、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhBP01-117〈フレンド〉の能力を使用することはできません。","question":"hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhBP01-117〈フレンド〉の能力を使用することはできますか？","related_cards":{"card_number":["hBP01-001","hBP01-117"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-117 ： フレンド]"},"title":"Q23（2024.09.21）"},{"answer":"いいえ、使用できません。ダメージを与える能力ではないため、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhBP01-027〈ベスティア・ゼータ〉のギフト「V.7」を使用することはできません。","question":"hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhBP01-027〈ベスティア・ゼータ〉のギフト「V.7」を使用することはできますか？","related_cards":{"card_number":["hBP01-001","hBP01-027"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-027 ： ベスティア・ゼータ]"},"title":"Q22（2024.09.21）"},{"answer":"いいえ、できません。hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」はダメージを与える能力ではないため、hBP01-002〈七詩ムメイ〉の推しスキル「文明の守護者」の能力を使用することはできません。","question":"相手のターンで、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」で自分の#Promise を持つホロメンがの残りHPが50になる時、hBP01-002〈七詩ムメイ〉の推しスキル「文明の守護者」で、そのホロメンのダメージを-50することはできますか？","related_cards":{"card_number":["hBP01-001","hBP01-002"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP01-002 ： 七詩ムメイ]"},"title":"Q21（2024.09.21）"},{"answer":"いいえ、発揮しません。hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」は残りHPを指定する能力のため、HPを回復していません。","question":"hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」を、残りHPが40で、〈石の斧〉が付いている相手のホロメンに使用しました。残りHPが50になった時、〈石の斧〉の「このホロメンが回復した時」の能力は発揮しますか？","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q20（2024.09.21）"},{"answer":"相手のホロメンの残りのHPは50になります。","question":"hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」は、残りのHPが40以下の相手のホロメンに使用した場合、HPはどうなりますか？","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q19（2024.09.21）"},{"answer":"いいえ、できません。hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」は、ダメージを与える能力ではないため、受けるダメージを減らしたり、ダメージを受けないようにすることはできません。","question":"hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」で自分のセンターホロメンのHPを50に減らされる時、hBP01-027〈ベスティア・ゼータ〉のギフト「V.7」でダメージを受けないようにすることはできますか？","related_cards":{"card_number":["hBP01-001"],"raw_html":"[hBP01-001 ： 天音かなた]"},"title":"Q18（2024.09.21）"}],"ko":[{"answer":"아니요, 할 수 없습니다.","question":"hBP06-097〈カワイイスタジャン〉이 부착된 Buzz 홀로멘의 남은 HP를 hBP01-001〈天音かなた〉의 오시 스킬 「꽉꽉」으로 50으로 만들 수 있나요?","related_cards":{"card_number":["hBP01-001","hBP06-097"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP06-097 ： カワイイスタジャン]"},"title":"Q536（2025.12.12）"},{"answer":"아니요, HP의 변동이 일어나지 않기 때문에 50으로 만들 수 없습니다.","question":"hBP04-024〈儒烏風亭らでん〉의 기프트 「냉정침착」은 hBP01-001〈天音かなた〉의 오시 스킬 「꽉꽉」으로 남은 HP를 50으로 만들 수 있나요?","related_cards":{"card_number":["hBP01-001","hBP04-024"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hBP04-024 ： 儒烏風亭らでん]"},"title":"Q382（2025.06.11）"},{"answer":"네, 가능합니다.","question":"hBP01-118〈あん肝〉이 부착된〈ときのそら〉에게 hBP01-001〈天音かなた〉의 오시 스킬 「