INSERT INTO card_sets (set_name, card_id) VALUES ('スタートデッキ 白 天音かなた', '157');
INSERT INTO cards_fts (rowid, card_number, text) VALUES (157, 'hBP01-116', 'hBP01-116 JinArt KABAKURA うぱお このマスコットが付いているホロメンのアーツ+10。
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('163', 'hBP01-122', 'supportFan', 'C', NULL, 'hBP01/hBP01-122_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP01/hBP01-122_C.png', NULL, NULL, NULL, NULL, 'JinArt KABAKURA', 'ロゼ隊', '{"card_sets":["ブースターパック「ブルーミングレディアンス」"],"translations":{"en":{"ability_text":"During your opponent''s turn, if the holomem this fan is attached to is downed, send the top card of your cheer deck to your 〈Aki Rosenthal〉.\n\nYou may only attach this fan to your 〈Aki Rosenthal〉, and you may attach any number of this fan per holomem.","name":"Rose Knights"},"es":{"ability_text":"Durante el turno del oponente, cuando la Holomen con este fan sea derribada, envía la carta superior de tu mazo de Aplausos a tu 〈アキ・ローゼンタール〉.\n\nEste fan solo puede equiparse a tu 〈アキ・ローゼンタール〉, y puedes colocar cualquier número de ellos en una sola.","name":"ロゼ隊"},"id":{"ability_text":"Pada giliran lawan, ketika Holomen yang dipasang fan ini mengalami Down, kirim 1 kartu teratas dari deck Yell-mu ke〈アキ・ローゼンタール〉mu.\n\nFan ini hanya bisa dipasang pada〈アキ・ローゼンタール〉mu, dan bisa dipasang sebanyak apa pun pada setiap orang.","name":"ロゼ隊"},"ja":{"ability_text":"相手のターンで、このファンが付いているホロメンがダウンした時、自分のエールデッキの上から1枚を、自分の〈アキ・ローゼンタール〉に送る。\n\r\nこのファンは、自分の〈アキ・ローゼンタール〉だけに付けられ、1人につき何枚でも付けられる。","name":"ロゼ隊"},"ko":{"ability_text":"상대 턴에, 이 팬이 붙어 있는 홀로멘이 다운되었을 때, 내 응원 덱 맨 위에서 1장을 내 〈アキ・ローゼンタール〉에게 보낸다.\n\n이 팬은 내 〈アキ・ローゼンタール〉에게만 붙일 수 있으며, 1인당 몇 장이든 붙일 수 있다.","name":"ロゼ隊"},"tc":{"ability_text":"在對手的回合中，若裝備了此應援的Holomen被擊倒時，從自己應援牌庫頂抽1張，送到自己的〈アキ・ローゼンタール〉上。\n\n此應援只能裝備在自己的〈アキ・ローゼンタール〉上，同一角色可以裝備任意張數。","name":"ロゼ隊"},"th":{"ability_text":"在對手的回合，當這張粉絲貼在的ホロメン倒下時，將自己應援牌組頂的一張卡送到自己的〈アキ・ローゼンタール〉。\n\n這張粉絲只能貼在自己的〈アキ・ローゼンタール〉身上，每人可以貼任意多張。","name":"ロゼ隊"}}}', '{}', '3972040787146b87a8ab0de515d159218ddb07f604011474c062d70546a646fb', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
INSERT INTO card_sets (set_name, card_id) VALUES ('ブースターパック「ブルーミングレディアンス」', '163');
INSERT INTO cards_fts (rowid, card_number, text) VALUES (163, 'hBP01-122', 'hBP01-122 JinArt KABAKURA ロゼ隊 相手のターンで、このファンが付いているホロメンがダウンした時、自分のエールデッキの上から1枚を、自分の〈アキ・ローゼンタール〉に送る。
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('168', 'hY01-001', 'supportCheer', 'C', NULL, 'COMMON/hY01-001_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/COMMON/hY01-001_C.png', NULL, NULL, NULL, NULL, 'はずき', '白エール', '{"card_sets":["ブースターパック「ブルーミングレディアンス」","ブースターパック「クインテットスペクトラム」","ブースターパック「エリートスパーク」","スタートデッキ「ときのそら＆AZKi」","スタートデッキ 白 轟はじめ","スタートデッキ 白 天音かなた","ライブスタートデッキ 白上フブキ","スタートエールセット"],"color_codes":["white"],"translations":{"en":{"ability_text":"■If a holomem leaves the stage, archive all of that holomem''s cheers.\n■If a holomem Baton Passes, archive the specified number of that holomem''s cheers.","name":"White Cheer"},"es":{"ability_text":"■Cuando una Holomen deja el escenario, archiva todos los Ales de esa Holomen.\n■Cuando una Holomen hace un relevo, archiva la cantidad indicada de sus Ales.","name":"白エール"},"id":{"ability_text":"■Ketika Holomen meninggalkan panggung, arsipkan semua Aile milik Holomen tersebut.\n■Ketika Holomen melakukan baton touch, arsipkan jumlah Aile yang ditentukan milik Holomen tersebut.","name":"白エール"},"ja":{"ability_text":"■ホロメンがステージから離れる時、そのホロメンのエールすべてをアーカイブする。\r\n■ホロメンがバトンタッチする時、そのホロメンのエールを指定された枚数アーカイブする。","name":"白エール"},"ko":{"ability_text":"■ 홀로멘이 스테이지에서 떠날 때, 그 홀로멘의 모든 응원을 아카이브한다.\n■ 홀로멘이 바통터치할 때, 그 홀로멘의 응원을 지정된 장수만큼 아카이브한다.","name":"白エール"},"tc":{"ability_text":"■當Holomen離開舞台時，將該Holomen的所有應援存入檔案區域。\n■當Holomen進行接力時，將該Holomen指定數量的應援存入檔案區域。","name":"白エール"},"th":{"ability_text":"■เมื่อโฮโลเมนออกจากสเตจ ให้ย้ายเอールทั้งหมดของโฮโลเมนนั้นไปยังอาร์ไคฟ์\n■เมื่อโฮโลเมนส่งไม้ต่อ ให้ย้ายเอールจำนวนที่ระบุของโฮโลเมนนั้นไปยังอาร์ไคฟ์","name":"ไวท์เอร์ล"}}}', '{}', 'ddbf37c94b881a28787fb74f57a1d8ee6268caf91346a046e0c15d707687d934', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
