INSERT INTO cards_fts (rowid, card_number, text) VALUES (168, 'hY01-001', 'hY01-001 はずき 白エール ■ホロメンがステージから離れる時、そのホロメンのエールすべてをアーカイブする。' || char(13) || '
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('172', 'hYS01-001', 'oshiCharacter', 'OC', NULL, 'hY01/hYS01-001_OC', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hY01/hYS01-001_OC.png', NULL, 5, NULL, NULL, '松尾 省吾', '七詩ムメイ', '{"card_sets":["スタートエールセット"],"color_codes":["white"],"oshi_skill":{"timing_code":"once_per_turn"},"sp_oshi_skill":{"timing_code":"once_per_game"},"translations":{"en":{"name":"Nanashi Mumei","oshi_skill":{"effect":"[1/Turn]During this turn, your white collab holomem get Arts+20.","name":"White Baton"},"sp_oshi_skill":{"effect":"[1/Game]During your opponent''s turn, usable if your white holomem would take Damage from your opponent:That holomem takes -20 Damage.","name":"Quick Guard"}},"es":{"name":"七詩ムメイ","oshi_skill":{"effect":"[Una vez por turno] Durante este turno, los Arts de tus Holomen colaborativos blancos obtienen +20.","name":"ホワイトバトン"},"sp_oshi_skill":{"effect":"[Una vez por partida] Puedes usarla durante el turno del oponente, cuando uno de tus Holomen blancos vaya a recibir daño del oponente: ese Holomen recibe -20 de daño.","name":"クイックガード"}},"id":{"name":"七詩ムメイ","oshi_skill":{"effect":"[ターンに１回]このターンの間、自分の白コラボホロメンのアーツ+20。","name":"ホワイトバトン"},"sp_oshi_skill":{"effect":"[ゲームに１回]相手のターンで、自分の白ホロメンが相手からダメージを受ける時に使える：そのホロメン１人が受けるダメージ-20。","name":"クイックガード"}},"ja":{"name":"七詩ムメイ","oshi_skill":{"effect":"[ターンに1回]このターンの間、自分の白コラボホロメンのアーツ+20。","name":"ホワイトバトン","timing":"ターンに1回"},"sp_oshi_skill":{"effect":"[ゲームに1回]相手のターンで、自分の白ホロメンが相手からダメージを受ける時に使える:そのホロメン1人が受けるダメージ-20。","name":"クイックガード","timing":"ゲームに1回"}},"ko":{"name":"七詩ムメイ","oshi_skill":{"effect":"[턴에 1회] 이번 턴 동안, 자신의 흰색 콜라보 홀로맨 아츠 +20.","name":"ホワイトバトン"},"sp_oshi_skill":{"effect":"[게임에 1회] 상대 턴에, 자신의 흰색 홀로맨이 상대에게서 대미지를 받을 때 사용할 수 있다: 그 홀로맨 1명이 받는 대미지 -20.","name":"クイックガード"}},"tc":{"name":"七詩ムメイ","oshi_skill":{"effect":"[每回合1次]本回合中，我方的白色合作Holomen的藝能+20。","name":"白色指揮棒"},"sp_oshi_skill":{"effect":"[每場遊戲1次]在對手的回合中，當我方的白色Holomen要從對手那裡受到傷害時可以使用：該Holomen所受到的傷害-20。","name":"快速防禦"}},"th":{"name":"七詩ムメイ","oshi_skill":{"effect":"[ターンに１回]ในช่วงนี้ อาร์ตของホロメンสีขาวของตัวเอง +20.","name":"ホワイトバトン"},"sp_oshi_skill":{"effect":"[ゲームに１回]ในเทิร์นของฝ่ายตรงข้าม เมื่อホロメンสีขาวของตัวเองจะได้รับความเสียหายจากฝ่ายตรงข้าม ใช้ได้: โฮโรมเมนคนนั้นที่กำลังจะได้รับความเสียหาย -20.","name":"クイックガード"}}}}', '{"en":[{"answer":"No, it cannot be used.Since it is not an ability that deals damage, hYS01-001 〈Nanashi Mumei）''s SP Oshi skill ''Quick Guard'' ability cannot be used against hBP01-001 〈Amane Kanata）''s Oshi skill ''Squish Squish''.","question":"Can hYS01-001〈Nanashi Mumei〉''s SP Oshi skill ''Quick Guard'' be used against hBP01-001〈Amane Kanata〉''s Oshi skill ''Squish Squish''?","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001: Amane Kanata]\n[hYS01-001: Nanashi Mumei]"},"title":"Q25（September 21, 2024）"}],"es":[{"answer":"No, no se puede usar. Como no es una habilidad que inflige daño, no es posible aplicar el efecto de la habilidad SP Oshi «クイックガード» de hYS01-001〈七詩ムメイ〉 contra la habilidad Oshi «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉.","question":"¿Se puede usar la habilidad SP Oshi «クイックガード» de hYS01-001〈七詩ムメイ〉 contra la habilidad Oshi «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉?","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"}],"id":[{"answer":"いいえ、使用できません。ダメージを与える能力ではないため、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」の能力を使用することはできません。","question":"hBP01-001〈天音かなた〉の推しスキル〈ぎゅっぎゅっ〉に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」を使用することはできますか？","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"}],"ja":[{"answer":"いいえ、使用できません。ダメージを与える能力ではないため、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」の能力を使用することはできません。","question":"hBP01-001〈天音かなた〉の推しスキル〈ぎゅっぎゅっ〉に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」を使用することはできますか？","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"}],"ko":[{"answer":"아니요, 사용할 수 없습니다. 대미지를 주는 능력이 아니기 때문에, hBP01-001〈天音かなた〉의 오시 스킬 「ぎゅっぎゅっ」에 대해 hYS01-001〈七詩ムメイ〉의 SP 오시 스킬 「クイックガード」의 능력을 사용할 수 없습니다.","question":"hBP01-001〈天音かなた〉의 오시 스킬〈ぎゅっぎゅっ〉에 대해 hYS01-001〈七詩ムメイ〉의 SP 오시 스킬 「クイックガード」를 사용할 수 있나요?","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"}],"tc":[{"answer":"不，可以使用。由於該技能不是造成傷害的能力，因此無法對 hBP01-001〈天音かなた〉的推し技能「ぎゅっぎゅっ」使用 hYS01-001〈七詩ムメイ〉的SP推し技能「快速防禦」的效果。","question":"可以對 hBP01-001〈天音かなた〉的推し技能〈ぎゅっぎゅっ〉使用 hYS01-001〈七詩ムメイ〉的SP推し技能「快速防禦」嗎？","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"}],"th":[{"answer":"ไม่สามารถใช้ได้ เนื่องจากมันไม่ใช่ความสามารถที่ก่อให้เกิดความเสียหาย จึงไม่สามารถใช้ความสามารถของ SP 推しスキル 「クイックガード」ของ hYS01-001〈七詩ムメイ〉 ต่อ 推しスキル 「ぎゅっぎゅっ」ของ hBP01-001〈天音かなた〉 ได้。","question":"hBP01-001〈天音かなた〉の推しスキル〈ぎゅっぎゅっ〉に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」を使用することはできますか？","related_cards":{"card_number":["hBP01-001","hYS01-001"],"raw_html":"[hBP01-001 ： 天音かなた]\n[hYS01-001 ： 七詩ムメイ]"},"title":"Q25（2024.09.21）"}]}', '478140b190dc1504f38cefcff4f1901c66d542bcdf2e3bc6c1b1e64e43d8b75f', '675fce3da4fb8f44924694a9e15a71f9e40d99c3a7f1966914e00bc49d7af6bf', '1970-01-01T00:00:00Z');
INSERT INTO card_colors (color_code, card_id) VALUES ('white', '172');
INSERT INTO card_sets (set_name, card_id) VALUES ('スタートエールセット', '172');
INSERT INTO cards_fts (rowid, card_number, text) VALUES (172, 'hYS01-001', 'hYS01-001 松尾 省吾 七詩ムメイ ホワイトバトン [ターンに1回]このターンの間、自分の白コラボホロメンのアーツ+20。 クイックガード [ゲームに1回]相手のターンで、自分の白ホロメンが相手からダメージを受ける時に使える:そのホロメン1人が受けるダメージ-20。 Q25（2024.09.21） hBP01-001〈天音かなた〉の推しスキル〈ぎゅっぎゅっ〉に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」を使用することはできますか？ いいえ、使用できません。ダメージを与える能力ではないため、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」の能力を使用することはできません。 Nanashi Mumei White Baton [1/Turn]During this turn, your white collab holomem get Arts+20. Quick Guard [1/Game]During your opponent''s turn, usable if your white holomem would take Damage from your opponent:That holomem takes -20 Damage. Q25（September 21, 2024） Can hYS01-001〈Nanashi Mumei〉''s SP Oshi skill ''Quick Guard'' be used against hBP01-001〈Amane Kanata〉''s Oshi skill ''Squish Squish''? No, it cannot be used.Since it is not an ability that deals damage, hYS01-001 〈Nanashi Mumei）''s SP Oshi skill ''Quick Guard'' ability cannot be used against hBP01-001 〈Amane Kanata）''s Oshi skill ''Squish Squish''. 七詩ムメイ 白色指揮棒 [每回合1次]本回合中，我方的白色合作Holomen的藝能+20。 快速防禦 [每場遊戲1次]在對手的回合中，當我方的白色Holomen要從對手那裡受到傷害時可以使用：該Holomen所受到的傷害-20。 Q25（2024.09.21） 可以對 hBP01-001〈天音かなた〉的推し技能〈ぎゅっぎゅっ〉使用 hYS01-001〈七詩ムメイ〉的SP推し技能「快速防禦」嗎？ 不，可以使用。由於該技能不是造成傷害的能力，因此無法對 hBP01-001〈天音かなた〉的推し技能「ぎゅっぎゅっ」使用 hYS01-001〈七詩ムメイ〉的SP推し技能「快速防禦」的效果。 七詩ムメイ ホワイトバトン [ターンに１回]このターンの間、自分の白コラボホロメンのアーツ+20。 クイックガード [ゲームに１回]相手のターンで、自分の白ホロメンが相手からダメージを受ける時に使える：そのホロメン１人が受けるダメージ-20。 Q25（2024.09.21） hBP01-001〈天音かなた〉の推しスキル〈ぎゅっぎゅっ〉に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」を使用することはできますか？ いいえ、使用できません。ダメージを与える能力ではないため、hBP01-001〈天音かなた〉の推しスキル「ぎゅっぎゅっ」に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」の能力を使用することはできません。 七詩ムメイ ホワイトバトン [턴에 1회] 이번 턴 동안, 자신의 흰색 콜라보 홀로맨 아츠 +20. クイックガード [게임에 1회] 상대 턴에, 자신의 흰색 홀로맨이 상대에게서 대미지를 받을 때 사용할 수 있다: 그 홀로맨 1명이 받는 대미지 -20. Q25（2024.09.21） hBP01-001〈天音かなた〉의 오시 스킬〈ぎゅっぎゅっ〉에 대해 hYS01-001〈七詩ムメイ〉의 SP 오시 스킬 「クイックガード」를 사용할 수 있나요? 아니요, 사용할 수 없습니다. 대미지를 주는 능력이 아니기 때문에, hBP01-001〈天音かなた〉의 오시 스킬 「ぎゅっぎゅっ」에 대해 hYS01-001〈七詩ムメイ〉의 SP 오시 스킬 「クイックガード」의 능력을 사용할 수 없습니다. 七詩ムメイ ホワイトバトン [ターンに１回]ในช่วงนี้ อาร์ตของホロメンสีขาวของตัวเอง +20. クイックガード [ゲームに１回]ในเทิร์นของฝ่ายตรงข้าม เมื่อホロメンสีขาวของตัวเองจะได้รับความเสียหายจากฝ่ายตรงข้าม ใช้ได้: โฮโรมเมนคนนั้นที่กำลังจะได้รับความเสียหาย -20. Q25（2024.09.21） hBP01-001〈天音かなた〉の推しスキル〈ぎゅっぎゅっ〉に対してhYS01-001〈七詩ムメイ〉のSP推しスキル「クイックガード」を使用することはできますか？ ไม่สามารถใช้ได้ เนื่องจากมันไม่ใช่ความสามารถที่ก่อให้เกิดความเสียหาย จึงไม่สามารถใช้ความสามารถของ SP 推しスキル 「クイックガード」ของ hYS01-001〈七詩ムメイ〉 ต่อ 推しスキル 「ぎゅっぎゅっ」ของ hBP01-001〈天音かなた〉 ได้。 七詩ムメイ ホワイトバトン [Una vez por turno] Durante este turno, los Arts de tus Holomen colaborativos blancos obtienen +20. クイックガード [Una vez por partida] Puedes usarla durante el turno del oponente, cuando uno de tus Holomen blancos vaya a recibir daño del oponente: ese Holomen recibe -20 de daño. Q25（2024.09.21） ¿Se puede usar la habilidad SP Oshi «クイックガード» de hYS01-001〈七詩ムメイ〉 contra la habilidad Oshi «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉? No, no se puede usar. Como no es una habilidad que inflige daño, no es posible aplicar el efecto de la habilidad SP Oshi «クイックガード» de hYS01-001〈七詩ムメイ〉 contra la habilidad Oshi «ぎゅっぎゅっ» de hBP01-001〈天音かなた〉.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('176', 'hBP01-015', 'character', 'P', 'debut', 'hPR/hBP01-015_P', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hPR/hBP01-015_P.png', 90, NULL, 1, '["null"]', NULL, '七詩ムメイ', '{"arts":[{"cost_count":1,"cost_types":["white"],"damage":10,"is_plus":true}],"card_sets":["PRカード"],"color_codes":["white"],"translations":{"en":{"arts":[{"effect":"If you have used a Support Card this turn, this Arts gets +20.","name":"Oh,Hi"}],"extra":"You may include any number of this holomem in the deck","name":"Nanashi Mumei"},"es":{"arts":[{"effect":"Si usaste una carta de Soporte durante este turno, este Arts obtiene +20.","name":"Oh,Hi"}],"extra":"Este holomen se puede incluir en cualquier cantidad en tu mazo.","name":"七詩ムメイ","tags":["#EN","#Promise","#トリ","#絵"]},"id":{"arts":[{"effect":"Jika kamu menggunakan kartu Support pada giliran ini, arts ini +20.","name":"Oh,Hi"}],"extra":"Holomen ini bisa dimasukkan ke dalam dek sebanyak yang diinginkan","name":"七詩ムメイ","tags":["#EN","#Promise","#トリ","#絵"]},"ja":{"arts":[{"effect":"このターンに自分がサポートカードを使っていた時、このアーツ+20。","name":"Oh,Hi"}],"extra":"このホロメンはデッキに何枚でも入れられる","name":"七詩ムメイ","tags":["#EN","#Promise","#トリ","#絵"]},"ko":{"arts":[{"effect":"이번 턴에 자신이 서포트 카드를 사용했다면, 이 아츠의 대미지가 +20.","name":"Oh,Hi"}],"extra":"이 홀로멘은 덱에 몇 장이든 넣을 수 있다","name":"七詩ムメイ","tags":["#EN","#Promise","#トリ","#絵"]},"tc":{"arts":[{"effect":"若此回合你已經使用過支援卡，這個Arts的傷害+20。","name":"Oh,Hi"}],"extra":"此成員卡可在牌組中放入任意張數","name":"七詩ムメイ","tags":["#EN","#Promise","#トリ","#絵"]},"th":{"arts":[{"effect":"ในเทิร์นนี้ ถ้าคุณได้ใช้การ์ดซัพพอร์ต จะเพิ่มอาร์ตส์นี้ +20。","name":"Oh,Hi"}],"extra":"การ์ดโฮโลเมนนี้สามารถใส่ลงในเด็คได้ไม่จำกัดจำนวน","name":"七詩ムメイ","tags":["#EN","#Promise","#トリ","#絵"]}}}', '{"en":[{"answer":"Yes, Arts damage is increased.Regardless of result, since the support card''s ability is activated, it is considered used and Arts damage is increased.","question":"If hSD01-020〈Circle of hololive Listeners〉 is used and the die roll is 2 or less, does the Arts damage of hBP01-015〈Nanashi Mumei〉''s Arts ''Oh,Hi'' get increased?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015: Nanashi Mumei]\n[hSD01-020: Circle of hololive Listeners]"},"title":"Q50（September 21, 2024）"},{"answer":"No, it is not increased.Using support cards means using cards from your hand.","question":"If hBP01-015〈Nanashi Mumei〉 uses Arts ''Oh,Hi'' when you have tools or mascots attached that are already active, will Arts damage be increased?","related_cards":{"card_number":["hBP01-015"],"raw_html":"[hBP01-015: Nanashi Mumei]"},"title":"Q49（September 21, 2024）"}],"es":[{"answer":"Sí, el daño del Arts se incrementa. Sin importar el resultado del dado, la habilidad de la carta de Soporte se considera activada, por lo tanto, se considera usada y el daño del Arts aumenta.","question":"Si usas hSD01-020〈ホロリスの輪〉 y el resultado del dado es 2 o menos, cuando utilizas el Arts «Oh,Hi» de hBP01-015〈七詩ムメイ〉, ¿el daño del Arts se incrementa?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"},{"answer":"No, no aumenta. Usar una carta de Soporte significa jugarla desde tu mano.","question":"Si hBP01-015〈七詩ムメイ〉 usa el Arts〈Oh,Hi〉 mientras ya hay una herramienta o un mascota que esté unida a tu holomen y activa su habilidad, ¿el daño del Arts aumenta?","related_cards":{"card_number":["hBP01-015"],"raw_html":"[hBP01-015 ： 七詩ムメイ]"},"title":"Q49（2024.09.21）"}],"id":[{"answer":"Ya, damage arts akan bertambah. Terlepas dari hasil dadu, kemampuan kartu Support tetap aktif, sehingga dianggap telah digunakan dan menambah damage arts.","question":"Jika menggunakan hSD01-020〈ホロリスの輪〉 dan hasil dadu 2 atau kurang, lalu menggunakan arts \"Oh,Hi\" dari hBP01-015〈七詩ムメイ〉, apakah damage arts akan bertambah?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"},{"answer":"Tidak, tidak bertambah. Penggunaan kartu Support berarti menggunakan kartu dari tangan.","question":"Jika sudah ada tool atau mascot yang terpasang pada holomenmu dan kemampuannya sedang aktif sebelumnya, lalu hBP01-015〈七詩ムメイ〉 menggunakan arts〈Oh,Hi〉, apakah damage arts akan bertambah?","related_cards":{"card_number":["hBP01-015"],"raw_html":"[hBP01-015 ： 七詩ムメイ]"},"title":"Q49（2024.09.21）"}],"ja":[{"answer":"はい、アーツダメージはプラスされます。サイコロの結果は問わず、サポートカードの能力は発揮されているので、使用したとみなされアーツダメージがプラスされます。","question":"hSD01-020〈ホロリスの輪〉を使用し、サイコロの目が2以下の時に、hBP01-015〈七詩ムメイ〉のアーツ「Oh,Hi」を使用した場合、アーツダメージはプラスされますか？","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"},{"answer":"いいえ、プラスされません。サポートカードの使用とは、手札からカードを使用することを指します。","question":"自分のホロメンに付いていて、能力を発揮しているツールやマスコットがあらかじめ存在している状態で、hBP01-015〈七詩ムメイ〉がアーツ〈Oh,Hi〉を使用した場合、アーツダメージはプラスされますか？","related_cards":{"card_number":["hBP01-015"],"raw_html":"[hBP01-015 ： 七詩ムメイ]"},"title":"Q49（2024.09.21）"}],"ko":[{"answer":"네, 아츠 대미지가 추가됩니다. 주사위 결과와 관계없이 서포트 카드의 능력은 발휘되고 있으므로, 사용한 것으로 간주되어 아츠 대미지가 추가됩니다.","question":"hSD01-020〈ホロリスの輪〉를 사용했고 주사위 눈이 2 이하일 때, hBP01-015〈七詩ムメイ〉의 아츠 「Oh,Hi」를 사용하면 아츠 대미지가 추가되나요?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"},{"answer":"아니요, 추가되지 않습니다. 서포트 카드의 사용이란, 패에서 카드를 사용하는 것을 의미합니다.","question":"자신의 홀로멘에 장착되어 능력을 발휘하고 있는 툴이나 마스코트가 이미 있는 상태에서, hBP01-015〈七詩ムメイ〉가 아츠 〈Oh,Hi〉를 사용하면 아츠 대미지가 추가되나요?","related_cards":{"card_number":["hBP01-015"],"raw_html":"[hBP01-015 ： 七詩ムメイ]"},"title":"Q49（2024.09.21）"}],"tc":[{"answer":"會的，Arts的傷害會增加。無論骰子結果為何，支援卡的效果仍已發動，因此視為已使用支援卡，傷害會增加。","question":"若使用 hSD01-020〈ホロリスの輪〉時，骰子點數為 2 以下，再使用 hBP01-015〈七詩ムメイ〉的Arts「Oh,Hi」，傷害會增加嗎？","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"},{"answer":"不會，傷害不會增加。所謂使用支援卡，是指從手牌中打出該卡。","question":"如果場上已有裝備在自己成員身上並已發揮效果的工具或吉祥物卡，這時 hBP01-015〈七詩ムメイ〉使用Arts〈Oh,Hi〉，傷害會增加嗎？","related_cards":{"card_number":["hBP01-015"],"raw_html":"[hBP01-015 ： 七詩ムメイ]"},"title":"Q49（2024.09.21）"}],"th":[{"answer":"ใช่ ความเสียหายอาร์ตส์จะถูกบวก ไม่ว่าแต้มลูกเต๋าจะเป็นเท่าใดก็ตาม ความสามารถของการ์ดซัพพอร์ตยังถือว่าแสดงผล จึงนับว่าได้ใช้และความเสียหายอาร์ตส์ถูกบวก","question":"เมื่อใช้ hSD01-020〈ホロリスの輪〉 และลูกเต๋าออก 2 หรือน้อยกว่า แล้วใช้อาร์ตส์ 「Oh,Hi」 ของ hBP01-015〈七詩ムメイ〉 ความเสียหายอาร์ตส์จะถูกบวกหรือไม่?","related_cards":{"card_number":["hBP01-015","hSD01-020"],"raw_html":"[hBP01-015 ： 七詩ムメイ]\n[hSD01-020 ： ホロリスの輪]"},"title":"Q50（2024.09.21）"},{"answer":"ไม่ ความเสียหายจะไม่ถูกบวก การใช้การ์ดซัพพอร์ตหมายถึงการใช้การ์ดจากมือ","question":"ถ้ามีทูลหรือมาสคอตติดอยู่กับโฮโลเมนของคุณและกำลังแสดงผลอยู่ล่วงหน้า แล้ว hBP01-015〈七詩ムメイ〉 ใช้อาร์ตส์〈Oh,Hi〉 ความเสียหายอาร์ตส์จะถูกบวกหรือไม่?","related_cards":{"card_number":["hBP01-015"],"raw_html":"[hBP01-015 ： 七詩ムメイ]"},"title":"Q49（2024.09.21）"}]}', '9b45af21a87d15fe2ced9c5616eea3f8379f3705f6c49eccd0afc355f88842e0', '75bc7b2595113e669964982df122df4079085329d2e0b22e6ac086260acce50a', '1970-01-01T00:00:00Z');
