INSERT INTO cards_fts (rowid, card_number, text) VALUES (447, 'hSD04-009', 'hSD04-009 saihate JP 2期生 料理 癒月ちょこ #JP #2期生 #料理 33… 22… 11… あくとっ このターンに自分が使っていたイベント1枚につき、このアーツ+40。 Yuzuki Choco 癒月ちょこ #JP #2期生 #料理 33… 22… 11… あくとっ 這回合中你每使用過1張活動牌，此Art就+40。 癒月ちょこ #JP #2期生 #料理 33… 22… 11… あくとっ Untuk setiap Event yang kamu gunakan selama giliran ini, arts ini mendapatkan +40. 癒月ちょこ #JP #2期生 #料理 33… 22… 11… あくとっ 이번 턴에 자신이 사용한 이벤트 1장당, 이 아츠의 파워를 +40. 癒月ちょこ #JP #2期生 #料理 33… 22… 11… あくとっ ในเทิร์นนี้ ต่อหนึ่งการ์ดอีเวนต์ที่คุณใช้ ทำให้อาร์ตชิ้นนี้เพิ่มพลังอีก +40 癒月ちょこ #JP #2期生 #料理 33… 22… 11… あくとっ Por cada carta de evento que hayas usado en este turno, este arte obtiene +40.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('477', 'hY01-003', 'supportCheer', 'SY', NULL, 'hBP02/hY01-003_SY', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP02/hY01-003_SY.png', NULL, NULL, NULL, NULL, 'リズ', '白エール', '{"card_sets":["ブースターパック「クインテットスペクトラム」"],"color_codes":["white"],"translations":{"en":{"ability_text":"■If a holomem leaves the stage, archive all of that holomem''s cheers.\n■If a holomem Baton Passes, archive the specified number of that holomem''s cheers.","name":"White Cheer"},"es":{"ability_text":"■ Cuando una Holomen abandona el escenario, archiva todos los Eales de esa Holomen.\n■ Cuando una Holomen hace un relevo, archiva la cantidad indicada de Eales de esa Holomen.","name":"白エール"},"id":{"ability_text":"■ Saat Holomen meninggalkan panggung, arsipkan semua Eruel milik Holomen tersebut.\n■ Saat Holomen melakukan baton touch, arsipkan jumlah Eruel yang ditentukan milik Holomen tersebut.","name":"白エール"},"ja":{"ability_text":"■ホロメンがステージから離れる時、そのホロメンのエールすべてをアーカイブする。\r\n■ホロメンがバトンタッチする時、そのホロメンのエールを指定された枚数アーカイブする。","name":"白エール"},"ko":{"ability_text":"■홀로멘이 스테이지에서 떠날 때, 그 홀로멘의 모든 응원을 아카이브한다.\n■홀로멘이 바통터치할 때, 그 홀로멘의 응원을 지정된 장수만큼 아카이브한다.","name":"白エール"},"tc":{"ability_text":"■當ホロメン要離開舞台時，將該ホロメン的所有應援卡放進檔案區域。\n■當ホロメン進行接力時，將該ホロメン指定數量的應援卡放進檔案區域。","name":"白エール"},"th":{"ability_text":"■เมื่อホロメン ออกจากสเตจ ให้นำエール ทั้งหมดของホロメン นั้นใส่ในอาร์ไคฟ์\n■เมื่อホロメン ทำการสลับตัว (Baton Touch) ให้เลือกจำนวนที่ระบุแล้วนำエール ของホロメン นั้นใส่ในอาร์ไคฟ์","name":"白エール"}}}', '{}', 'dbd3765b9df3e0b6ff0691a32950530c7d63d0c3eacedbbed259f78c18865b85', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
