INSERT INTO cards_fts (rowid, card_number, text) VALUES (529, 'hSD05-013', 'hSD05-013 Watersnake DEV_IS ReGLOSS 歌 音乃瀬奏 #DEV_IS #ReGLOSS #歌 ガハw クレッシェンドな日々 自分のステージのエール1枚を、このホロメン以外の自分のホロメンに付け替えられる。 音乃瀬奏 #DEV_IS #ReGLOSS #歌 ガハw クレッシェンドな日々 You may move 1 Cheer on your Stage from this Holomem to another Holomem you control. 音乃瀬奏 #DEV_IS #ReGLOSS #歌 ガハw クレッシェンドな日々 可以將自己舞台上的1張應援，轉移給除這位Holomen以外的自己的Holomen。 音乃瀬奏 #DEV_IS #ReGLOSS #歌 ガハw クレッシェンドな日々 Pindahkan 1 kartu Cheer di panggung Anda ke salah satu Holomen milik Anda selain Holomen ini. 音乃瀬奏 #DEV_IS #ReGLOSS #歌 ガハw クレッシェンドな日々 자신의 스테이지에 있는 응원 1장을, 이 홀로맨이 아닌 자신의 다른 홀로맨에게 붙일 수 있다. 音乃瀬奏 #DEV_IS #ReGLOSS #歌 ガハw クレッシェンドな日々 สามารถย้ายไอเท็มเอลล์ 1 ใบจากสเตจของตัวเอง ไปแนบกับโฮโลเมนคนอื่นของตัวเองที่ไม่ใช่โฮโลเมนนี้ได้ 音乃瀬奏 #DEV_IS #ReGLOSS #歌 ガハw クレッシェンドな日々 Puedes reasignar 1 carta de Apoyo de tu escenario a otro Holomen tuyo que no sea este Holomen.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('614', 'hBP03-050', 'character', 'R', 'first', 'hBP03/hBP03-050_R', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-050_R.png', 150, NULL, 1, '["null"]', '© 2016 COVER Corp. MariA', 'FUWAMOCO', '{"arts":[{"cost_count":2,"cost_types":["null","null"],"damage":40},{"cost_count":2,"cost_types":["blue","red"],"damage":60}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["blue_red"],"translations":{"en":{"arts":[{"effect":"Reveal 1 [red Aile or blue Aile] from your Aile deck and send it to one of your Holomen with #Advent. Then, shuffle your Aile deck.","name":"魔界乃番犬シスターズ"},{"name":"2人揃ってFUWAMOCOです！"}],"extra":"This Holomen is also treated as <フワワ・アビスガード> and <モココ・アビスガード>.","name":"FUWAMOCO","tags":["#EN","#Advent","#ケモミミ"]},"es":{"arts":[{"effect":"Revela 1 carta de [Energía Roja o Energía Azul] de tu mazo de Energías, envíala a tu Holomen con #Advent y luego baraja tu mazo de Energías.","name":"Hermana Perra Guardiana del Inframundo"},{"name":"¡Juntas somos FUWAMOCO!"}],"extra":"Este Holomen también se considera como 〈フワワ・アビスガード〉 y 〈モココ・アビスガード〉.","name":"FUWAMOCO","tags":["#EN","#Advent","#ケモミミ"]},"id":{"arts":[{"effect":"Dari deck cheer-mu, perlihatkan 1 kartu [cheer merah atau cheer biru], lalu kirim ke Holomen milikmu yang memiliki #Advent. Setelah itu, kocok kembali deck cheer-mu.","name":"魔界乃番犬シスターズ"},{"name":"2人揃ってFUWAMOCOです！"}],"extra":"Holomen ini juga dianggap sebagai〈フワワ・アビスガード〉dan〈モココ・アビスガード〉.","name":"FUWAMOCO","tags":["#EN","#Advent","#ケモミミ"]},"ja":{"arts":[{"effect":"自分のエールデッキから、[赤エールか青エール]1枚を公開し、自分の#Adventを持つホロメンに送る。そしてエールデッキをシャッフルする。","name":"魔界乃番犬シスターズ"},{"name":"2人揃ってFUWAMOCOです！"}],"extra":"このホロメンは〈フワワ・アビスガード〉〈モココ・アビスガード〉としても扱う","name":"FUWAMOCO","tags":["#EN","#Advent","#ケモミミ"]},"ko":{"arts":[{"effect":"자신의 에일 덱에서 [빨간 에일 혹은 파란 에일] 1장을 공개하고, 자신의 #Advent를 가진 홀로멘에게 보낸다. 그런 다음 에일 덱을 셔플한다.","name":"마계의 번견 시스터즈"},{"name":"둘이 함께 FUWAMOCO입니다!"}],"extra":"이 홀로멘은 〈フワワ・アビスガード〉〈モココ・アビスガード〉로도 취급한다","name":"FUWAMOCO","tags":["#EN","#Advent","#ケモミミ"]},"tc":{"arts":[{"effect":"從自己的應援牌庫中公開1張[紅色應援或藍色應援]，送給自己具有#Advent的Holomen。然後洗牌應援牌庫。","name":"魔界乃番犬シスターズ"},{"name":"2人揃ってFUWAMOCOです！"}],"extra":"此Holomen同時視為〈フワワ・アビスガード〉與〈モココ・アビスガード〉。","name":"FUWAMOCO","tags":["#EN","#Advent","#ケモミミ"]},"th":{"arts":[{"effect":"เปิดเผยการ์ด [เอลสีแดงหรือเอลสีน้ำเงิน] 1 ใบจากเด็คเอลของตัวเอง แล้วส่งให้กับโฮโลเมมเบอร์ของตัวเองที่มี #Advent จากนั้นสับเด็คเอลของตัวเอง","name":"魔界乃番犬シスターズ"},{"name":"2人揃ってFUWAMOCOです！"}],"extra":"โฮโลเมมเบอร์นี้ถือว่าเป็น〈フワワ・アビスガード〉และ〈モココ・アビスガード〉ด้วย","name":"FUWAMOCO","tags":["#EN","#Advent","#ケモミミ"]}}}', '{"en":[{"answer":"It means this card is considered to have the card names <フワワ・アビスガード>, <モココ・アビスガード>, and <FUWAMOCO>.","question":"What does the extra ability of hBP03-050 <FUWAMOCO> — “This Holomen is also treated as <フワワ・アビスガード> and <モココ・アビスガード>.” — mean?","related_cards":{"card_number":["hBP03-050"],"raw_html":"[hBP03-050 ： FUWAMOCO]"},"title":"Q617（2026.03.02）"},{"answer":"Yes, it does.","question":"Does the extra ability of hBP03-050 <FUWAMOCO> — “This Holomen is also treated as <フワワ・アビスガード> and <モココ・アビスガード>.” — apply even when it’s not on the stage?","related_cards":{"card_number":["hBP03-050"],"raw_html":"[hBP03-050 ： FUWAMOCO]"},"title":"Q544（2025.12.18）"},{"answer":"Yes, you can.","question":"Using hBP04-089 <ツートンカラーパソコン>, if I choose <ときのそら> and <フワワ・アビスガード> as Holomen on my stage with different single colors, can I add hSD01-013 <SorAZ> and hBP03-050 <FUWAMOCO> to my hand as same-colored 1st Holomen?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"Yes, it does.","question":"Does the ability of hBP04-049 <ムーナ・ホシノヴァ>’s arts “Shining Moon” increase by +50 even if the only other Holomen I have is hBP03-050 <FUWAMOCO>?","related_cards":{"card_number":["hBP04-049","hBP03-050"],"raw_html":"[hBP04-049 ： ムーナ・ホシノヴァ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q390（2025.06.11）"},{"answer":"Yes, you can. Even if the specific card name doesn’t appear among your cards, if a card has an extra ability that states it is treated as certain names (such as “This Holomen is also treated as <フワワ・アビスガード> and <モココ・アビスガード>.”), it satisfies that condition.","question":"In hBP03-109 <Ruffians>, it says, “You can send a blue Aile from your Archive to your <フワワ・アビスガード>.” Can I also send it to hBP03-050 <FUWAMOCO>?","related_cards":{"card_number":["hBP03-109","hBP03-050","hBP03-043"],"raw_html":"[hBP03-109 ： Ruffians]\n[hBP03-050 ： FUWAMOCO]\n[hBP03-043 ： フワワ・アビスガード]"},"title":"Q359（2025.03.11）"},{"answer":"Yes, you can. Since hBP03-050 <FUWAMOCO> counts as both red and blue, it meets the condition.","question":"If my oshi Holomen is hBP03-004 <FUWAMOCO>, can I use hBP03-084 <ゴージャスパソコン> to add hBP03-050 <FUWAMOCO> to my hand?","related_cards":{"card_number":["hBP03-050","hBP03-084","hBP03-004"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-084 ： ゴージャスパソコン]\n[hBP03-004 ： FUWAMOCO]"},"title":"Q340（2025.03.11）"},{"answer":"Yes, you can. Even if the specific card name isn’t present, if a card has an extra that treats it as a specific name (such as “This Holomen is also treated as <フワワ・アビスガード> and <モココ・アビスガード>.”), it satisfies that condition.","question":"Using the art “Want to eat together?” from hBP03-043 <フワワ・アビスガード>, can I transfer an Aile to my hBP03-050 <FUWAMOCO>?","related_cards":{"card_number":["hBP03-050","hBP03-043"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-043 ： フワワ・アビスガード]"},"title":"Q322（2025.03.11）"},{"answer":"Yes, it does. Even if the specific card name isn’t among your cards, if a card has an extra that treats it as a certain name, it fulfills that condition.","question":"Does the art “もこもこしてる方” from hBP03-039 <モココ・アビスガード> still give +30 if my center Holomen is hBP03-050 <FUWAMOCO>?","related_cards":{"card_number":["hBP03-039","hBP03-050"],"raw_html":"[hBP03-039 ： モココ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q321（2025.03.11）"},{"answer":"Yes, it can. Even if the specific card name isn’t present, a card with an extra that treats it as that name fulfills the condition.","question":"Can the Bloom Effect “フワ花流水” from hBP03-042 <フワワ・アビスガード> deal Special Damage 20 even if the only other Holomen on my stage is hBP03-050 <FUWAMOCO>?","related_cards":{"card_number":["hBP03-042","hBP03-050"],"raw_html":"[hBP03-042 ： フワワ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q320（2025.03.11）"},{"answer":"Yes, it moves without resting. Cards with extras that treat them as specific names satisfy the relevant conditions.","question":"With hBP03-039 <モココ・アビスガード>’s gift “魔界乃番犬の暴れん坊”, if my center Holomen is hBP03-050 <FUWAMOCO>, does it move to the back position without resting?","related_cards":{"card_number":["hBP03-039","hBP03-050"],"raw_html":"[hBP03-039 ： モココ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q319（2025.03.11）"},{"answer":"Yes, you can. Even if the specific card name doesn’t exist among your cards, if a card has an extra that treats it as that name, it meets the condition.","question":"Using hBP03-038 <モココ・アビスガード>’s Bloom Effect “遊びの時間だー！” can I add hBP03-050 <FUWAMOCO> from my deck to my hand?","related_cards":{"card_number":["hBP03-050","hBP03-038"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-038 ： モココ・アビスガード]"},"title":"Q318（2025.03.11）"},{"answer":"Yes, you can. Even if the specific name isn’t among your cards, cards with extras that treat them as certain names count as fulfilling that condition.","question":"With hBP03-004 <FUWAMOCO>’s Oshi Skill “モコちゃん！”, can I send an Aile to my hBP03-050 <FUWAMOCO>?","related_cards":{"card_number":["hBP03-050","hBP03-004"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-004 ： FUWAMOCO]"},"title":"Q302（2025.03.11）"}],"es":[{"answer":"Significa que esta carta se considera como si tuviera los nombres 〈フワワ・アビスガード〉, 〈モココ・アビスガード〉 y 〈FUWAMOCO〉.","question":"¿Qué significa la habilidad extra de hBP03-050〈FUWAMOCO〉 «Este Holomen también se considera como 〈フワワ・アビスガード〉 y 〈モココ・アビスガード〉»?","related_cards":{"card_number":["hBP03-050"],"raw_html":"[hBP03-050 ： FUWAMOCO]"},"title":"Q617（2026.03.02）"},{"answer":"Sí, se considera así en todas las zonas.","question":"Con respecto al Extra de hBP03-050〈FUWAMOCO〉 «Este Holomen también se considera como 〈フワワ・アビスガード〉 y 〈モココ・アビスガード〉», ¿se considera así incluso cuando no está en el escenario?","related_cards":{"card_number":["hBP03-050"],"raw_html":"[hBP03-050 ： FUWAMOCO]"},"title":"Q544（2025.12.18）"},{"answer":"Sí, puedes añadirlos.","question":"Usando hBP04-089〈ツートンカラーパソコン〉, elijo en mi escenario a los Holomen de colores distintos 〈ときのそら〉 y 〈フワワ・アビスガード〉. En este caso, ¿puedo añadir a mi mano hSD01-013〈SorAZ〉 y hBP03-050〈FUWAMOCO〉 como 1st Holomen del mismo color?","related_cards":{"card_number":["hBP04-089","hSD01-013","hBP03-050"],"raw_html":"[hBP04-089 ： ツートンカラーパソコン]\n[hSD01-013 ： SorAZ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q404（2025.06.11）"},{"answer":"Sí, se activa.","question":"¿La habilidad de la carta de arte «Shining Moon» de hBP04-049〈ムーナ・ホシノヴァ〉 se activa con «+50» incluso si el único Holomen aliado es hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP04-049","hBP03-050"],"raw_html":"[hBP04-049 ： ムーナ・ホシノヴァ]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q390（2025.06.11）"},{"answer":"Sí, puedes hacerlo. Incluso si la carta no tiene el nombre exacto, si posee un Extra que indique «Este Holomen también se considera como 〈フワワ・アビスガード〉 y 〈モココ・アビスガード〉», cumple esa condición.","question":"Con la habilidad de hBP03-109〈Ruffians〉 que dice «Puedes enviar una Energía Azul desde tu archivo a tu 〈フワワ・アビスガード〉», ¿puedo también enviarla a hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-109","hBP03-050","hBP03-043"],"raw_html":"[hBP03-109 ： Ruffians]\n[hBP03-050 ： FUWAMOCO]\n[hBP03-043 ： フワワ・アビスガード]"},"title":"Q359（2025.03.11）"},{"answer":"Sí, puedes. Como hBP03-050〈FUWAMOCO〉 es tanto Roja como Azul, cumple los requisitos.","question":"Si mi Holomen favorito es hBP03-004〈FUWAMOCO〉, ¿puedo usar hBP03-084〈ゴージャスパソコン〉 para añadir hBP03-050〈FUWAMOCO〉 a mi mano?","related_cards":{"card_number":["hBP03-050","hBP03-084","hBP03-004"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-084 ： ゴージャスパソコン]\n[hBP03-004 ： FUWAMOCO]"},"title":"Q340（2025.03.11）"},{"answer":"Sí, puedes. Aunque la carta no tenga el mismo nombre, si tiene el Extra «Este Holomen también se considera como 〈フワワ・アビスガード〉 y 〈モココ・アビスガード〉», cumple la condición.","question":"Con el arte «¿Comemos juntas?» de hBP03-043〈フワワ・アビスガード〉, ¿puedo mover la Energía a mi hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-050","hBP03-043"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-043 ： フワワ・アビスガード]"},"title":"Q322（2025.03.11）"},{"answer":"Sí, se incrementa. Aunque la carta no tenga el mismo nombre, si cuenta con un Extra que indique «Este Holomen también se considera como 〈フワワ・アビスガード〉 y 〈モココ・アビスガード〉», se considera válida.","question":"Si mi Holomen central es hBP03-050〈FUWAMOCO〉, ¿el arte «モコモコしてる方» de hBP03-039〈モココ・アビスガード〉 se incrementa en «+30»?","related_cards":{"card_number":["hBP03-039","hBP03-050"],"raw_html":"[hBP03-039 ： モココ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q321（2025.03.11）"},{"answer":"Sí, puedes infligirlo. Incluso si la carta no tiene ese nombre, el Extra de 〈FUWAMOCO〉 cumple la condición mencionada.","question":"En el efecto Bloom «フワ花流水» de hBP03-042〈フワワ・アビスガード〉, ¿si mi único Holomen en el escenario es hBP03-050〈FUWAMOCO〉, puedo infligir daño especial de «20»?","related_cards":{"card_number":["hBP03-042","hBP03-050"],"raw_html":"[hBP03-042 ： フワワ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q320（2025.03.11）"},{"answer":"Sí, se mueve sin descansar. Si la carta tiene el Extra que la hace contar como los nombres 〈フワワ・アビスガード〉 y 〈モココ・アビスガード〉, cumple la condición.","question":"Si mi Holomen central es hBP03-050〈FUWAMOCO〉, ¿el regalo «Rebelde Guardiana del Inframundo» de hBP03-039〈モココ・アビスガード〉 se mueve a la posición trasera sin descansar?","related_cards":{"card_number":["hBP03-039","hBP03-050"],"raw_html":"[hBP03-039 ： モココ・アビスガード]\n[hBP03-050 ： FUWAMOCO]"},"title":"Q319（2025.03.11）"},{"answer":"Sí, puedes. Aunque el nombre difiera, si posee un Extra que indica que se considera como 〈フワワ・アビスガード〉 y 〈モココ・アビスガード〉, se considera válida.","question":"¿Con la habilidad del efecto Bloom «¡Hora de jugar!» de hBP03-038〈モココ・アビスガード〉 puedo añadir hBP03-050〈FUWAMOCO〉 a mi mano desde el mazo?","related_cards":{"card_number":["hBP03-050","hBP03-038"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-038 ： モココ・アビスガード]"},"title":"Q318（2025.03.11）"},{"answer":"Sí, puede. Aunque la carta no tenga el mismo nombre, si tiene un Extra que indica que se considera como 〈フワワ・アビスガード〉 y 〈モココ・アビスガード〉, cumple esa condición.","question":"¿La habilidad favorita «¡Moco-chan!» de hBP03-004〈FUWAMOCO〉 puede enviar Energía a mi hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-050","hBP03-004"],"raw_html":"[hBP03-050 ： FUWAMOCO]\n[hBP03-004 ： FUWAMOCO]"},"title":"Q302（2025.03.11）"}],"id":[{"answer":"Itu berarti kartu ini memiliki nama〈フワワ・アビスガード〉,〈モココ・アビスガード〉, dan〈FUWAMOCO〉sebagai nama kartu.","question":"Apa arti dari kemampuan ekstra “Holomen ini juga dianggap sebagai〈フワワ・アビスガード〉dan〈モココ・アビスガード〉” pada hBP03-050〈FUWAMOCO〉?","related_cards":{"card_number":["hBP03-050"],"raw_html":"[hBP03-050 ： FUWAMOCO]"},"title":"Q617（2026.03.02）"},{"answer":"Ya, tetap dianggap begitu.","question":"Apakah kemampuan ekstra “Holomen ini juga dianggap sebagai〈フワワ・アビスガード〉dan〈モココ・アビスガード〉” pada hBP03-050〈FUWAMOCO〉juga berlaku ketika tidak berada di stage?","related_cards":{"card_number":["hBP03-050"],"raw_html":"[hBP03-050 ： FUWAMOCO]"},"title":"Q544（2025.12.18）"},{"answer":"Ya, bisa.","question":"Jika aku menggunakan hBP04-089〈ツートンカラーパソコン〉dan memilih〈ときのそら〉serta〈フワワ・アビスガード〉s