INSERT INTO cards_fts (rowid, card_number, text) VALUES (726, 'hBP03-044', 'hBP03-044 えいひ JP 0期生 歌 星街すいせい #JP #0期生 #歌 バーチャルゴースト 自分の推しホロメンが〈星街すいせい〉の時、このホロメンの青エール1枚を、自分のバックホロメンの〈星街すいせい〉に付け替えられる。 プラネットステージ 自分のデッキの上から4枚を見る。その中から、〈星街すいせい〉1枚を公開し、手札に加える。そして残ったカードを好きな順でデッキの下に戻す。 星街すいせい #JP #0期生 #歌 バーチャルゴースト If your oshi Holomen is 〈星街すいせい〉, you can move one of this Holomen’s blue Yell cards and attach it to your backline 〈星街すいせい〉. プラネットステージ Look at the top 4 cards of your deck. Reveal one 〈星街すいせい〉 card from among them and add it to your hand. Return the remaining cards to the bottom of your deck in any order. 星街すいせい #JP #0期生 #歌 バーチャルゴースト 當你的推しHolomen是〈星街すいせい〉時，可以將此Holomen的一張藍色應援，改附加到你後排Holomen的〈星街すいせい〉上。 プラネットステージ 查看自己牌庫頂的4張牌，從中公開1張〈星街すいせい〉並加入手牌。將剩餘的牌以任意順序放回牌庫底。 星街すいせい #JP #0期生 #歌 バーチャルゴースト Jika idol favoritmu adalah 〈星街すいせい〉, kamu boleh memindahkan 1 kartu Blue Ale dari holomen-mu ini ke 〈星街すいせい〉 di back holomen milikmu. プラネットステージ Lihat 4 kartu teratas dari dek-mu. Dari situ, buka 1 kartu 〈星街すいせい〉 dan masukkan ke tanganmu. Kemudian kembalikan sisa kartu ke bawah dek dalam urutan yang kamu pilih. 星街すいせい #JP #0期生 #歌 バーチャルゴースト 내 오시 홀로멘이 〈星街すいせい〉일 때, 이 홀로멘의 파란 에ール 1장을 내 백 홀로멘 〈星街すいせい〉에게 옮겨 붙일 수 있다. プラネットステージ 내 덱 위에서 카드 4장을 본다. 그중에서 〈星街すいせい〉 1장을 공개하고 패에 넣는다. 남은 카드는 원하는 순서로 덱 맨 아래로 되돌린다. 星街すいせい #JP #0期生 #歌 バーチャルゴースト เมื่อสมาชิกโฮโลเมนที่คุณเชียร์คือ〈星街すいせい〉 คุณสามารถย้ายการ์ดเอールสีน้ำเงิน 1 ใบจากโฮโลเมนนี้ไปติดกับ〈星街すいせい〉ในแบ็กโฮโลเมนของคุณได้ プラネットステージ ดูไพ่จากบนสุดของเด็คคุณ 4 ใบ ระหว่างนั้น เผย〈星街すいせい〉 1 ใบจากไพ่เหล่านั้นและนำเข้ามือ แล้วนำไพ่ที่เหลือกลับลงไปที่ก้นเด็คตามลำดับที่คุณต้องการ 星街すいせい #JP #0期生 #歌 バーチャルゴースト Si tu holo favorito es 〈星街すいせい〉, puedes mover 1 carta de Cheer azul de este holomen y equiparla al 〈星街すいせい〉 que tengas en tu zona de apoyo. プラネットステージ Mira las 4 cartas superiores de tu mazo. Revela 1 carta de 〈星街すいせい〉 de entre ellas y añádela a tu mano. Luego devuelve las demás cartas al fondo del mazo en el orden que prefieras.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('735', 'hBP03-055', 'character', 'SR', 'first', 'hBP03/hBP03-055_SR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP03/hBP03-055_SR.png', 130, NULL, 1, '["null"]', '雨傘ゆん', '常闇トワ', '{"arts":[{"cost_count":1,"cost_types":["purple"],"damage":40},{"cost_count":2,"cost_types":["purple","null"],"damage":50}],"card_sets":["ブースターパック「エリートスパーク」"],"color_codes":["purple"],"translations":{"en":{"arts":[{"name":"トワとお家デートしたっていい"},{"effect":"If you have a backup Holomen with #歌, deal 20 special damage to an opponent’s Collaboration Holomen.","name":"てんQ"}],"name":"常闇トワ","tags":["#JP","#4期生","#歌","#シューター"]},"es":{"arts":[{"name":"Está bien tener una cita en casa con Towa"},{"effect":"Si tienes un holomem de respaldo con #歌, inflige 20 de daño especial al holomem colaborativo del oponente.","name":"てんQ"}],"name":"常闇トワ","tags":["#JP","#4期生","#歌","#シューター"]},"id":{"arts":[{"name":"トワとお家デートしたっていい"},{"effect":"Saat kamu memiliki back holomen yang memiliki tag #歌, berikan 20 damage khusus kepada kolaborasi holomen lawan.","name":"てんQ"}],"name":"常闇トワ","tags":["#JP","#4期生","#歌","#シューター"]},"ja":{"arts":[{"name":"トワとお家デートしたっていい"},{"effect":"自分の#歌を持つバックホロメンがいる時、相手のコラボホロメンに特殊ダメージ20を与える。","name":"てんQ"}],"name":"常闇トワ","tags":["#JP","#4期生","#歌","#シューター"]},"ko":{"arts":[{"name":"トワとお家デートしたっていい"},{"effect":"#노래를 가진 자신의 백라인 홀로맨이 있을 때, 상대 콜라보 홀로맨에게 특수 데미지 20을 준다.","name":"てんQ"}],"name":"常闇トワ","tags":["#JP","#4期生","#歌","#シューター"]},"tc":{"arts":[{"name":"トワとお家デートしたっていい"},{"effect":"當自己的後場有持有#歌的Holomen時，對對手的合作Holomen造成20點特殊傷害。","name":"てんQ"}],"name":"常闇トワ","tags":["#JP","#4期生","#歌","#シューター"]},"th":{"arts":[{"name":"トワとお家デートしたっていい"},{"effect":"เมื่อมีバックホロメンที่คุณครอบครองและมี#歌 อยู่ ให้ทำดาเมจพิเศษ 20 แก่โคลาบโฮโลเมนของฝ่ายตรงข้าม","name":"てんQ"}],"name":"常闇トワ","tags":["#JP","#4期生","#歌","#シューター"]}}}', '{}', '9d2e5f5cf2c0ab906fa64d267ce20f2ec8210ceef16c4ade8ac69f3524e06c63', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
