INSERT INTO cards_fts (rowid, card_number, text) VALUES (735, 'hBP03-055', 'hBP03-055 雨傘ゆん JP 4期生 歌 シューター 常闇トワ #JP #4期生 #歌 #シューター トワとお家デートしたっていい てんQ 自分の#歌を持つバックホロメンがいる時、相手のコラボホロメンに特殊ダメージ20を与える。 常闇トワ #JP #4期生 #歌 #シューター トワとお家デートしたっていい てんQ If you have a backup Holomen with #歌, deal 20 special damage to an opponent’s Collaboration Holomen. 常闇トワ #JP #4期生 #歌 #シューター トワとお家デートしたっていい てんQ 當自己的後場有持有#歌的Holomen時，對對手的合作Holomen造成20點特殊傷害。 常闇トワ #JP #4期生 #歌 #シューター トワとお家デートしたっていい てんQ Saat kamu memiliki back holomen yang memiliki tag #歌, berikan 20 damage khusus kepada kolaborasi holomen lawan. 常闇トワ #JP #4期生 #歌 #シューター トワとお家デートしたっていい てんQ #노래를 가진 자신의 백라인 홀로맨이 있을 때, 상대 콜라보 홀로맨에게 특수 데미지 20을 준다. 常闇トワ #JP #4期生 #歌 #シューター トワとお家デートしたっていい てんQ เมื่อมีバックホロメンที่คุณครอบครองและมี#歌 อยู่ ให้ทำดาเมจพิเศษ 20 แก่โคลาบโฮโลเมนของฝ่ายตรงข้าม 常闇トワ #JP #4期生 #歌 #シューター Está bien tener una cita en casa con Towa てんQ Si tienes un holomem de respaldo con #歌, inflige 20 de daño especial al holomem colaborativo del oponente.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('1218', 'hBP05-040', 'character', 'U', 'first', 'hBP05/hBP05-040_U', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP05/hBP05-040_U.png', 150, NULL, 1, '["null"]', 'UIIV◇', 'miComet', '{"arts":[{"cost_count":3,"cost_types":["null","null","null"],"damage":90}],"card_sets":["ブースターパック「エンチャントレガリア」"],"color_codes":["red","blue"],"keyword":{"type":"コラボエフェクト","type_code":"collab_effect"},"translations":{"en":{"arts":[{"effect":"You may move 1 Cheer from this Holomem to one of your back Holomems.","name":"ビジネスパートナー"}],"extra":"Treat this Holomem also as 〈さくらみこ〉 and 〈星街すいせい〉.","keyword":{"effect":"If your Life is 3 or less, you may Bloom once more this turn for your Center Holomem [〈さくらみこ〉 or 〈星街すいせい〉] that Bloomed this turn, using a Holomem from your hand.","name":"ビジネスフレンド"},"name":"miComet","tags":["#JP","#0期生","#ベイビー","#歌"]},"es":{"arts":[{"effect":"Puedes mover una carta de Elan de este Holomen y equiparla a tu Holomen de respaldo.","name":"ビジネスパートナー"}],"extra":"Este Holomen también se considera como 〈さくらみこ〉 y 〈星街すいせい〉.","keyword":{"effect":"Si tu vida es 3 o menos, puedes hacer que tu Holomen central que floreció (Bloom) este turno y que sea [〈さくらみこ〉 o 〈星街すいせい〉] florezca otra vez usando un Holomen de tu mano.","name":"ビジネスフレンド"},"name":"miComet","tags":["#JP","#0期生","#ベイビー","#歌"]},"id":{"arts":[{"effect":"Kamu bisa memindahkan 1 kartu Eal dari Holomen ini ke Holomen belakangmu.","name":"ビジネスパートナー"}],"extra":"Holomen ini juga dianggap sebagai 〈さくらみこ〉 dan 〈星街すいせい〉.","keyword":{"effect":"Jika Life kamu 3 atau kurang, kamu bisa melakukan Bloom sekali lagi terhadap Center Holomen yang telah Bloom di giliran ini dan memiliki [〈さくらみこ〉 atau 〈星街すいせい〉], dengan menggunakan Holomen dari tanganmu.","name":"ビジネスフレンド"},"name":"miComet","tags":["#JP","#0期生","#ベイビー","#歌"]},"ja":{"arts":[{"effect":"このホロメンのエール1枚を自分のバックホロメンに付け替えられる。","name":"ビジネスパートナー"}],"extra":"このホロメンは〈さくらみこ〉〈星街すいせい〉としても扱う","keyword":{"effect":"自分のライフが3以下なら、自分のこのターンにBloomしたセンターホロメンの[〈さくらみこ〉か〈星街すいせい〉]を、自分の手札のホロメンを使ってもう1回Bloomできる。","name":"ビジネスフレンド"},"name":"miComet","tags":["#JP","#0期生","#ベイビー","#歌"]},"ko":{"arts":[{"effect":"이 홀로맨의 에ール 1장을 자신의 백 홀로맨에게 옮길 수 있다.","name":"ビジネスパートナー"}],"extra":"이 홀로맨은 〈さくらみこ〉와 〈星街すいせい〉로서도 취급한다","keyword":{"effect":"자신의 라이프가 3 이하라면, 이번 턴에 Bloom한 센터 홀로맨 중 [〈さくらみこ〉 또는 〈星街すいせい〉]를, 자신의 패에 있는 홀로맨을 사용해 한 번 더 Bloom 할 수 있다.","name":"ビジネスフレンド"},"name":"miComet","tags":["#JP","#0期生","#ベイビー","#歌"]},"tc":{"arts":[{"effect":"可以將這位Holomen的一張應援卡轉移到自己的後排Holomen身上。","name":"ビジネスパートナー"}],"extra":"此Holomen同時視為〈さくらみこ〉與〈星街すいせい〉。","keyword":{"effect":"若自己的生命為3或以下，則本回合Bloom過的中心Holomen為[〈さくらみこ〉或〈星街すいせい〉]時，可以再使用自己手牌中的Holomen進行一次Bloom。","name":"ビジネスフレンド"},"name":"miComet","tags":["#JP","#0期生","#ベイビー","#歌"]},"th":{"arts":[{"effect":"สามารถเปลี่ยนการ์ดเอール 1 ใบของโฮโลเม็นนี้ ไปติดกับโฮโลเม็นฝั่งหลังของตนเองได้","name":"ビジネスパートナー"}],"extra":"โฮโลเม็นนี้ถือว่าเป็น〈さくらみこ〉และ〈星街すいせい〉ด้วย","keyword":{"effect":"ถ้าค่าไลฟ์ของตัวเองเหลือ 3 หรือน้อยกว่า สามารถใช้โฮโลเม็นในมือของตน Bloom เซ็นเตอร์โฮโลเม็นที่ Bloom ในเทิร์นนี้ซึ่งเป็น [〈さくらみこ〉หรือ〈星街すいせい〉] อีกครั้งได้","name":"ビジネスフレンド"},"name":"miComet","tags":["#JP","#0期生","#ベイビー","#歌"]}}}', '{"en":[{"answer":"It means the card is considered to have the names 〈さくらみこ〉, 〈星街すいせい〉, and 〈miComet〉 as its card names.","question":"What does the Extra ability of hBP05-040〈miComet〉, “Treat this Holomem also as 〈さくらみこ〉 and 〈星街すいせい〉,” mean?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q618（2026.03.02）"},{"answer":"Yes, it does.","question":"Does hBP05-040〈miComet〉’s Extra ability “Treat this Holomem also as 〈さくらみこ〉 and 〈星街すいせい〉” apply even when it is not on stage?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q545（2025.12.18）"}],"es":[{"answer":"Significa que la carta posee los nombres 〈さくらみこ〉, 〈星街すいせい〉 y 〈miComet〉 como nombres de carta.","question":"¿Qué significa la habilidad extra “Este Holomen también se considera como 〈さくらみこ〉 y 〈星街すいせい〉” de hBP05-040〈miComet〉?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q618（2026.03.02）"},{"answer":"Sí, se trata como tal.","question":"En el caso de la habilidad extra “Este Holomen también se considera como 〈さくらみこ〉 y 〈星街すいせい〉” de hBP05-040〈miComet〉, ¿se trata también como 〈さくらみこ〉 y 〈星街すいせい〉 incluso si no está en el escenario?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q545（2025.12.18）"}],"id":[{"answer":"Artinya kartu ini memiliki nama 〈さくらみこ〉, 〈星街すいせい〉, dan 〈miComet〉.","question":"Apa arti kemampuan Ekstra dari hBP05-040〈miComet〉, \"Holomen ini juga dianggap sebagai 〈さくらみこ〉 dan 〈星街すいせい〉\"?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q618（2026.03.02）"},{"answer":"Ya, tetap dianggap begitu.","question":"Untuk hBP05-040〈miComet〉 dengan Ekstra \"Holomen ini juga dianggap sebagai 〈さくらみこ〉 dan 〈星街すいせい〉\", apakah tetap dianggap sebagai 〈さくらみこ〉 dan 〈星街すいせい〉 saat berada di luar stage?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q545（2025.12.18）"}],"ja":[{"answer":"カード名として、〈さくらみこ〉、〈星街すいせい〉、〈miComet〉を持つことを指します。","question":"hBP05-040〈miComet〉のエクストラ能力「このホロメンは〈さくらみこ〉〈星街すいせい〉としても扱う」とは、どういう意味ですか？","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q618（2026.03.02）"},{"answer":"はい、扱います。","question":"hBP05-040〈miComet〉のエクストラ「このホロメンは〈さくらみこ〉〈星街すいせい〉としても扱う」とは、ステージ以外にある場合でも〈さくらみこ〉〈星街すいせい〉として扱いますか？","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q545（2025.12.18）"}],"ko":[{"answer":"카드 이름으로서 〈さくらみこ〉, 〈星街すいせい〉, 〈miComet〉을 모두 가진다는 의미입니다.","question":"hBP05-040〈miComet〉의 엑스트라 능력 「이 홀로맨은 〈さくらみこ〉〈星街すいせい〉로서도 취급한다」는 무슨 뜻인가요?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q618（2026.03.02）"},{"answer":"네, 그렇게 취급합니다.","question":"hBP05-040〈miComet〉의 엑스트라 「이 홀로맨은 〈さくらみこ〉〈星街すいせい〉로서도 취급한다」는 스테이지 이외의 영역에 있을 때도 〈さくらみこ〉〈星街すいせい〉로 취급하나요?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q545（2025.12.18）"}],"tc":[{"answer":"代表此卡同時具有〈さくらみこ〉、〈星街すいせい〉和〈miComet〉三個卡名。","question":"hBP05-040〈miComet〉的額外能力「此Holomen同時視為〈さくらみこ〉與〈星街すいせい〉。」是什麼意思？","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q618（2026.03.02）"},{"answer":"是的，會被當作。","question":"hBP05-040〈miComet〉的額外能力「此Holomen同時視為〈さくらみこ〉與〈星街すいせい〉。」在不在舞台上的情況下，也會被當作〈さくらみこ〉與〈星街すいせい〉嗎？","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q545（2025.12.18）"}],"th":[{"answer":"หมายถึงการ์ดนี้ถือว่ามีชื่อ〈さくらみこ〉, 〈星街すいせい〉 และ〈miComet〉พร้อมกัน","question":"ความหมายของเอ็กซ์ตร้าความสามารถ “โฮโลเม็นนี้ถือว่าเป็น〈さくらみこ〉และ〈星街すいせい〉ด้วย” ของ hBP05-040〈miComet〉 คืออะไร?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q618（2026.03.02）"},{"answer":"ใช่ ถือว่าเป็นเช่นนั้น","question":"เอ็กซ์ตร้า “โฮโลเม็นนี้ถือว่าเป็น〈さくらみこ〉และ〈星街すいせい〉ด้วย” ของ hBP05-040〈miComet〉 จะยังถือว่าเป็น〈さくらみこ〉หรือ〈星街すいせい〉แม้อยู่ในพื้นที่อื่นนอกจากสเตจหรือไม่?","related_cards":{"card_number":["hBP05-040"],"raw_html":"[hBP05-040 ： miComet]"},"title":"Q545（2025.12.18）"}]}', '5babc555e9f8f4cfaa4431c29f5a33a9c83caebd3d2f4400e7cd25831471cb77', '175d19e6170fff86b170a61ed9fc1fa5aeee613c0f8ec71537c52aee57756550', '1970-01-01T00:00:00Z');
