INSERT INTO cards_fts (rowid, card_number, text) VALUES (1218, 'hBP05-040', 'hBP05-040 UIIV◇ JP 0期生 ベイビー 歌 miComet #JP #0期生 #ベイビー #歌 このホロメンは〈さくらみこ〉〈星街すいせい〉としても扱う ビジネスパートナー このホロメンのエール1枚を自分のバックホロメンに付け替えられる。 ビジネスフレンド 自分のライフが3以下なら、自分のこのターンにBloomしたセンターホロメンの[〈さくらみこ〉か〈星街すいせい〉]を、自分の手札のホロメンを使ってもう1回Bloomできる。 Q618（2026.03.02） hBP05-040〈miComet〉のエクストラ能力「このホロメンは〈さくらみこ〉〈星街すいせい〉としても扱う」とは、どういう意味ですか？ カード名として、〈さくらみこ〉、〈星街すいせい〉、〈miComet〉を持つことを指します。 Q545（2025.12.18） hBP05-040〈miComet〉のエクストラ「このホロメンは〈さくらみこ〉〈星街すいせい〉としても扱う」とは、ステージ以外にある場合でも〈さくらみこ〉〈星街すいせい〉として扱いますか？ はい、扱います。 miComet #JP #0期生 #ベイビー #歌 Treat this Holomem also as 〈さくらみこ〉 and 〈星街すいせい〉. ビジネスパートナー You may move 1 Cheer from this Holomem to one of your back Holomems. ビジネスフレンド If your Life is 3 or less, you may Bloom once more this turn for your Center Holomem [〈さくらみこ〉 or 〈星街すいせい〉] that Bloomed this turn, using a Holomem from your hand. Q618（2026.03.02） What does the Extra ability of hBP05-040〈miComet〉, “Treat this Holomem also as 〈さくらみこ〉 and 〈星街すいせい〉,” mean? It means the card is considered to have the names 〈さくらみこ〉, 〈星街すいせい〉, and 〈miComet〉 as its card names. Q545（2025.12.18） Does hBP05-040〈miComet〉’s Extra ability “Treat this Holomem also as 〈さくらみこ〉 and 〈星街すいせい〉” apply even when it is not on stage? Yes, it does. miComet #JP #0期生 #ベイビー #歌 此Holomen同時視為〈さくらみこ〉與〈星街すいせい〉。 ビジネスパートナー 可以將這位Holomen的一張應援卡轉移到自己的後排Holomen身上。 ビジネスフレンド 若自己的生命為3或以下，則本回合Bloom過的中心Holomen為[〈さくらみこ〉或〈星街すいせい〉]時，可以再使用自己手牌中的Holomen進行一次Bloom。 Q618（2026.03.02） hBP05-040〈miComet〉的額外能力「此Holomen同時視為〈さくらみこ〉與〈星街すいせい〉。」是什麼意思？ 代表此卡同時具有〈さくらみこ〉、〈星街すいせい〉和〈miComet〉三個卡名。 Q545（2025.12.18） hBP05-040〈miComet〉的額外能力「此Holomen同時視為〈さくらみこ〉與〈星街すいせい〉。」在不在舞台上的情況下，也會被當作〈さくらみこ〉與〈星街すいせい〉嗎？ 是的，會被當作。 miComet #JP #0期生 #ベイビー #歌 Holomen ini juga dianggap sebagai 〈さくらみこ〉 dan 〈星街すいせい〉. ビジネスパートナー Kamu bisa memindahkan 1 kartu Eal dari Holomen ini ke Holomen belakangmu. ビジネスフレンド Jika Life kamu 3 atau kurang, kamu bisa melakukan Bloom sekali lagi terhadap Center Holomen yang telah Bloom di giliran ini dan memiliki [〈さくらみこ〉 atau 〈星街すいせい〉], dengan menggunakan Holomen dari tanganmu. Q618（2026.03.02） Apa arti kemampuan Ekstra dari hBP05-040〈miComet〉, "Holomen ini juga dianggap sebagai 〈さくらみこ〉 dan 〈星街すいせい〉"? Artinya kartu ini memiliki nama 〈さくらみこ〉, 〈星街すいせい〉, dan 〈miComet〉. Q545（2025.12.18） Untuk hBP05-040〈miComet〉 dengan Ekstra "Holomen ini juga dianggap sebagai 〈さくらみこ〉 dan 〈星街すいせい〉", apakah tetap dianggap sebagai 〈さくらみこ〉 dan 〈星街すいせい〉 saat berada di luar stage? Ya, tetap dianggap begitu. miComet #JP #0期生 #ベイビー #歌 이 홀로맨은 〈さくらみこ〉와 〈星街すいせい〉로서도 취급한다 ビジネスパートナー 이 홀로맨의 에ール 1장을 자신의 백 홀로맨에게 옮길 수 있다. ビジネスフレンド 자신의 라이프가 3 이하라면, 이번 턴에 Bloom한 센터 홀로맨 중 [〈さくらみこ〉 또는 〈星街すいせい〉]를, 자신의 패에 있는 홀로맨을 사용해 한 번 더 Bloom 할 수 있다. Q618（2026.03.02） hBP05-040〈miComet〉의 엑스트라 능력 「이 홀로맨은 〈さくらみこ〉〈星街すいせい〉로서도 취급한다」는 무슨 뜻인가요? 카드 이름으로서 〈さくらみこ〉, 〈星街すいせい〉, 〈miComet〉을 모두 가진다는 의미입니다. Q545（2025.12.18） hBP05-040〈miComet〉의 엑스트라 「이 홀로맨은 〈さくらみこ〉〈星街すいせい〉로서도 취급한다」는 스테이지 이외의 영역에 있을 때도 〈さくらみこ〉〈星街すいせい〉로 취급하나요? 네, 그렇게 취급합니다. miComet #JP #0期生 #ベイビー #歌 โฮโลเม็นนี้ถือว่าเป็น〈さくらみこ〉และ〈星街すいせい〉ด้วย ビジネスパートナー สามารถเปลี่ยนการ์ดเอール 1 ใบของโฮโลเม็นนี้ ไปติดกับโฮโลเม็นฝั่งหลังของตนเองได้ ビジネスフレンド ถ้าค่าไลฟ์ของตัวเองเหลือ 3 หรือน้อยกว่า สามารถใช้โฮโลเม็นในมือของตน Bloom เซ็นเตอร์โฮโลเม็นที่ Bloom ในเทิร์นนี้ซึ่งเป็น [〈さくらみこ〉หรือ〈星街すいせい〉] อีกครั้งได้ Q618（2026.03.02） ความหมายของเอ็กซ์ตร้าความสามารถ “โฮโลเม็นนี้ถือว่าเป็น〈さくらみこ〉และ〈星街すいせい〉ด้วย” ของ hBP05-040〈miComet〉 คืออะไร? หมายถึงการ์ดนี้ถือว่ามีชื่อ〈さくらみこ〉, 〈星街すいせい〉 และ〈miComet〉พร้อมกัน Q545（2025.12.18） เอ็กซ์ตร้า “โฮโลเม็นนี้ถือว่าเป็น〈さくらみこ〉และ〈星街すいせい〉ด้วย” ของ hBP05-040〈miComet〉 จะยังถือว่าเป็น〈さくらみこ〉หรือ〈星街すいせい〉แม้อยู่ในพื้นที่อื่นนอกจากสเตจหรือไม่? ใช่ ถือว่าเป็นเช่นนั้น miComet #JP #0期生 #ベイビー #歌 Este Holomen también se considera como 〈さくらみこ〉 y 〈星街すいせい〉. ビジネスパートナー Puedes mover una carta de Elan de este Holomen y equiparla a tu Holomen de respaldo. ビジネスフレンド Si tu vida es 3 o menos, puedes hacer que tu Holomen central que floreció (Bloom) este turno y que sea [〈さくらみこ〉 o 〈星街すいせい〉] florezca otra vez usando un Holomen de tu mano. Q618（2026.03.02） ¿Qué significa la habilidad extra “Este Holomen también se considera como 〈さくらみこ〉 y 〈星街すいせい〉” de hBP05-040〈miComet〉? Significa que la carta posee los nombres 〈さくらみこ〉, 〈星街すいせい〉 y 〈miComet〉 como nombres de carta. Q545（2025.12.18） En el caso de la habilidad extra “Este Holomen también se considera como 〈さくらみこ〉 y 〈星街すいせい〉” de hBP05-040〈miComet〉, ¿se trata también como 〈さくらみこ〉 y 〈星街すいせい〉 incluso si no está en el escenario? Sí, se trata como tal.');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('1877', 'hBP07-091', 'supportStaff', 'C', NULL, 'hBP07/hBP07-091_C', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP07/hBP07-091_C.png', NULL, NULL, NULL, NULL, '海原カイロ', 'ライブスタッフ', '{"card_sets":["ブースターパック「ディーヴァフィーバー」"],"translations":{"en":{"ability_text":"You can’t play this card unless you archive 1 Cheer from your Stage.\n\nAttach 1 Fan from your Archive to one of your Holomen. If you do, return 1 Holomen from your Archive to your hand.","name":"ライブスタッフ"},"es":{"ability_text":"No puedes usar esta carta a menos que archives 1 carta de Apoyo en tu escenario.\n\nAdjunta 1 carta de Fan de tu Archivo a uno de tus Holomen. Si lo haces, devuelve 1 carta de Holomen de tu Archivo a tu mano.","name":"ライブスタッフ"},"id":{"ability_text":"Kartu ini tidak bisa digunakan kecuali kamu mengarsipkan 1 kartu Yell di stage-mu.\n\nTempelkan 1 kartu Fan dari area arsipmu ke salah satu Holomen milikmu. Jika kamu melakukannya, kembalikan 1 kartu Holomen dari area arsipmu ke tanganmu.","name":"Staf Live"},"ja":{"ability_text":"このカードは、自分のステージのエール1枚をアーカイブしなければ使えない。\n\n自分のアーカイブのファン1枚を自分のホロメンに付ける。付けたなら、自分のアーカイブのホロメン1枚を手札に戻す。","name":"ライブスタッフ"},"ko":{"ability_text":"이 카드는 자신의 스테이지에 있는 응원 1장을 아카이브해야만 사용할 수 있다.\n\n자신의 아카이브에 있는 팬 1장을 자신의 홀로멘에게 붙인다. 그렇게 했다면, 자신의 아카이브에 있는 홀로멘 1장을 패로 되돌린다.","name":"라이브 스태프"},"tc":{"ability_text":"必須將自己舞台區的1張應援卡存入檔案區域，才能使用此卡。\n\n將自己檔案區域中的1張粉絲卡附加到自己的Holomen身上。若已附加，則從自己的檔案區域將1張Holomen卡返回手牌。","name":"ライブスタッフ"},"th":{"ability_text":"ไม่สามารถใช้การ์ดนี้ได้ เว้นแต่คุณจะเก็บการ์ด​「เอール」​1 ใบบนสเตจของคุณไว้ในพื้นที่จัดเก็บ (Archive)\n\nนำ「แฟน」​1 ใบจากพื้นที่จัดเก็บของคุณไปติดกับ「โฮโลเมン」ของคุณ ถ้าทำเช่นนั้นแล้ว ให้นำ「โฮโลเมน」​1 ใบจากพื้นที่จัดเก็บของคุณกลับขึ้นมือ","name":"ライブスタッフ"}}}', '{}', 'fe407083ab2b3ff28510c844e8c9533bf9fd6cdaaf2029f82b68338abf1346fe', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
INSERT INTO card_sets (set_name, card_id) VALUES ('ブースターパック「ディーヴァフィーバー」', '1877');
INSERT INTO cards_fts (rowid, card_number, text) VALUES (1877, 'hBP07-091', 'hBP07-091 海原カイロ ライブスタッフ このカードは、自分のステージのエール1枚をアーカイブしなければ使えない。
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('2003', 'hBP07-091', 'supportStaff', 'S', NULL, 'hBP07/hBP07-091_S', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP07/hBP07-091_S.png', NULL, NULL, NULL, NULL, '海原カイロ', 'ライブスタッフ', '{"card_sets":["ブースターパック「ディーヴァフィーバー」"],"translations":{"en":{"ability_text":"You can’t use this card unless you archive 1 Cheer card from your Stage.\n\nAttach 1 Fan card from your Archive to one of your Holomen. If you do, return 1 Holomen card from your Archive to your hand.","name":"ライブスタッフ"},"es":{"ability_text":"No puedes usar esta carta a menos que archives 1 carta de Apoyo en tu escenario.\n\nAdjunta 1 carta de Fan de tu archivo a uno de tus Holomen. Si lo haces, devuelve 1 carta de Holomen de tu archivo a tu mano.","name":"ライブスタッフ"},"id":{"ability_text":"Kartu ini hanya bisa digunakan jika kamu mengarsipkan 1 kartu Sorakan di panggungmu.\n\nPasang 1 kartu Penggemar dari arsipmu ke salah satu Holomen kamu. Jika kamu melakukannya, kembalikan 1 kartu Holomen dari arsipmu ke tanganmu.","name":"Staf Live"},"ja":{"ability_text":"このカードは、自分のステージのエール1枚をアーカイブしなければ使えない。\n\n自分のアーカイブのファン1枚を自分のホロメンに付ける。付けたなら、自分のアーカイブのホロメン1枚を手札に戻す。","name":"ライブスタッフ"},"ko":{"ability_text":"이 카드는 자신의 스테이지에 있는 응원 1장을 아카이브하지 않으면 사용할 수 없다.\n\n자신의 아카이브에 있는 팬 1장을 자신의 홀로멤버에게 붙인다. 그렇게 했다면, 자신의 아카이브에 있는 홀로멤버 1장을 패로 되돌린다.","name":"ライブスタッフ"},"tc":{"ability_text":"要使用此卡，必須將自己舞台上的1張「應援」存入檔案區域。\n\n將自己檔案區域中的1張「粉絲」附加到自己的「成員」上。若已附加，則將自己檔案區域中的1張「成員」返回手牌。","name":"Live Staff"},"th":{"ability_text":"การ์ดใบนี้ไม่สามารถใช้ได้ เว้นแต่จะอาร์ไคฟ์เอนด์ 1 ใบจากสเตจของตนเอง\n\nนำแฟน 1 ใบจากอาร์ไคฟ์ของตัวเองมาติดกับโฮโลเมンของตน ถ้าทำเช่นนั้น ให้นำโฮโลเมน 1 ใบจากอาร์ไคฟ์ของตนกลับเข้ามือ","name":"ライブスタッフ"}}}', '{}', 'cdcefdd9dd5367bd4df0f1e42666065d7b111ba934554c9a36cd29b4b86baba0', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
INSERT INTO card_sets (set_name, card_id) VALUES ('ブースターパック「ディーヴァフィーバー」', '2003');
INSERT INTO cards_fts (rowid, card_number, text) VALUES (2003, 'hBP07-091', 'hBP07-091 海原カイロ ライブスタッフ このカードは、自分のステージのエール1枚をアーカイブしなければ使えない。
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('2138', 'hBP03-044', 'character', 'SR', 'first', 'hCO01/hBP03-044_SR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hCO01/hBP03-044_SR.png', 150, NULL, 1, '["null"]', 'Mika Pikazo', '星街すいせい', '{"arts":[{"cost_count":2,"cost_types":["blue","null"],"damage":40}],"card_sets":["オフィシャルホロカコレクション-2025ライブセット-"],"color_codes":["blue"],"keyword":{"type":"ブルームエフェクト","type_code":"bloom_effect"},"translations":{"en":{"arts":[{"effect":"If your oshimen Holomen is 〈星街すいせい〉, you may move 1 blue Yell card from this Holomen to your backline Holomen 〈星街すいせい〉.","name":"Virtual Ghost"}],"keyword":{"effect":"Look at the top 4 cards of your deck. You may reveal 1 〈星街すいせい〉 card from among them and add it to your hand. Then, put the remaining cards on the bottom of your deck in any order.","name":"Planet Stage"},"name":"星街すいせい","tags":["#JP","#0期生","#歌"]},"es":{"arts":[{"effect":"Si tu Holomen favorita es 〈星街すいせい〉, puedes transferir una carta de Aplauso Azul de esta Holomen a tu Holomen de respaldo 〈星街すいせい〉.","name":"バーチャルゴースト"}],"keyword":{"effect":"Mira las 4 cartas superiores de tu mazo. Revela una carta de 〈星街すいせい〉 entre ellas y añádela a tu mano. Coloca el resto de las cartas en la parte inferior del mazo en el orden que prefieras.","name":"プラネットステージ"},"name":"星街すいせい","tags":["#JP","#0期生","#歌"]},"id":{"arts":[{"effect":"Jika oshi Holomen-mu adalah 〈星街すいせい〉, kamu dapat memindahkan 1 kartu Aerial biru dari Holomen ini ke 〈星街すいせい〉 yang ada di Holomen belakangmu.","name":"バーチャルゴースト"}],"keyword":{"effect":"Lihat 4 kartu teratas dari dekmu. Perlihatkan 1 kartu 〈星街すいせい〉 dari antara kartu tersebut, lalu tambahkan ke tanganmu. Kemudian, kembalikan sisa kartu ke bagian bawah dek dalam urutan yang kamu pilih.","name":"プラネットステージ"},"name":"星街すいせい","tags":["#JP","#0期生","#歌"]},"ja":{"arts":[{"effect":"自分の推しホロメンが〈星街すいせい〉の時、このホロメンの青エール1枚を、自分のバックホロメンの〈星街すいせい〉に付け替えられる。","name":"バーチャルゴースト"}],"keyword":{"effect":"自分のデッキの上から4枚を見る。その中から、〈星街すいせい〉1枚を公開し、手札に加える。そして残ったカードを好きな順でデッキの下に戻す。","name":"プラネットステージ"},"name":"星街すいせい","tags":["#JP","#0期生","#歌"]},"ko":{"arts":[{"effect":"내 오시 홀로멘이 〈星街すいせい〉일 때, 이 홀로멘의 파란 응원 1장을 내 백 홀로멘인 〈星街すいせい〉에게 옮겨 붙일 수 있다.","name":"バーチャルゴースト"}],"keyword":{"effect":"내 덱 위에서 카드 4장을 본다. 그중에서 〈星街すいせい〉 1장을 공개하고 패에 넣는다. 남은 카드는 원하는 순서로 덱 아래에 되돌린다.","name":"プラネットステージ"},"name":"星街すいせい","tags":["#JP","#0期生","#歌"]},"tc":{"arts":[{"effect":"當你的應援成員是〈星街すいせい〉時，可以將此成員的1張藍色應援卡，改附加到你後場成員中的〈星街すいせい〉上。","name":"バーチャルゴースト"}],"keyword":{"effect":"從自己的牌庫上方查看4張牌，公開其中1張〈星街すいせい〉並加入手牌。然後將剩下的牌以任意順序放回牌庫底。","name":"プラネットステージ"},"name":"星街すいせい","tags":["#JP","#0期生","#歌"]},"th":{"arts":[{"effect":"ถ้าโฮโลเมนที่เชียร์อยู่เป็น〈星街すいせい〉 สามารถย้ายการ์ดเอลสีน้ำเงิน 1 ใบจาก〈星街すいせい〉ที่อยู่ด้านหน้า ไปติดกับ〈星街すいせい〉ที่อยู่ในโฮโลเมนหลังของตัวเองได้","name":"バーチャルゴースト"}],"keyword":{"effect":"ดูการ์ด 4 ใบจากด้านบนสุดของเด็คของตนเอง เผย〈星街すいせい〉 1 ใบจากในนั้นแล้วเพิ่มเข้ามือ จากนั้นนำการ์ดที่เหลือใส่กลับไปใต้เด็คในลำดับที่ต้องการ","name":"プラネットステージ"},"name":"星街すいせい","tags":["#JP","#0期生","#歌"]}}}', '{}', '8e63713316d20360acbf6086b34f11b86fba511a6c2a0740bdc5acf68ce885f4', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
