INSERT INTO cards_fts (rowid, card_number, text) VALUES (2139, 'hBP03-055', 'hBP03-055 花澤明 JP 4期生 歌 シューター 常闇トワ #JP #4期生 #歌 #シューター トワとお家デートしたっていい てんQ 自分の#歌を持つバックホロメンがいる時、相手のコラボホロメンに特殊ダメージ20を与える。 常闇トワ #JP #4期生 #歌 #シューター トワとお家デートしたっていい てんQ If you have a backup Holomem with #歌, deal 20 special damage to an opponent’s collab Holomem. 常闇トワ #JP #4期生 #歌 #シューター 能和トワ來場在家的約會也沒問題 てんQ 當自己的備援區有持有#歌的Holomen時，對對手的合作Holomen造成20點特殊傷害。 常闇トワ #JP #4期生 #歌 #シューター トワとお家デートしたっていい てんQ Kalau ada anggota holo pendukung milikmu yang punya tag #歌, berikan 20 damage khusus ke anggota holo kolaborasi lawan. 常闇トワ #JP #4期生 #歌 #シューター トワとお家デートしたっていい てんQ 자신의 #노래를 가진 백업 홀로멘이 있을 때, 상대 콜라보 홀로멘에게 특수 데미지 20을 준다. 常闇トワ #JP #4期生 #歌 #シューター トワとお家デートしたっていい てんQ ถ้ามีแบ็คโฮโลเมมเบอร์ที่มีแท็ก #歌 อยู่ฝ่ายตน จะสร้างความเสียหายพิเศษ 20 แก่โฮโลเมมเบอร์คอลแลปของฝั่งตรงข้าม 常闇トワ #JP #4期生 #歌 #シューター Trato de cita en casa con Towa está bien てんQ Cuando tienes un holo compañero de respaldo con #歌, inflige 20 de daño especial al holo colaborador del oponente.');
