INSERT INTO cards_fts (rowid, card_number, text) VALUES (2263, 'hBP08-060', 'hBP08-060 兎未枝 EN Advent ケモミミ FUWAMOCO #EN #Advent #ケモミミ このホロメンは〈フワワ・アビスガード〉〈モココ・アビスガード〉としても扱う いっしょういっしょ♡ 自分の推しホロメンが青の〈FUWAMOCO〉なら、自分のデッキの上から1枚をホロパワーにする。 “BAU” DOL♡ [コラボポジション限定]自分の推しスキル「モコちゃん！」の[ホロパワー:-3]を[ホロパワー:-2]に変更する。 FUWAMOCO #EN #Advent #ケモミミ This holomem is also treated as 〈Fuwawa Abyssgard〉 and 〈Mococo Abyssgard〉. いっしょういっしょ♡ If your oshi holomem is a blue 〈FUWAMOCO〉, put the top card of your deck into your Holopower area. “BAU” DOL♡ [Collab Position Only] Change the [Holopower:-3] cost of your oshi skill “Moco-chan!” to [Holopower:-2]. FUWAMOCO #EN #Advent #ケモミミ 此Holomen同時視為〈フワワ・アビスガード〉與〈モココ・アビスガード〉 いっしょういっしょ♡ 若自己的推しHolomen是藍色的〈FUWAMOCO〉，則將自己牌庫上方1張卡轉為Holo Power。 “BAU” DOL♡ [僅限合作位置]將自己推し技能「モコちゃん！」的[Holo Power:-3]改為[Holo Power:-2]。 FUWAMOCO #EN #Advent #ケモミミ Holomen ini juga dianggap sebagai 〈フワワ・アビスガード〉 dan 〈モココ・アビスガード〉. いっしょういっしょ♡ Jika oshi Holomen-mu adalah 〈FUWAMOCO〉 berwarna biru, ubah 1 kartu teratas dari deck-mu menjadi Holo Power. “BAU” DOL♡ [Hanya untuk posisi kolaborasi] Ubah efek skill oshi-mu 「モコちゃん！」 dari [Holo Power:-3] menjadi [Holo Power:-2]. FUWAMOCO #EN #Advent #ケモミミ 이 홀로멘은 〈フワワ・アビスガード〉와 〈モココ・アビスガード〉로도 취급한다. いっしょういっしょ♡ 내 오시 홀로멘이 파란색 〈FUWAMOCO〉라면, 내 덱 맨 위의 카드 1장을 홀로파워로 둔다. “BAU” DOL♡ [콜라보 포지션 한정] 내 오시 스킬 「モコちゃん！」의 [홀로파워:-3]을 [홀로파워:-2]로 변경한다. FUWAMOCO #EN #Advent #ケモミミ โฮโลเมมเบอร์นี้ยังถือว่าเป็น〈フワワ・アビスガード〉และ〈モココ・アビスガード〉ด้วย いっしょういっしょ♡ ถ้าโฮโลเมมเบอร์ที่ชอบของคุณเป็น〈FUWAMOCO〉สีน้ำเงิน ให้นำการ์ด 1 ใบจากด้านบนสุดของเด็คตัวเองไปไว้ในพลังโฮโล “BAU” DOL♡ [จำกัดตำแหน่งคอลแลบ] เปลี่ยน[โฮโลพลัง:-3]ของสกิลที่ชอบของตัวเองชื่อ 「モコちゃん！」 เป็น [โฮโลพลัง:-2] FUWAMOCO #EN #Advent #ケモミミ Este holomen también se considera como〈フワワ・アビスガード〉y〈モココ・アビスガード〉. いっしょういっしょ♡ Si tu holo favorito es un〈FUWAMOCO〉azul, convierte la carta superior de tu mazo en Holopoder. “BAU” DOL♡ [Solo en posición de colaboración] Cambia el [Holopoder:-3] de tu habilidad favorita «モコちゃん！» a [Holopoder:-2].');
INSERT INTO cards (id, card_number, card_type_code, rarity_code, bloom_level_code, image_key, source_image_url, hp, life, baton_touch_count, baton_touch_types, illustrator, name_ja, payload, qa_payload, content_hash, qa_hash, seeded_at) VALUES ('2444', 'hBP01-028', 'character', 'HR', 'debut', 'hBP08/hBP01-028_HR', 'https://hololive-official-cardgame.com/wp-content/images/cardlist/hBP08/hBP01-028_HR.png', 100, NULL, 1, '["null"]', 'がり', 'IRyS', '{"arts":[{"cost_count":1,"cost_types":["null"],"damage":30}],"card_sets":["ブースターパック バウンサーバウンド"],"color_codes":["white"],"translations":{"en":{"arts":[{"name":"ハイRyS！"}],"extra":"You can include any number of this Holomem in your deck.","name":"IRyS","tags":["#EN","#Promise","#歌"]},"es":{"arts":[{"name":"ハイRyS！"}],"extra":"Puedes incluir cualquier cantidad de esta holomem en tu mazo.","name":"IRyS","tags":["#EN","#Promise","#歌"]},"id":{"arts":[{"name":"ハイRyS！"}],"extra":"Holomen ini bisa dimasukkan ke dalam dek dengan jumlah berapa pun.","name":"IRyS","tags":["#EN","#Promise","#歌"]},"ja":{"arts":[{"name":"ハイRyS！"}],"extra":"このホロメンはデッキに何枚でも入れられる","name":"IRyS","tags":["#EN","#Promise","#歌"]},"ko":{"arts":[{"name":"하이RyS！"}],"extra":"이 홀로멤은 덱에 몇 장이든 넣을 수 있다","name":"IRyS","tags":["#EN","#Promise","#歌"]},"tc":{"arts":[{"name":"ハイRyS！"}],"extra":"此成員可在牌組中放入任意張數","name":"IRyS","tags":["#EN","#Promise","#歌"]},"th":{"arts":[{"name":"ハイRyS！"}],"extra":"โฮโลเมมเบอร์นี้สามารถใส่ได้ไม่จำกัดจำนวนในเด็ค","name":"IRyS","tags":["#EN","#Promise","#歌"]}}}', '{}', '59c020f3ca7b972ca3b56b777a52e71187c5a320a83fe86fd4ec013a87b38162', '44136fa355b3678a1146ad16f7e8649e94fb4fc21fe77e8310c060f61caaff8a', '1970-01-01T00:00:00Z');
