INSERT INTO cards_fts (rowid, card_number, text) VALUES (2444, 'hBP01-028', 'hBP01-028 がり EN Promise 歌 IRyS #EN #Promise #歌 このホロメンはデッキに何枚でも入れられる ハイRyS！ IRyS #EN #Promise #歌 You can include any number of this Holomem in your deck. ハイRyS！ IRyS #EN #Promise #歌 此成員可在牌組中放入任意張數 ハイRyS！ IRyS #EN #Promise #歌 Holomen ini bisa dimasukkan ke dalam dek dengan jumlah berapa pun. ハイRyS！ IRyS #EN #Promise #歌 이 홀로멤은 덱에 몇 장이든 넣을 수 있다 하이RyS！ IRyS #EN #Promise #歌 โฮโลเมมเบอร์นี้สามารถใส่ได้ไม่จำกัดจำนวนในเด็ค ハイRyS！ IRyS #EN #Promise #歌 Puedes incluir cualquier cantidad de esta holomem en tu mazo. ハイRyS！');
